var QUESTIONS = [{"id":1,"type":"single","stem":"学分学费每学年末根据实际修读学分结算一次，毕业时按实际修读学分多退少补，学生实际修读学分超过所属专业毕业要求总学分（）学分（不含）以上的，应补交超出的学分学费。","options":[["A","2"],["B","3"],["C","5"],["D","10"]],"answer":["C"],"source":"《中国石油大学（华东）学分制收费管理暂行办法》","category":"学分制收费","excerpt":"第十条学生毕业清算时，对实际修读学分超过所属专业毕业要求总学分5个学分以内（含5个学分）部分，学校可适当予以减免学分学费（具体政策以毕业当年学校公布优惠政策为准）；超过毕业要求总学分5个学分以上部分，学生应正常缴纳学分学费。"},{"id":2,"type":"single","stem":"考试时，要按规定时间提前15分钟入场，按（）就座。","options":[["A","个人意愿"],["B","监考人员安排"],["C","学号"],["D","以上皆可"]],"answer":["B"],"source":"中国石油大学（华东）学生考试工作管理规定（修订）","category":"考试管理","excerpt":"第二十八条考生要严格遵守考场规则，在规定的时间内独立完成答卷。凡不服从监考人员安排，违反考试纪律或作弊者，按学校有关规定处理。第八章考试违纪、作弊的认定及处理第二十九条考生有下列情况之一者，视为违反考试纪律，要当场给予口头警告并予以纠正：（一）未按考场规则就座；（二）闭卷考试至发试卷时仍将规定以外物品等带入座位；（三）自带空白答题纸或草稿纸；（四）未经监考人员允许借用他人的书、笔记、资料、计算器等物品；（五）考试中东张西望，企图偷看他人试卷；（六）交卷后仍在考场逗留或在考场附近大声喧哗；（七）将试卷、答题卡、答题纸、草稿纸等带出考场。对具有上述任意一种行为，无视警告且不纠正者，取消考试资格，该门课程总成绩以零分记。"},{"id":3,"type":"single","stem":"考试迟到（）分钟，禁止入场。","options":[["A","10"],["B","15"],["C","20"],["D","30"]],"answer":["D"],"source":"中国石油大学（华东）学生考试工作管理规定（修订）","category":"考试管理","excerpt":"第二十四条监考人员须严格遵守教学纪律，认真履行监考职责，自始至终维持好考场秩序。对不认真履行职责者，按学校有关规定处理。第七章考试纪律第二十五条考生要按规定的考试时间提前15分钟进入考场，按照监考人员的安排就座；将有效证件放在桌面，无有效证件者不准参加考试。迟到30分钟以上和无故不参加考试者，按“缺考”处理。开考30分钟后，准予交卷出场。未交卷且未经监考人员允许擅自离开考场者，不得重新进入考场。考生交卷后应离开考场，不得在考场内逗留或在考场附近大声喧哗。"},{"id":4,"type":"single","stem":"考试开考（）分钟后，可以交卷出场。","options":[["A","15"],["B","20"],["C","30"],["D","60"]],"answer":["C"],"source":"中国石油大学（华东）学生考试工作管理规定（修订）","category":"考试管理","excerpt":"第二十四条监考人员须严格遵守教学纪律，认真履行监考职责，自始至终维持好考场秩序。对不认真履行职责者，按学校有关规定处理。第七章考试纪律第二十五条考生要按规定的考试时间提前15分钟进入考场，按照监考人员的安排就座；将有效证件放在桌面，无有效证件者不准参加考试。迟到30分钟以上和无故不参加考试者，按“缺考”处理。开考30分钟后，准予交卷出场。未交卷且未经监考人员允许擅自离开考场者，不得重新进入考场。考生交卷后应离开考场，不得在考场内逗留或在考场附近大声喧哗。"},{"id":5,"type":"single","stem":"独立设置的实验（上机）课程，缺做实验（）或缺交实验报告（）及以上者，成绩以零分记载。","options":[["A","1/3，2/3"],["B","1/3，1/3"],["C","2/3，2/3"],["D","2/3，1/3"]],"answer":["B"],"source":"《中国石油大学（华东）本科实验教学管理办法》","category":"实验教学与实习","excerpt":"第十九条独立设置的实验（上机）课程，缺做实验1/3或缺交实验报告1/3及以上者，成绩以零分记载。"},{"id":6,"type":"single","stem":"关于大学生创新创业训练计划的以下哪种说法是正确的（）。","options":[["A","一人可以同时担任多个在研项目的负责人"],["B","一人只能担任一个在研项目的负责人，但可以作为多个在研项目的成员"],["C","一人只能参与一个在研项目，无论是负责人还是成员"],["D","一人只能担任一个在研项目的负责人，同时可以作为另一个在研项目的成员"]],"answer":["C"],"source":"《中国石油大学（华东）大学生创新创业训练计划项目管理办法》","category":"创新创业","excerpt":""},{"id":7,"type":"single","stem":"参加实习或缺勤（包括病、事假）累计达实习总时间（）及以上的，实习成绩为不及格。","options":[["A","1/2"],["B","1/3"],["C","1/4"],["D","1/5"]],"answer":["B"],"source":"《中国石油大学（华东）本科实习教学管理办法》","category":"实验教学与实习","excerpt":"第四十条有下列情形之一者，不得参加课程考核：（1）不参加实习或缺勤（包括病、事假等）累计达到实习总时间1/3的；（2）实习中有违纪行为，经教育不改，或有严重违纪行为的；（3）其他经认定不能参加考核的情形。第八章质量保障第四十一条教学院部是本单位实习教学质量的责任单位，应建立实习教学过程质量监控机制，明确实习各主要教学环节的质量要求，强化实习过程管理，确保实习课程目标的达成。"},{"id":8,"type":"single","stem":"学校对在校本科生获得授权的发明专利奖励金额是多少","options":[["A","5000"],["B","4000"],["C","3000"],["D","2000"]],"answer":["C"],"source":"《中国石油大学（华东）本科生创新成果奖励办法》","category":"学科竞赛","excerpt":""},{"id":9,"type":"single","stem":"在校生应在（）按学校规定缴纳学费，并在每学期（夏季小学期除外）开学后1周内办理学籍注册手续，取得本学期的学习资格。","options":[["A","每学期初"],["B","每学年初"],["C","每学期末"],["D","以上任意时间"]],"answer":["B"],"source":"《中国石油大学（华东）本科生学籍管理规定》","category":"学籍管理","excerpt":"第八条在校生应在每学年初按学校规定缴纳学费，并在每学期（夏季小学期除外）开学后1周内办理学籍注册手续，取得本学期的学习资格。未按照学校规定缴纳学费、超过最长学习年限或者其他不符合注册条件的，不予注册。因故不能如期注册的，须履行暂缓注册手续。逾期2周不办理注册手续者，按照退学处理。家庭经济困难的学生可以申请助学贷款或者其他形式资助，办理有关手续后注册。第三章学习纪律与考勤第九条学生须严格遵守学校教育教学相关规章制度，对违反纪律的学生，根据学校学生纪律处分相关规定处理。"},{"id":10,"type":"single","stem":"凡结课（含免修）考核不及格的课程,可通过重新选课修读或补考取得该课程的学分。考核成绩合格,但成绩不理想的课程,也可重新选课修读。在学校规定的最长学习年限内,重新选课修读（）。","options":[["A","最多不超过3次"],["B","最多不超过4次"],["C","最多不超过5次"],["D","不限制次数"]],"answer":["D"],"source":"《中国石油大学（华东）本科生学籍管理规定》","category":"学籍管理","excerpt":"第十七条凡结课（含免修）考核不及格的课程，可通过重新选课修读或补考取得该课程的学分。考核成绩合格，但成绩不理想的课程，也可重新选课修读。1.在学校规定的最长学习年限内，重新选课修读不限制次数，所有修读成绩均如实记载；2.补考时间为每学期的开学初，补考课程为前一学期考核不及格的必修或限选课程，且申请补考的课程成绩必须达50分（含）以上；3.实验课程、实习实训、毕业设计等实践性教学环节以及无结课考核环节的课程不能补考；4.学生补考及格获得该课程学分，补考不及格须重新选课修读。"},{"id":11,"type":"single","stem":"学生退学后（）重新参加普通高等学校招生全国统一考试,被学校录取并取得学籍的,其已获得学分,经学校认定符合相关专业本科培养方案要求,可予以承认。","options":[["A","1年内"],["B","2年内"],["C","3年内"],["D","5年内"]],"answer":["B"],"source":"《中国石油大学（华东）本科生学籍管理规定》","category":"学籍管理","excerpt":"第二十四条学生因退学等情况中止学业，其在校学习期间所修课程及已获得学分，予以记录。学生退学后2年内重新参加普通高等学校招生全国统一考试，被学校录取并取得学籍的，其已获得学分，经学校认定符合相关专业本科培养方案要求，可予以承认。第五章转学与转专业第二十五条学生入学后，一般不予转学。如因患病或者确有特殊困难和需要，无法继续在校学习者或不适应学校学习要求的，可以申请转学。"},{"id":12,"type":"single","stem":"因学业成绩不良达到退学情形者,可申请试读,试读期为（）,试读期间享受在校生待遇。","options":[["A","半年"],["B","1年"],["C","2年"],["D","不限"]],"answer":["B"],"source":"《中国石油大学（华东）本科生学籍管理规定》","category":"学籍管理","excerpt":"第四十二条因学业成绩不良达到退学情形者，可申请试读，试读期为1年，试读期间享受在校生待遇。试读期满已选必修课程中累计未取得学分数不超过15学分者，试读合格；试读期满不合格者，须办理退学手续。学生在校学习期间，只能试读1次。试读合格者，若已选必修课程中累计未取得学分数再次达到25学分者，予以退学。"},{"id":13,"type":"single","stem":"学生结业后（）之内回校完成相关课程修读,达到本科培养方案规定的学分要求的,学校准予毕业,符合学士学位授予标准的,授予学士学位。","options":[["A","1年"],["B","2年"],["C","3年"],["D","5年"]],"answer":["A"],"source":"《中国石油大学（华东）本科生学籍管理规定》","category":"学籍管理","excerpt":"第四十六条学生毕业时未修满本科培养方案规定的学分要求，可申请延长学习年限或结业。1.延长学习年限（1）延长学习年限应由学生本人提出申请，所在院部审核批准后报教务处备案，但其累计在校时间不能超过学校规定的最长学习年限；（2）延长学习年限的学生，享受在校生待遇。2.结业（1）毕业时累计欠本科培养方案规定的学分要求15学分以内（含15学分）的学生，经本人申请，所在院部审核，学校批准后，可办理结业手续；（2）学生结业后1年之内回校完成相关课程修读，达到本科培养方案规定的学分要求的，学校准予毕业，符合学士学位授予标准的，授予学士学位。合格后颁发的毕业证书、学位证书，毕业时间、获学位时间按发证日期填写；（3）学生结业1年后仍未达到本科培养方案规定的学分要求的，不再换发毕业证书。"},{"id":14,"type":"single","stem":"学生毕业时未完成本科培养方案规定的学分要求,所欠学分超过（）学分且未申请延长学习年限的,按肄业处理。","options":[["A","10"],["B","15"],["C","20"],["D","25"]],"answer":["B"],"source":"《中国石油大学（华东）本科生学籍管理规定》","category":"学籍管理","excerpt":"第四十七条学生毕业时未完成本科培养方案规定的学分要求，所欠学分超过15学分且未申请延长学习年限的，按肄业处理。肄业处理流程参照退学办理。第九章学业证书第四十八条学校严格按照招生时确定的办学类型和学习形式，以及学生招生录取时填报的个人信息，填写、颁发学历证书、学位证书及其他学业证书。学生在校期间申请变更姓名、出生日期等证书需填写的个人信息的，应当有合理、充分的理由，并提供有法定效力的相应证明文件，经学校审查通过后，可予以修改。"},{"id":15,"type":"single","stem":"学生申请免修、免听课程每学期一般不超过（）门。","options":[["A","1"],["B","2"],["C","3"],["D","4"]],"answer":["B"],"source":"《中国石油大学（华东）本科生学籍管理规定》","category":"学籍管理","excerpt":"……第十五条1.课程免修（1）学生对本科培养方案规定的课程通过自学等途径确已掌握，可以申请免修；（2）学生申请免修原则上应在学期初2周内向开课院部提出申请；（3）开课院部根据课程学习要求等情况，决定是否接受免修申请。同意免修的，由开课院部确定课程的考核方式、考核内容、评价标准等报教务处审批。批准通过的，由教务处统一组织考核；（4）免修课程成绩按考核成绩如实记载，考核成绩不及格的，免修当学期不得再次申请修读该门课程。2.课程免听（1）学生因拟选修课程上课时间冲突等，可以申请课程免听，自学该门课程，达到课程相关教学要求；（2）学生申请免听应在课程开始后2周内提交，并征得任课教师同意，开课院部批准后，报教务处备案；（3）经批准免听的课程，学生须完成任课教师给定的课程学习任务，方可参加该课程的结课考核。3.思想政治理论课、体育课、通识教育选修课、包含实验环节的课程、独立实验课、军训、实习、毕业设计（论文）以及其他须随堂修读的课程，均不得申请免修、免听。4.学生申请免修、免听课程每学期一般不超过2门。"},{"id":16,"type":"single","stem":"学生申请免听应在课程开始后（）内提交,并征得任课教师同意,开课院部批准后,报教务处备案。","options":[["A","4周"],["B","3周"],["C","2周"],["D","1周"]],"answer":["C"],"source":"《中国石油大学（华东）本科生学籍管理规定》","category":"学籍管理","excerpt":"……第十五条1.课程免修（1）学生对本科培养方案规定的课程通过自学等途径确已掌握，可以申请免修；（2）学生申请免修原则上应在学期初2周内向开课院部提出申请；（3）开课院部根据课程学习要求等情况，决定是否接受免修申请。同意免修的，由开课院部确定课程的考核方式、考核内容、评价标准等报教务处审批。批准通过的，由教务处统一组织考核；（4）免修课程成绩按考核成绩如实记载，考核成绩不及格的，免修当学期不得再次申请修读该门课程。2.课程免听（1）学生因拟选修课程上课时间冲突等，可以申请课程免听，自学该门课程，达到课程相关教学要求；（2）学生申请免听应在课程开始后2周内提交，并征得任课教师同意，开课院部批准后，报教务处备案；（3）经批准免听的课程，学生须完成任课教师给定的课程学习任务，方可参加该课程的结课考核。"},{"id":17,"type":"single","stem":"对于本科培养方案规定的实践性教学环节和学校规定必须参加的其他各项教学活动,无故缺席的,按每天（）学时计旷课。","options":[["A","5"],["B","6"],["C","7"],["D","8"]],"answer":["B"],"source":"《中国石油大学（华东）本科生学籍管理规定》","category":"学籍管理","excerpt":""},{"id":18,"type":"single","stem":"专业注册学费是指以不同专业的（）为基础，对不同专业收取的年度学费。","options":[["A","生均培养成本"],["B","专业建设需求"],["C","学生承受能力"],["D","家庭承受能力"]],"answer":["A"],"source":"《中国石油大学（华东）学分制收费管理暂行办法》","category":"学分制收费","excerpt":"第四条本办法所称学分制收费，是按照专业注册学费和学分学费两部分计收学费的收费管理制度。学分制收费执行政府定价或政府指导价。第二章收费项目及标准第五条专业注册学费是学生进行专业学习注册取得专业课程选修资格需缴纳的费用。专业注册学费由学校按照不同专业生均培养成本等因素合理确定。专业注册学费按学年计收。学校在每学年初向学生收取专业注册学费，为学生办理专业注册手续，授予学生本学年选课资格。学校按照学生实际修业年限收取专业注册学费。"},{"id":19,"type":"single","stem":"学分学费按学生修读学分计收，学分收费标准为每学分（）元。","options":[["A","30"],["B","50"],["C","100"],["D","200"]],"answer":["C"],"source":"《中国石油大学（华东）学分制收费管理暂行办法》","category":"学分制收费","excerpt":""},{"id":20,"type":"single","stem":"学生毕业时，按照多退少补原则结算学费，学生实际修读学分超过所属专业毕业要求总学分（），应补交超出的学分学费。","options":[["A","＞5学分"],["B","≥5学分"],["C","＞3学分"],["D","≥3学分"]],"answer":["A"],"source":"《中国石油大学（华东）学分制收费管理暂行办法》","category":"学分制收费","excerpt":"第十条学生毕业清算时，对实际修读学分超过所属专业毕业要求总学分5个学分以内（含5个学分）部分，学校可适当予以减免学分学费（具体政策以毕业当年学校公布优惠政策为准）；超过毕业要求总学分5个学分以上部分，学生应正常缴纳学分学费。"},{"id":21,"type":"single","stem":"学生费用清缴次序为（）。①代收费；②专业注册学费；③住宿费；④学分学费。","options":[["A","①②③④"],["B","①③②④"],["C","①④③②"],["D","①③④②"]],"answer":["B"],"source":"《中国石油大学（华东）学分制收费管理暂行办法》","category":"学分制收费","excerpt":""},{"id":22,"type":"single","stem":"双学位专业学制为（）年。","options":[["A","1"],["B","2"],["C","3"],["D","4"]],"answer":["C"],"source":"《中国石油大学（华东）本科生双学位培养管理办法》","category":"双学位与辅修","excerpt":""},{"id":23,"type":"single","stem":"学生原则上从第（）学期进入双学位专业学习。","options":[["A","1"],["B","2"],["C","3"],["D","5"]],"answer":["C"],"source":"《中国石油大学（华东）本科生双学位培养管理办法》","category":"双学位与辅修","excerpt":""},{"id":24,"type":"single","stem":"学生修读的双学位专业应属于（）。","options":[["A","同一学科门类"],["B","不同学科门类"],["C","相近学科门类"],["D","交叉学科门类"]],"answer":["B"],"source":"《中国石油大学（华东）本科生双学位培养管理办法》","category":"双学位与辅修","excerpt":"……二、4.双学士学位双学士学位指学生在学习期间同时完成两个不同学科门类专业的系统学习，达到培养要求后，获得一本有两个学位标注的学位证书。"},{"id":25,"type":"single","stem":"修读双学位的学生，获得主修专业学位但达不到双学位专业和教学培养方案要求的，若所修双学位课程的总学分（）学分者，颁发辅修专业证书。","options":[["A","≥25"],["B","≥30"],["C","≥32"],["D","≥35"]],"answer":["B"],"source":"《中国石油大学（华东）本科生双学位培养管理办法》","category":"双学位与辅修","excerpt":""},{"id":26,"type":"single","stem":"修读双学位的学生，获得主修专业学位但达不到双学位专业和教学培养方案要求的，低于（）学分者，其所修双学位课程作为通识教育选修课记入《中国石油大学（华东）学生成绩记载表》。","options":[["A","20"],["B","25"],["C","30"],["D","35"]],"answer":["C"],"source":"《中国石油大学（华东）本科生双学位培养管理办法》","category":"双学位与辅修","excerpt":""},{"id":27,"type":"single","stem":"申请辅修专业的学生，须在第（）学期初提出申请。","options":[["A","3"],["B","4"],["C","5"],["D","6"]],"answer":["C"],"source":"《中国石油大学（华东）本科生辅修培养管理办法》","category":"双学位与辅修","excerpt":""},{"id":28,"type":"single","stem":"辅修专业培养方案由辅修专业开设院部制定，所设课程应是本专业基础课程和专业课，总学分一般为（）左右。","options":[["A","20"],["B","25"],["C","30"],["D","35"]],"answer":["C"],"source":"《中国石油大学（华东）本科生辅修培养管理办法》","category":"双学位与辅修","excerpt":""},{"id":29,"type":"single","stem":"每学期开学后（）内，辅修专业的学生须到辅修专业开设院部办理课程修读手续,并按照本学期所选修课程学分缴纳学费。","options":[["A","1周"],["B","2周"],["C","3周"],["D","4周"]],"answer":["B"],"source":"《中国石油大学（华东）本科生辅修培养管理办法》","category":"双学位与辅修","excerpt":""},{"id":30,"type":"single","stem":"对完成辅修专业培养方案所规定的学分者,颁发（）专业证书。","options":[["A","主修"],["B","辅修"],["C","主修和辅修"],["D","随便"]],"answer":["B"],"source":"《中国石油大学（华东）本科生辅修培养管理办法》","category":"双学位与辅修","excerpt":""},{"id":31,"type":"single","stem":"我校除建筑学专业以外的其他专业，创业休学学生的最长学习年限为（）年。","options":[["A","6"],["B","7"],["C","8"],["D","9"]],"answer":["C"],"source":"《中国石油大学（华东）本科生创新创业学籍管理办法（试行）》","category":"创新创业","excerpt":""},{"id":32,"type":"single","stem":"学生申请学分认定,应于每学期初（）向所在院（部）提出申请,并提供能体现创新创业实践过程及成果的支撑材料,经院（部）创新创业教育领导小组认定、学校创新创业教育工作领导小组办公室审定后,报学校备案。","options":[["A","2周内"],["B","3周内"],["C","1个月内"],["D","2个月内"]],"answer":["B"],"source":"《中国石油大学（华东）本科生创新创业学籍管理办法（试行）》","category":"创新创业","excerpt":"第十一条学生申请学分认定，应于每学期初3周内向所在院（部）提出申请，并提供能体现创新创业实践过程及成果的支撑材料，经院（部）创新创业教育领导小组认定、学校创新创业教育工作领导小组办公室审定后，报学校备案。必要时，由学校组织专家论证，通过者取得相应学分。因创业休学，未按时申请学分认定的，可复学后提出申请。"},{"id":33,"type":"single","stem":"学校优良学风标兵班的评选范围是（）。","options":[["A","全校除大一班级外的所有全日制本科生班级"],["B","全校除毕业班级外所有全日制本科生班级"],["C","全校所有全日制本科生班级"],["D","全校除新生班级、毕业班级以外的所有全日制本科生班级"]],"answer":["C"],"source":"《中国石油大学(华东)优良学风班评选办法》","category":"优良学风班","excerpt":"一、评选范围全校所有全日制本科生班级。"},{"id":34,"type":"single","stem":"评选优良学风班需具备的条件之一是：全班学生学习效果显著，各门必修课程考试及格率达（）。","options":[["A","0.85"],["B","0.9"],["C","0.95"],["D","1"]],"answer":["C"],"source":"《中国石油大学(华东)优良学风班评选办法》","category":"优良学风班","excerpt":"二、评选标准1.评选优良学风班需具备以下条件：（1）全班学生政治思想状况良好，拥护党的路线、方针、政策；（2）全班学生学习态度端正，学习目的明确，学习气氛浓厚；（3）全班学生遵守法纪，遵守《高等学校学生行为准则》和学校的各项规章制度；（4）班集体凝聚力强，开展集体活动效果良好；（5）全班学生学习效果显著：各门必修课程考试及格率达95%，优良率达60%，各种竞赛成绩和课外科技活动成果突出。2.优良学风标兵班从优良学风班中选出。3.符合以下任一项者不得申报或取消其当年评选资格：（1）凡班级有学生在评选当年受到学校处分者；（2）凡班级申报材料弄虚作假者，一经发现，取消其评奖资格，并不得参加下一年度的申报。"},{"id":35,"type":"single","stem":"优良学风标兵班从（）中选出。","options":[["A","优良学风班"],["B","先进班集体"],["C","红旗团支部"],["D","以上均可"]],"answer":["A"],"source":"《中国石油大学(华东)优良学风班评选办法》","category":"优良学风班","excerpt":"二、评选标准1.评选优良学风班需具备以下条件：（1）全班学生政治思想状况良好，拥护党的路线、方针、政策；（2）全班学生学习态度端正，学习目的明确，学习气氛浓厚；（3）全班学生遵守法纪，遵守《高等学校学生行为准则》和学校的各项规章制度；（4）班集体凝聚力强，开展集体活动效果良好；（5）全班学生学习效果显著：各门必修课程考试及格率达95%，优良率达60%，各种竞赛成绩和课外科技活动成果突出。2.优良学风标兵班从优良学风班中选出。3.符合以下任一项者不得申报或取消其当年评选资格：（1）凡班级有学生在评选当年受到学校处分者；（2）凡班级申报材料弄虚作假者，一经发现，取消其评奖资格，并不得参加下一年度的申报。"},{"id":36,"type":"single","stem":"下列哪一项属于学生公寓内可以使用的电器？","options":[["A","电热水壶"],["B","电褥子"],["C","电磁炉"],["D","电脑"]],"answer":["D"],"source":"《中国石油大学（华东）学生公寓管理规定》","category":"学生公寓","excerpt":""},{"id":37,"type":"single","stem":"下列选项哪一项不符合学生公寓室内卫生规范","options":[["A","卫生间异味"],["B","床面平整、洁净"],["C","桌面整洁"],["D","地面保持干净"]],"answer":["A"],"source":"《中国石油大学（华东）学生公寓管理规定》","category":"学生公寓","excerpt":""},{"id":38,"type":"single","stem":"保留入学资格由新生本人提出书面申请，并附相关证明材料（因病需提交校医院或校医院指定的二级甲等以上医院诊断证明），经学校批准，可保留入学资格（）。保留入学资格期间不具有学籍。","options":[["A","半年"],["B","1年"],["C","2年"],["D","3年"]],"answer":["B"],"source":"《中国石油大学（华东）本科生学籍管理规定》","category":"学籍管理","excerpt":"第六条新生因患病或者其他正当理由的，可申请保留入学资格。保留入学资格由新生本人提出书面申请，并附相关证明材料（因病需提交校医院或校医院指定的二级甲等以上医院诊断证明），经学校批准，可保留入学资格1年。保留入学资格期间不具有学籍。新生保留入学资格期满前应向学校申请入学，因病保留入学资格者须同时提交校医院或校医院指定的二级甲等以上医院出具的病愈证明，经学校审查合格后，办理入学手续。审查不合格的，取消入学资格；逾期不办理入学手续且未有因不可抗力延迟等正当理由的，视为放弃入学资格。"},{"id":39,"type":"single","stem":"学生有以下情形之一者，不得参加该课程的结课考核（免听课程除外）：1.累计缺课达到该课程计划学时的（）者；2.累计缺交作业（含抄袭作业）达到该门课程所有作业量的（）者；3.独立设置的实验（上机）课程，缺做实验学时或缺交实验报告达到（）者。","options":[["A","1/3；1/3；1/3"],["B","1/2；1/2；1/2"],["C","1/3；1/2；1/3"],["D","1/2；1/3；1/2"]],"answer":["A"],"source":"《中国石油大学（华东）本科生学籍管理规定》","category":"学籍管理","excerpt":"第十六条学生有以下情形之一者，不得参加该课程的结课考核（免听课程除外）：1.累计缺课达到该课程计划学时的1/3者；2.累计缺交作业（含抄袭作业）达到该门课程所有作业量的1/3者；3.独立设置的实验（上机）课程，缺做实验学时或缺交实验报告达到1/3者。"},{"id":40,"type":"single","stem":"（）是学生社团的最高权力机构，依照本社团的章程行使职权。","options":[["A","学生社团主席团"],["B","学生社团代表大会"],["C","学生社团会员大会"],["D","学生社团主席"]],"answer":["C"],"source":"中国石油大学（华东）学生社团管理办法","category":"学生社团","excerpt":""},{"id":41,"type":"single","stem":"凡我校本科生在取得本专业培养计划规定学分的同时,还需至少取得（）个自主发展计划学分。","options":[["A","5"],["B","10"],["C","15"],["D","20"]],"answer":["B"],"source":"中国石油大学(华东)本科生自主发展计划","category":"自主发展计划","excerpt":""},{"id":42,"type":"single","stem":"服务时间累计60小时以上者,计（）学分。","options":[["A","1"],["B","2"],["C","3"],["D","4"]],"answer":["B"],"source":"中国石油大学(华东)本科生自主发展计划","category":"自主发展计划","excerpt":""},{"id":43,"type":"single","stem":"实践时间累计4周以上者,计（）学分。","options":[["A","1"],["B","2"],["C","3"],["D","4"]],"answer":["B"],"source":"中国石油大学(华东)本科生自主发展计划","category":"自主发展计划","excerpt":""},{"id":44,"type":"single","stem":"社会实践模块累计不超过（）学分","options":[["A","4"],["B","5"],["C","6"],["D","3"]],"answer":["C"],"source":"中国石油大学(华东)本科生自主发展计划","category":"自主发展计划","excerpt":""},{"id":45,"type":"single","stem":"科技创新模块至少取得（）学分。","options":[["A","1"],["B","2"],["C","3"],["D","4"]],"answer":["B"],"source":"中国石油大学(华东)本科生自主发展计划","category":"自主发展计划","excerpt":""},{"id":46,"type":"single","stem":"学科竞赛获得校级奖励的计（）学分。","options":[["A","0.5"],["B","1"],["C","1.5"],["D","2"]],"answer":["D"],"source":"中国石油大学(华东)本科生自主发展计划","category":"自主发展计划","excerpt":""},{"id":47,"type":"single","stem":"积极参与学生社团活动,被评为校级以上优秀社团,核心成员（20人以内）计（）学分。","options":[["A","0.5"],["B","1"],["C","1.5"],["D","2"]],"answer":["D"],"source":"中国石油大学(华东)本科生自主发展计划","category":"自主发展计划","excerpt":""},{"id":48,"type":"single","stem":"校级大学生创业基地入驻程序为：项目申报、（）、项目入驻。","options":[["A","项目答辩"],["B","项目遴选"],["C","项目审核"],["D","撰写项目计划书"]],"answer":["B"],"source":"中国石油大学(华东)大学生创业实践管理办法","category":"创新创业","excerpt":"第六条基地入驻程序：1.项目申报。实行集中申报和评审，项目负责人向办公室提出申请，并提交创业基地入驻申请表、项目可行性研究报告等材料。2.项目遴选。办公室对项目进行初审，并组织相关专家组成评审组对通过初审的项目进行评审，评审过程采用公开答辩的形式。根据评审意见，拟定入驻方案。3.项目入驻。项目负责人与办公室签订入驻协议，办理入驻手续，入驻期原则上为一年。"},{"id":49,"type":"single","stem":"创业基金资助期原则上为（）年。","options":[["A","半"],["B","一"],["C","两"],["D","三"]],"answer":["B"],"source":"中国石油大学(华东)大学生创业实践管理办法","category":"创新创业","excerpt":"第十条基金资助程序：1.项目申报。实行集中申报和评审，项目负责人向办公室提出申请，并提交创业基金申请表、项目可行性研究报告等材料。2.项目遴选。办公室对项目进行初审，并组织相关专家组成评审组对通过初审的项目进行评审，评审过程采用公开答辩的形式。根据评审意见，拟定资助额度。3.项目资助。项目负责人与办公室签订资助协议。基金资助期原则上为一年，初期拨付资助金额的50%，经中期检查通过后，拨付剩余资助金额的50%。"},{"id":50,"type":"single","stem":"创业基金初期拨付资助金额的（）。","options":[["A","0.3"],["B","0.4"],["C","0.5"],["D","0.6"]],"answer":["C"],"source":"中国石油大学(华东)大学生创业实践管理办法","category":"创新创业","excerpt":"第十条基金资助程序：1.项目申报。实行集中申报和评审，项目负责人向办公室提出申请，并提交创业基金申请表、项目可行性研究报告等材料。2.项目遴选。办公室对项目进行初审，并组织相关专家组成评审组对通过初审的项目进行评审，评审过程采用公开答辩的形式。根据评审意见，拟定资助额度。3.项目资助。项目负责人与办公室签订资助协议。基金资助期原则上为一年，初期拨付资助金额的50%，经中期检查通过后，拨付剩余资助金额的50%。"},{"id":51,"type":"single","stem":"受资助项目如有盈利,根据项目收益情况,将项目净利润的（）%上交学校大学生创业基金,用以滚动支持更多创业项目。","options":[["A","5"],["B","10"],["C","15"],["D","20"]],"answer":["A"],"source":"中国石油大学(华东)大学生创业实践管理办法","category":"创新创业","excerpt":"第十一条基金运作管理：1.受资助的项目应定期向办公室提交基金使用情况的财务报告和项目运行情况报告，并接受中期检查和期满验收考核。2.受资助的项目因客观原因需对目标、进度和经费等进行调整时，应向办公室提出书面申请，经审核通过方可执行。3.受资助的项目提前退出时，须提前提出书面申请，报办公室审核后，办理清算核销手续。4.受资助项目如有盈利，根据项目收益情况，将项目净利润5%上交学校大学生创业基金，用以滚动支持更多创业项目。第五章扶持政策第十二条办公室负责与政府、企业、校友联系，为大学生创业项目争取场地、技术、资金等扶持政策。"},{"id":52,"type":"single","stem":"大学生创业项目入驻期原则上为（）年","options":[["A","半"],["B","一"],["C","两"],["D","三"]],"answer":["B"],"source":"中国石油大学(华东)大学生创业实践管理办法","category":"创新创业","excerpt":"第六条基地入驻程序：1.项目申报。实行集中申报和评审，项目负责人向办公室提出申请，并提交创业基地入驻申请表、项目可行性研究报告等材料。2.项目遴选。办公室对项目进行初审，并组织相关专家组成评审组对通过初审的项目进行评审，评审过程采用公开答辩的形式。根据评审意见，拟定入驻方案。3.项目入驻。项目负责人与办公室签订入驻协议，办理入驻手续，入驻期原则上为一年。"},{"id":53,"type":"single","stem":"可以借用别人的借书证借书吗？（ ）","options":[["A","可以"],["B","不可以"],["C","偶尔可以"],["D","允许借用一次"]],"answer":["B"],"source":"中国石油大学（华东）图书馆开架书库借阅管理规定","category":"图书馆","excerpt":""},{"id":54,"type":"single","stem":"图书馆开架书库是怎样分布的？（ ）","options":[["A","一层社科书库、二层文艺书库、三层科技书库"],["B","一层文艺书库、二层科技书库、三层社科书库"],["C","一层文艺书库、二层社科书库、三层科技书库"],["D","一层科技书库、二层社科书库、三层文艺书库"]],"answer":["C"],"source":"中国石油大学（华东）图书馆开架书库借阅管理规定","category":"图书馆","excerpt":""},{"id":55,"type":"single","stem":"图书馆的书刊都是经过科学的组织和管理，井然有序地排列在书架上的，排架规律为：面对书架，左手起架，（ ）书序排号，逐渐过度到末尾架，排架与排架之间，呈“S”型迂回绕架连接。","options":[["A","自右向左由小至大"],["B","自右向左由大至小"],["C","自左向右由小至大"],["D","自左向右由大至小"]],"answer":["C"],"source":"中国石油大学（华东）图书馆开架书库借阅管理规定","category":"图书馆","excerpt":""},{"id":56,"type":"single","stem":"以下说法哪个正确（ ）。","options":[["A","读者可以在所借图书上圈划"],["B","读者可以在所借图书上批注"],["C","读者可以将所借图书撕页"],["D","禁止污损图书"]],"answer":["D"],"source":"中国石油大学（华东）图书馆开架书库借阅管理规定","category":"图书馆","excerpt":""},{"id":57,"type":"single","stem":"本科生的借书规则是（ ）。","options":[["A","可借7本，单个书库最大借书量为3本"],["B","可借7本，单个书库最大借书量为5本"],["C","可借10本，单个书库最大借书量为3本"],["D","可借10本，单个书库最大借书量为5本"]],"answer":["D"],"source":"中国石油大学（华东）图书馆开架书库借阅管理规定","category":"图书馆","excerpt":""},{"id":58,"type":"single","stem":"购买原版图书赔偿时要求（ ）。","options":[["A","作者相同即可"],["B","出版社相同即可"],["C","书名、作者、出版社都相同"],["D","书名相同即可"]],"answer":["C"],"source":"中国石油大学（华东）图书馆开架书库借阅管理规定","category":"图书馆","excerpt":""},{"id":59,"type":"single","stem":"1980年后出版的中文图书直接赔款是按照原价的（ ）赔偿。","options":[["A","5-10倍"],["B","3-5倍"],["C","5-8倍"],["D","8-10倍"]],"answer":["B"],"source":"中国石油大学（华东）图书馆开架书库借阅管理规定","category":"图书馆","excerpt":""},{"id":60,"type":"single","stem":"以下哪一种情形可以办理离校核准手续（ ） 。","options":[["A","有在借图书"],["B","有限制担保"],["C","有超期图书"],["D","无在借图书无欠费"]],"answer":["D"],"source":"中国石油大学（华东）图书馆开架书库借阅管理规定","category":"图书馆","excerpt":""},{"id":61,"type":"single","stem":"我校的校风是（）。","options":[["A","实事求是，艰苦奋斗"],["B","勤奋严谨，求实创新"],["C","实事求是，奋发图强"],["D","求真务实，创新图强"]],"answer":["A"],"source":"《学校概况》 无》","category":"学校概况","excerpt":""},{"id":62,"type":"single","stem":"我校的校训是（）。","options":[["A","唯真唯实"],["B","惟真惟实"],["C","艰苦奋斗"],["D","艰苦奋斗"]],"answer":["B"],"source":"《学校概况》 无》","category":"学校概况","excerpt":""},{"id":63,"type":"single","stem":"我校的学风是（）。","options":[["A","实事求是，艰苦奋斗"],["B","勤奋严谨，求实创新"],["C","实事求是，奋发图强"],["D","勤奋严谨，奋发图强"]],"answer":["B"],"source":"《学校概况》 无》","category":"学校概况","excerpt":""},{"id":64,"type":"single","stem":"我校的校歌是（）。","options":[["A","《我为祖国献石油》"],["B","《北京石油学院学生之歌》"],["C","《团结就是力量》"],["D","《五月的花海》"]],"answer":["B"],"source":"《学校概况》 无》","category":"学校概况","excerpt":""},{"id":65,"type":"single","stem":"石大精神是（）。","options":[["A","实事求是，艰苦奋斗"],["B","勤奋严谨，求实创新"],["C","实事求是，奋发图强"],["D","求真务实，创新图强"]],"answer":["D"],"source":"《学校概况》 无》","category":"学校概况","excerpt":""},{"id":66,"type":"single","stem":"中国石油大学是教育部直属全国重点大学，是国家“（）”重点建设和开展“优势学科创新平台”建设并建有研究生院的高校之一。","options":[["A","985工程"],["B","211工程"],["C","优势学科建设平台"],["D","优势学科发展平台"]],"answer":["B"],"source":"《学校概况》 前言 第I页》","category":"学校概况","excerpt":"栺学校概况中国石油大学（华东）是教育部直属全国重点大学，是国家“211工程”重点建设和开展“985工程优势学科创新平台”建设并建有研究生院的高校之一。学校是教育部和五大能源企业集团公司、教育部和山东省人民政府共建的高校，是石油石化高层次人才培养的重要基地，被誉为“石油科技、管理人才的摇篮”，现已成为一所以工为主、石油石化特色鲜明、多学科协调发展的大学。2017年、2022年均进入国家“双一流”建设高校行列。"},{"id":67,"type":"single","stem":"追溯学校历史，（）年新中国成立之初，组建了新中国第一所石油高等学府——北京石油学院。","options":[["A","1949"],["B","1950"],["C","1952"],["D","1953"]],"answer":["D"],"source":"《学校概况》 前言 第I页》","category":"学校概况","excerpt":"追溯学校历史，1953年新中国成立之初，国民经济建设急需石油资源，石油工业发展急需专业人才。"},{"id":68,"type":"single","stem":"（）年10月，我校被确定为全国重点高校。","options":[["A","1959"],["B","1960"],["C","1961"],["D","1969"]],"answer":["B"],"source":"《学校概况》 前言 第I页》","category":"学校概况","excerpt":"……1960年10月，学校被确定为全国重点高校。"},{"id":69,"type":"single","stem":"（）年，学校迁至胜利油田所在地山东东营。","options":[["A","1960"],["B","1965"],["C","1969"],["D","1978"]],"answer":["C"],"source":"《学校概况》 前言 第I页》","category":"学校概况","excerpt":"……1969年，学校迁至胜利油田所在地———山东东营，更名为华东石油学院。"},{"id":70,"type":"single","stem":"学校迁至东营后，更名为（）。","options":[["A","华东石油学院"],["B","石油大学"],["C","中国石油大学"],["D","中国石油大学（华东）"]],"answer":["A"],"source":"《学校概况》 前言 第I页》","category":"学校概况","excerpt":"……1969年，学校迁至胜利油田所在地———山东东营，更名为华东石油学院。"},{"id":71,"type":"single","stem":"1997年，学校正式进入国家（）首批重点建设高校行列。","options":[["A","211工程"],["B","985优势学科平台"],["C","985工程"],["D","双一流学科"]],"answer":["A"],"source":"《学校概况》 前言 第I页》","category":"学校概况","excerpt":"……1997年，石油大学正式进入国家“211工程”首批重点建设高校行列。"},{"id":72,"type":"single","stem":"我校现在校本科生近（）人，研究生7000余人，留学生1100余人。","options":[["A","15000"],["B","19000"],["C","25000"],["D","30000"]],"answer":["B"],"source":"《学校概况》 前言 第Ⅲ页》","category":"学校概况","excerpt":"学校教育体系完备，各类教育层次结构合理，现有全日制在校本科生19000余人、研究生11000余人，留学生800余人。建校以来，学校始终坚持以立德树人为根本任务，着力打造人才培养质量品牌，赢得了广泛的社会声誉。建有国家级实验教学示范中心4个、国家级工程实践教育中心3个、国家级虚拟仿真实验教学中心3个、教育部虚拟教研室5个，获批国家级一流本科专业32个、国家级一流课程64门。从广大校友中涌现出大批杰出人才，走出了32位两院院士以及一大批石油石化行业领军人物和工程技术骨干。2004年被国务院授予“全国就业先进工作单位”荣誉称号，2011年入选50所全国毕业生就业典型经验高校，2019年入选“国家创新人才培养示范基地”，2021年入选“国家首批特色化示范性软件学院”，2022年入选国家级创新创业教育实践基地，2024年入选教育部涉外法治人才协同培养创新基地。"},{"id":73,"type":"single","stem":"自国家实行毕业生双向选择就业政策以来,毕业生就业率连续（）年保持在90%以上,2004年被国务院授予“全国就业先进工作单位”荣誉称号。","options":[["A","22"],["B","23"],["C","24"],["D","25"]],"answer":["D"],"source":"《学校概况》 前言 第Ⅲ页》","category":"学校概况","excerpt":""},{"id":74,"type":"single","stem":"在历史的新时期，在新的历史时期,学校坚持特色发展,开放发展,和谐发展,正在向着“建设国内著名、石油学科国际一流的高水平（）大学”的办学目标奋力迈进。","options":[["A","综合型"],["B","研究型"],["C","复合型"],["D","产学研融合型"]],"answer":["B"],"source":"《学校概况》 前言 第Ⅳ页》","category":"学校概况","excerpt":""},{"id":75,"type":"single","stem":"学生综合素质测评每学年进行（）次，一般于开学后4周内完成。","options":[["A","1"],["B","2"],["C","3"],["D","4"]],"answer":["A"],"source":"《中国石油大学（华东）学生综合素质测评办法（试行）》","category":"综合素质测评","excerpt":"第六条学生综合素质测评每学年进行1次，一般于新学年开学后4周内完成。"},{"id":76,"type":"single","stem":"已知英语（4-2）3学分，数学（2-2）5学分，军事理论1学分，小李同学英语、数学、军理的成绩分别是85、98、91，那么，小李同学的这三门功课的专业学习测评成绩绩点为（）。","options":[["A","4.13"],["B","92.89"],["C","4.29"],["D","91.33"]],"answer":["C"],"source":"《中国石油大学（华东）学生综合素质测评办法（试行）》","category":"综合素质测评","excerpt":""},{"id":77,"type":"single","stem":"已知小李同学的专业学习测评成绩、基础性素质测评成绩、发展性素质测评成绩分别得分91、85、88，那么小李的综合素质测评成绩绩点为（）。","options":[["A","88"],["B","91"],["C","85"],["D","90.1"]],"answer":["D"],"source":"《中国石油大学（华东）学生综合素质测评办法（试行）》","category":"综合素质测评","excerpt":""},{"id":78,"type":"single","stem":"基础性素质测评成绩中，“记实”分值应占（）。","options":[["A","0.4"],["B","0.5"],["C","0.6"],["D","0.7"]],"answer":["C"],"source":"《中国石油大学（华东）学生综合素质测评办法（试行）》","category":"综合素质测评","excerpt":""},{"id":79,"type":"single","stem":"基础性素质测评评定等级为A的比例应不超过（）。","options":[["A","0.1"],["B","0.25"],["C","0.33"],["D","0.5"]],"answer":["D"],"source":"《中国石油大学（华东）学生综合素质测评办法（试行）》","category":"综合素质测评","excerpt":""},{"id":80,"type":"single","stem":"国家奖学金奖励标准为（）。","options":[["A","5000元/人"],["B","6000元/人"],["C","6000元/人"],["D","8000元/人"]],"answer":["D"],"source":"《中国石油大学（华东）学生奖学金管理细则(试行)》","category":"奖学金与资助","excerpt":"……第五条奖励标准：8000元/人。"},{"id":81,"type":"single","stem":"国家励志奖学金奖励标准为（）。","options":[["A","5000元/人"],["B","7000元/人"],["C","6000元/人"],["D","8000元/人"]],"answer":["A"],"source":"《中国石油大学（华东）学生奖学金管理细则(试行)》","category":"奖学金与资助","excerpt":"……第五条奖励标准：5000元/人。"},{"id":82,"type":"single","stem":"学习优秀奖学金奖励标准为（）。","options":[["A","5000元/人"],["B","2000元/人"],["C","6000元/人"],["D","3000元/人"]],"answer":["B"],"source":"《中国石油大学（华东）学生奖学金管理细则(试行)》","category":"奖学金与资助","excerpt":"……第五条奖励标准：该奖项分为三个等级：一等奖学金4000元/人，按学生数的3%评定；二等奖学金2000元/人，按学生数的7%评定；三等奖学金1000元/人，按学生数的15%评定。评选要求：参评学生应为二年级以上（含二年级）学生。各院部严格按照《中国石油大学（华东）学生综合素质测评办法》的标准，对学生进行综合素质测评。4.企事业奖学金奖励对象：奖励品学兼优，综合素质全面发展，符合设奖单位（个人）评选要求的学生。奖励标准：奖励标准和奖励名额由学校与设奖单位（个人）协商确定。评选要求：各院部按照设奖单位（个人）的评选要求进行评定。以上四类综合奖学金不可兼得。（二）单项奖学金1.学习优秀奖学金奖励对象：奖励当学年学习成绩特别优秀的学生。奖励标准：2000元/人。"},{"id":83,"type":"single","stem":"当学年专业学习测评排名在专业年级前10%,且未获得综合奖学金的，可参评（）奖学金。","options":[["A","企事业奖学金的一种"],["B","学习优秀"],["C","文体"],["D","突出成绩"]],"answer":["B"],"source":"《中国石油大学（华东）学生奖学金管理细则(试行)》","category":"奖学金与资助","excerpt":"……第五条1.学习优秀奖学金奖励对象：奖励当学年学习成绩特别优秀的学生。奖励标准：2000元/人。评选要求：参评学生应为二年级以上（含二年级）学生，当学年专业学习测评排名在专业年级前10%，且未获得综合奖学金。"},{"id":84,"type":"single","stem":"学习进步奖学金奖励标准是800元/人,奖励专业学习测评成绩排名较上学年进步达到（）%的学生。","options":[["A","10"],["B","20"],["C","30"],["D","40"]],"answer":["C"],"source":"《中国石油大学（华东）学生奖学金管理细则(试行)》","category":"奖学金与资助","excerpt":""},{"id":85,"type":"single","stem":"省级先进班集体奖励（）元/班。","options":[["A","1000"],["B","3000"],["C","4000"],["D","5000"]],"answer":["B"],"source":"《中国石油大学（华东）学生奖学金管理细则(试行)》","category":"奖学金与资助","excerpt":""},{"id":86,"type":"single","stem":"优良学风班分为优良学分班、优良学风标兵班，奖励标准分别为（）元/班。","options":[["A","3000、5000"],["B","2000、4000"],["C","1000、3000"],["D","800、2000"]],"answer":["C"],"source":"《中国石油大学（华东）学生奖学金管理细则(试行)》","category":"奖学金与资助","excerpt":""},{"id":87,"type":"single","stem":"国家助学贷款本专科生每人每年最高不超过（）元。","options":[["A","10000"],["B","8000"],["C","6000"],["D","4000"]],"answer":["B"],"source":"《中国石油大学（华东）国家助学贷款实施办法》","category":"奖学金与资助","excerpt":""},{"id":88,"type":"single","stem":"国家助学金申请学生,当学年基础性素质测评等级至少为（）。","options":[["A","A"],["B","B"],["C","C"],["D","D"]],"answer":["C"],"source":"《中国石油大学（华东）“国家奖学金”、“国家励志奖学金”、“国家助学金”评选实施细则》","category":"奖学金与资助","excerpt":"第十一条申请国家助学金者还需具备以下条件：（一）勤奋学习，积极上进；（二）家庭经济困难，生活俭朴；（三）当学年基础性素质测评等级为“C”以上（含“C”）。第五章评选程序第十二条学生资助中心根据教育部全国学生资助管理中心下达的国家奖学金、国家励志奖学金、国家助学金名额，按照"},{"id":89,"type":"single","stem":"国家励志奖学金申请学生当学年基础性素质测评等级至少为（）。","options":[["A","A"],["B","B"],["C","C"],["D","D"]],"answer":["B"],"source":"《中国石油大学（华东）“国家奖学金”、“国家励志奖学金”、“国家助学金”评选实施细则》","category":"奖学金与资助","excerpt":"第十条申请国家励志奖学金者还需具备以下条件：（一）在校生中二年级以上（含二年级）的学生，在校期间学习成绩优秀；（二）家庭经济困难，生活俭朴；（三）当学年基础性素质测评等级为“B”以上（含“B”）；（四）当学年修读的课程不低于30学分，原则上专业学习测评成绩与综合素质测评成绩排名均位于前30%（含30%）。"},{"id":90,"type":"single","stem":"国家奖学金申请学生当学年基础性素质测评等级至少为（）。","options":[["A","A"],["B","B"],["C","C"],["D","D"]],"answer":["A"],"source":"《中国石油大学（华东）“国家奖学金”、“国家励志奖学金”、“国家助学金”评选实施细则》","category":"奖学金与资助","excerpt":"第九条申请国家奖学金者还需具备以下条件：（一）在校生中二年级以上（含二年级）的学生，在校期间学习成绩优异，社会实践、创新能力、综合素质等方面特别突出；（二）当学年基础性素质测评等级为“A”；（三）当学年修读的课程不低于30学分，专业学习测评成绩与综合素质测评成绩排名均位于前10%（含10%）；专业学习测评成绩与综合素质测评成绩排名没有进入前10%，但达到前30%（含30%）的学生，如在其他方面表现非常突出，也可申请国家奖学金，但需提交详细的证明材料，证明材料须由院（部）学生资助工作领导小组或工作组审核后盖章确认。其他方面表现非常突出是指在道德风尚、学术研究、学科竞赛、创新发明、社会实践、社会工作、体育竞赛、艺术展演等某一方面表现特别优秀。"},{"id":91,"type":"single","stem":"学生参加勤工助学不应当影响学业,原则上每周不超过（）小时,每月不超过（）小时。","options":[["A","8,40"],["B","7,35"],["C","8,35"],["D","7,40"]],"answer":["A"],"source":"《学生勤工助学管理实施细则》","category":"奖学金与资助","excerpt":"第十条校内勤工助学岗位既要满足学生需求，又要保证学生不因参加勤工助学而影响学习。学生参加勤工助学的时间原则上每周不超过8小时，每月不超过40小时。寒暑假勤工助学时间可根据学校的具体情况适当延长。"},{"id":92,"type":"single","stem":"先进班级体评选中，学年班集体成员修读课程及格率达（）以上有资格进行评选。","options":[["A","0.8"],["B","0.85"],["C","0.9"],["D","0.95"]],"answer":["D"],"source":"《中国石油大学（华东）先进班集体、优秀学生、优秀学生干部评选标准》","category":"优良学风班","excerpt":"……一、当学年班集体成员修读课程及格率达95%以上，优良率达60%以上。"},{"id":93,"type":"single","stem":"先进班级体评选中，学年班集体成员修读课程优良率达（）以上有资格进行评选。","options":[["A","0.6"],["B","0.65"],["C","0.7"],["D","0.75"]],"answer":["A"],"source":"《中国石油大学（华东）先进班集体、优秀学生、优秀学生干部评选标准》","category":"优良学风班","excerpt":"……一、当学年班集体成员修读课程及格率达95%以上，优良率达60%以上。"},{"id":94,"type":"single","stem":"先进班级体评选数一般不会超过班级总数的（）。","options":[["A","0.05"],["B","0.1"],["C","0.15"],["D","0.2"]],"answer":["B"],"source":"《中国石油大学（华东）先进班集体、优秀学生、优秀学生干部评选标准》","category":"优良学风班","excerpt":"……一、8.评选数不超过班级总数的10%。"},{"id":95,"type":"single","stem":"优秀学生评选中，综合素质测评成绩前（）内的学生具有申请资格,最终评选数不超过学生数的（）。","options":[["A","30%，20%"],["B","30%，30%"],["C","20%，20%"],["D","20%，30%"]],"answer":["A"],"source":"《中国石油大学（华东）先进班集体、优秀学生、优秀学生干部评选标准》","category":"优良学风班","excerpt":"二、优秀学生评选标准1.热爱祖国，拥护党的路线、方针、政策，政治上积极要求进步，具有较高的思想政治素质。2.积极参加学校、院部组织的各项活动，热爱集体，团结同学。遵守《学生文明行为规范》，有优秀的道德品质和良好的文明行为。3.学习目的明确，态度端正，勤奋刻苦，善于学习和吸收新知识，有较强的分析问题和解决问题的能力，具有开拓创新精神，学习成绩优秀。4.自觉遵守宪法和各项法律法规，遵守学校的规章制度，组织纪律性强，学年内无违法、违纪行为。5.积极参加体育锻炼和文娱活动，有健康的身体、良好的卫生习惯和过硬的心理素质，达到《国家学生体质健康标准》要求。6.积极做好宿舍内务卫生，营造良好的宿舍环境。7.综合素质测评成绩前30%内的学生具有申请资格，最终评选数不超过学生数的20%。"},{"id":96,"type":"single","stem":"优秀学生干部评选中，综合素质测评成绩前（）内的学生具有申请资格,最终评选数不超过学生数的（）。","options":[["A","50%，20%"],["B","50%，10%"],["C","30%，10%"],["D","30%，20%"]],"answer":["B"],"source":"《中国石油大学（华东）先进班集体、优秀学生、优秀学生干部评选标准》","category":"优良学风班","excerpt":"三、优秀学生干部评选标准1.热爱祖国，拥护党的路线、方针、政策，具有较高的思想政治素质和道德修养。2.热爱集体，团结同学，担任学生干部满1年，积极参与学校、院部组织的各项集体活动，配合学校和老师主动开展管理工作。热心为同学服务，作风正派，具有较强的管理能力和组织协调能力，在同学中有较高威信，切实起到骨干和带头作用，工作成绩突出。3.能正确处理好学习与工作的关系，学风严谨，成绩优良。4.自觉遵守宪法和各项法律、法规，遵守学校的规章制度，组织纪律性强，学年内无违法、违纪行为。5.积极做好宿舍内务卫生和个人卫生，带头营造良好的宿舍风气，维护宿舍正常的生活秩序，宿舍检查的优良达标率位居前列。6.综合素质测评成绩前50%内的学生具有申请资格，最终评选数不超过学生数的10%。"},{"id":97,"type":"single","stem":"国家励志奖学金由中央和地方政府共同出资设立,用于奖励资助（）学生。","options":[["A","在德、智、体、美等方面全面发展,综合素质特别优秀"],["B","勤奋学习,努力进取,在德、智、体、美等方面全面发展,品学兼优的家庭经济困难"],["C","拥有特长并取得优秀成绩"],["D","做好事，回报社会"]],"answer":["B"],"source":"《中国石油大学（华东）“国家奖学金”、“国家励志奖学金”、“国家助学金”评选实施细则》","category":"奖学金与资助","excerpt":""},{"id":98,"type":"single","stem":"除开除学籍处分以外,给予学生处分设置一定期限,严重警告处分期限为（）个月。","options":[["A","4"],["B","6"],["C","8"],["D","10"]],"answer":["C"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第六条除开除学籍处分以外，给予学生处分设置一定期限，警告处分期限为6个月，严重警告处分期限为8个月，记过处分期限为10个月，留校察看处分期限为12个月，处分期限从处分决定下达之日起计算。受纪律处分的学生，其处分期限可减至退学或者毕业等离校日止。"},{"id":99,"type":"single","stem":"除开除学籍处分以外,给予学生处分设置一定期限,记过处分期限为（）个月。","options":[["A","4"],["B","6"],["C","8"],["D","10"]],"answer":["D"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第六条除开除学籍处分以外，给予学生处分设置一定期限，警告处分期限为6个月，严重警告处分期限为8个月，记过处分期限为10个月，留校察看处分期限为12个月，处分期限从处分决定下达之日起计算。受纪律处分的学生，其处分期限可减至退学或者毕业等离校日止。"},{"id":100,"type":"single","stem":"除开除学籍处分以外,给予学生处分设置一定期限,留校察看处分期限为（）个月","options":[["A","6"],["B","8"],["C","10"],["D","12"]],"answer":["D"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第六条除开除学籍处分以外，给予学生处分设置一定期限，警告处分期限为6个月，严重警告处分期限为8个月，记过处分期限为10个月，留校察看处分期限为12个月，处分期限从处分决定下达之日起计算。受纪律处分的学生，其处分期限可减至退学或者毕业等离校日止。"},{"id":101,"type":"single","stem":"除开除学籍处分以外,给予学生处分设置一定期限,警告处分期限为（）个月。","options":[["A","4"],["B","6"],["C","8"],["D","10"]],"answer":["B"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第六条除开除学籍处分以外，给予学生处分设置一定期限，警告处分期限为6个月，严重警告处分期限为8个月，记过处分期限为10个月，留校察看处分期限为12个月，处分期限从处分决定下达之日起计算。受纪律处分的学生，其处分期限可减至退学或者毕业等离校日止。"},{"id":102,"type":"single","stem":"除开除学籍处分以外,给予学生处分设置一定期限,警告处分期限为（）个月,严重警告处分期限为（）个月,记过处分期限为（）个月,留校察看处分期限为（）个月。","options":[["A","6,8,10,12"],["B","4，6，8，10"],["C","8，10，12，14"],["D","3，5，7，9"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第六条除开除学籍处分以外，给予学生处分设置一定期限，警告处分期限为6个月，严重警告处分期限为8个月，记过处分期限为10个月，留校察看处分期限为12个月，处分期限从处分决定下达之日起计算。受纪律处分的学生，其处分期限可减至退学或者毕业等离校日止。"},{"id":103,"type":"single","stem":"对于违反宪法，违反四项基本原则的行为者，给予（）处分。","options":[["A","严重警告"],["B","记过"],["C","留校察看"],["D","开除学籍"]],"answer":["D"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第八条学生有以下情形之一的，可以从重或者加重处分：（一）互相串供，隐瞒真相；（二）对有关人员打击报复、威胁恫吓；（三）贿赂违纪处理人员或者以其他方式干扰违纪处理工作；（四）作为集体违纪事件组织策划者，或者教唆、煽动他人违纪并造成严重后果；（五）同时有两种以上违纪行为或者屡次违纪；（六）其他可以从重或者加重处分的情形。第三章违纪行为和处分第九条对有违反宪法，反对四项基本原则行为者，给予开除学籍处分。"},{"id":104,"type":"single","stem":"构成刑事犯罪,受刑事处罚者,给予（）处分。","options":[["A","严重警告"],["B","记过"],["C","留校察看"],["D","开除学籍"]],"answer":["D"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第十条对触犯国家法律法规，受处罚者，给予如下处分：（一）构成刑事犯罪，受刑事处罚者，给予开除学籍处分；因过失犯罪者，给予留校察看或者开除学籍处分；（二）违反治安管理处罚法，受行政拘留者，视情节轻重，给予记过、留校察看或者开除学籍处分；受警告或者罚款者，给予警告或者严重警告处分。"},{"id":105,"type":"single","stem":"因过失犯罪者,给予（）或者（）处分。","options":[["A","警告，严重警告"],["B","严重警告，记过"],["C","记过，留校察看"],["D","留校察看，开除学籍"]],"answer":["D"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":""},{"id":106,"type":"single","stem":"违反治安管理处罚法,受警告或者罚款者,给予（）或者（）处分。","options":[["A","警告，严重警告"],["B","严重警告，记过"],["C","记过，留校察看"],["D","留校察看，开除学籍"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":""},{"id":107,"type":"single","stem":"对泄露党和国家机密者,视情节轻重,给予（）或者（）处分。","options":[["A","警告，严重警告"],["B","严重警告，记过"],["C","记过，留校察看"],["D","留校察看，开除学籍"]],"answer":["D"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":""},{"id":108,"type":"single","stem":"对破坏民族团结、挑拨民族纠纷，情节较轻者，给予（）处分。","options":[["A","警告"],["B","严重警告"],["C","记过"],["D","留校察看"]],"answer":["C"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第十二条对破坏民族团结、挑拨民族纠纷者，给予记过处分；情节严重的，给予留校察看或者开除学籍处分。"},{"id":109,"type":"single","stem":"校园内违规携带、保存、使用危险物品者,给予严重警告处分,情节严重的,给予（）或者（）处分。","options":[["A","警告，严重警告"],["B","严重警告，记过"],["C","记过，留校察看"],["D","留校察看，开除学籍"]],"answer":["C"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":""},{"id":110,"type":"single","stem":"张贴、投递、散发非法宣传品,散布、传播虚假信息或者有害信息且造成严重后果或者恶劣影响者的,给予（）处分。","options":[["A","警告"],["B","严重警告"],["C","记过"],["D","留校察看"]],"answer":["C"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"……第十四条（二）参与各种非法集会、游行、示威，不听劝阻者，给予警告或者严重警告处分，情节严重的，给予记过处分；（三）张贴、投递、散发非法宣传品，散布、传播虚假信息或者有害信息者，给予警告或者严重警告处分，造成严重后果或者恶劣影响者，给予记过处分；（四）主动参与非法传销者，给予记过处分，情节严重的，给予留校察看或者开除学籍处分；（五）在校内参与宗教活动、封建迷信活动者，给予严重警告处分，情节严重的，给予记过处分；（六）在校内组织宗教活动或者传播宗教者，给予记过处分，情节严重的，给予留校察看或者开除学籍处分；（七）破坏学校教育教学秩序、生活秩序以及公共场所管理秩序者，给予记过或者留校察看处分，情节严重的，给予开除学籍处分；"},{"id":111,"type":"single","stem":"破坏环境,情节严重者,给予（）处分。","options":[["A","警告"],["B","严重警告"],["C","记过"],["D","留校察看"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第十五条对从事或者参与有损大学生形象、有悖社会公序良俗的活动者的处分：（一）破坏环境，情节严重者，给予警告处分；（二）侮辱、诽谤或恐吓他人者，给予警告处分，情节恶劣的，给予记过处分；（三）有窥看、滋扰等侵犯他人合法权益行为者，给予警告或者严重警告处分；情节严重或经教育不改者，给予记过、留校察看或者开除学籍处分；（四）聚众观看淫秽书刊或者声像制品者，给予严重警告处分；（五）在公共设施上乱涂乱画者，给予严重警告或者记过处分；（六）传播、复制、贩卖违规书刊和音像制品者，给予记过处分，情节严重的，给予留校察看处分；（七）宿舍内留宿异性及到异性宿舍留宿者，给予留校察看或者开除学籍处分；（八）其他有损大学生形象、有悖社会公序良俗行为者，视情节轻重，给予相应纪律处分。"},{"id":112,"type":"single","stem":"侮辱、诽谤或恐吓他人者,给予警告处分,情节恶劣的,给予（）处分。","options":[["A","警告"],["B","严重警告"],["C","记过"],["D","留校察看"]],"answer":["C"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第十五条对从事或者参与有损大学生形象、有悖社会公序良俗的活动者的处分：（一）破坏环境，情节严重者，给予警告处分；（二）侮辱、诽谤或恐吓他人者，给予警告处分，情节恶劣的，给予记过处分；（三）有窥看、滋扰等侵犯他人合法权益行为者，给予警告或者严重警告处分；情节严重或经教育不改者，给予记过、留校察看或者开除学籍处分；（四）聚众观看淫秽书刊或者声像制品者，给予严重警告处分；（五）在公共设施上乱涂乱画者，给予严重警告或者记过处分；（六）传播、复制、贩卖违规书刊和音像制品者，给予记过处分，情节严重的，给予留校察看处分；（七）宿舍内留宿异性及到异性宿舍留宿者，给予留校察看或者开除学籍处分；（八）其他有损大学生形象、有悖社会公序良俗行为者，视情节轻重，给予相应纪律处分。"},{"id":113,"type":"single","stem":"聚众观看淫秽书刊或者声像制品者,给予（）处分。","options":[["A","警告"],["B","严重警告"],["C","记过"],["D","留校察看"]],"answer":["B"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第十五条对从事或者参与有损大学生形象、有悖社会公序良俗的活动者的处分：（一）破坏环境，情节严重者，给予警告处分；（二）侮辱、诽谤或恐吓他人者，给予警告处分，情节恶劣的，给予记过处分；（三）有窥看、滋扰等侵犯他人合法权益行为者，给予警告或者严重警告处分；情节严重或经教育不改者，给予记过、留校察看或者开除学籍处分；（四）聚众观看淫秽书刊或者声像制品者，给予严重警告处分；（五）在公共设施上乱涂乱画者，给予严重警告或者记过处分；（六）传播、复制、贩卖违规书刊和音像制品者，给予记过处分，情节严重的，给予留校察看处分；（七）宿舍内留宿异性及到异性宿舍留宿者，给予留校察看或者开除学籍处分；（八）其他有损大学生形象、有悖社会公序良俗行为者，视情节轻重，给予相应纪律处分。"},{"id":114,"type":"single","stem":"在公共设施上乱涂乱画者,给予（）或者（）处分。","options":[["A","警告，严重警告"],["B","严重警告，记过"],["C","记过，留校察看"],["D","留校察看，开除学籍"]],"answer":["B"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":""},{"id":115,"type":"single","stem":"课程作业、结业论文以及实验报告存在剽窃、抄袭、伪造等行为者,视情节轻重,给予（）或者（）处分。","options":[["A","警告，严重警告"],["B","严重警告，记过"],["C","记过，留校察看"],["D","留校察看，开除学籍"]],"answer":["B"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":""},{"id":116,"type":"single","stem":"对无故缺席不参加教育教学计划规定的活动者,情节严重的,应给与一定处分，累计无故缺席10-19学时者,给予（）处分。","options":[["A","警告"],["B","严重警告"],["C","记过"],["D","留校察看"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第十九条对无故缺席不参加教育教学计划规定的活动者，情节严重的，给予如下处分，以一学期为限计算：（一）累计无故缺席10~19学时者，给予警告处分；（二）累计无故缺席20~39学时者，给予严重警告处分；（三）累计无故缺席40~59学时者，给予记过处分；（四）累计无故缺席60~80学时者，给予留校察看处分；（五）受到留校察看处分，经教育不改，因无故缺席再次达到纪律处分条件的，给予开除学籍处分；（六）无故迟到、早退累计3次按无故缺席1学时计算；无故不参加实践教学、军训等活动者，每天按无故缺席6学时计算；未经批准擅自离校，每天按无故缺席6学时计算，累计后给予相应纪律处分。"},{"id":117,"type":"single","stem":"对无故缺席不参加教育教学计划规定的活动者,情节严重的,应给与一定处分，累计无故缺席20-39学时者,给予（）处分。","options":[["A","警告"],["B","严重警告"],["C","记过"],["D","留校察看"]],"answer":["B"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第十九条对无故缺席不参加教育教学计划规定的活动者，情节严重的，给予如下处分，以一学期为限计算：（一）累计无故缺席10~19学时者，给予警告处分；（二）累计无故缺席20~39学时者，给予严重警告处分；（三）累计无故缺席40~59学时者，给予记过处分；（四）累计无故缺席60~80学时者，给予留校察看处分；（五）受到留校察看处分，经教育不改，因无故缺席再次达到纪律处分条件的，给予开除学籍处分；（六）无故迟到、早退累计3次按无故缺席1学时计算；无故不参加实践教学、军训等活动者，每天按无故缺席6学时计算；未经批准擅自离校，每天按无故缺席6学时计算，累计后给予相应纪律处分。"},{"id":118,"type":"single","stem":"对无故缺席不参加教育教学计划规定的活动者,情节严重的,应给与一定处分，累计无故缺席40-59学时者,给予（）处分。","options":[["A","警告"],["B","严重警告"],["C","记过"],["D","留校察看"]],"answer":["C"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第十九条对无故缺席不参加教育教学计划规定的活动者，情节严重的，给予如下处分，以一学期为限计算：（一）累计无故缺席10~19学时者，给予警告处分；（二）累计无故缺席20~39学时者，给予严重警告处分；（三）累计无故缺席40~59学时者，给予记过处分；（四）累计无故缺席60~80学时者，给予留校察看处分；（五）受到留校察看处分，经教育不改，因无故缺席再次达到纪律处分条件的，给予开除学籍处分；（六）无故迟到、早退累计3次按无故缺席1学时计算；无故不参加实践教学、军训等活动者，每天按无故缺席6学时计算；未经批准擅自离校，每天按无故缺席6学时计算，累计后给予相应纪律处分。"},{"id":119,"type":"single","stem":"对无故缺席不参加教育教学计划规定的活动者,情节严重的,应给与一定处分，累计无故缺席60-80学时者,给予（）处分。","options":[["A","警告"],["B","严重警告"],["C","记过"],["D","留校察看"]],"answer":["D"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第十九条对无故缺席不参加教育教学计划规定的活动者，情节严重的，给予如下处分，以一学期为限计算：（一）累计无故缺席10~19学时者，给予警告处分；（二）累计无故缺席20~39学时者，给予严重警告处分；（三）累计无故缺席40~59学时者，给予记过处分；（四）累计无故缺席60~80学时者，给予留校察看处分；（五）受到留校察看处分，经教育不改，因无故缺席再次达到纪律处分条件的，给予开除学籍处分；（六）无故迟到、早退累计3次按无故缺席1学时计算；无故不参加实践教学、军训等活动者，每天按无故缺席6学时计算；未经批准擅自离校，每天按无故缺席6学时计算，累计后给予相应纪律处分。"},{"id":120,"type":"single","stem":"无故迟到、早退累计（）次按无故缺席1学时计算。","options":[["A","2"],["B","3"],["C","4"],["D","5"]],"answer":["B"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第十九条对无故缺席不参加教育教学计划规定的活动者，情节严重的，给予如下处分，以一学期为限计算：（一）累计无故缺席10~19学时者，给予警告处分；（二）累计无故缺席20~39学时者，给予严重警告处分；（三）累计无故缺席40~59学时者，给予记过处分；（四）累计无故缺席60~80学时者，给予留校察看处分；（五）受到留校察看处分，经教育不改，因无故缺席再次达到纪律处分条件的，给予开除学籍处分；（六）无故迟到、早退累计3次按无故缺席1学时计算；无故不参加实践教学、军训等活动者，每天按无故缺席6学时计算；未经批准擅自离校，每天按无故缺席6学时计算，累计后给予相应纪律处分。"},{"id":121,"type":"single","stem":"无故不参加实践教学、军训等活动者,每天按无故缺席（）学时计算。","options":[["A","5"],["B","6"],["C","7"],["D","8"]],"answer":["B"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第十九条对无故缺席不参加教育教学计划规定的活动者，情节严重的，给予如下处分，以一学期为限计算：（一）累计无故缺席10~19学时者，给予警告处分；（二）累计无故缺席20~39学时者，给予严重警告处分；（三）累计无故缺席40~59学时者，给予记过处分；（四）累计无故缺席60~80学时者，给予留校察看处分；（五）受到留校察看处分，经教育不改，因无故缺席再次达到纪律处分条件的，给予开除学籍处分；（六）无故迟到、早退累计3次按无故缺席1学时计算；无故不参加实践教学、军训等活动者，每天按无故缺席6学时计算；未经批准擅自离校，每天按无故缺席6学时计算，累计后给予相应纪律处分。"},{"id":122,"type":"single","stem":"未经批准擅自离校,每天按无故缺席（）学时计算。","options":[["A","5"],["B","6"],["C","7"],["D","8"]],"answer":["B"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第十九条对无故缺席不参加教育教学计划规定的活动者，情节严重的，给予如下处分，以一学期为限计算：（一）累计无故缺席10~19学时者，给予警告处分；（二）累计无故缺席20~39学时者，给予严重警告处分；（三）累计无故缺席40~59学时者，给予记过处分；（四）累计无故缺席60~80学时者，给予留校察看处分；（五）受到留校察看处分，经教育不改，因无故缺席再次达到纪律处分条件的，给予开除学籍处分；（六）无故迟到、早退累计3次按无故缺席1学时计算；无故不参加实践教学、军训等活动者，每天按无故缺席6学时计算；未经批准擅自离校，每天按无故缺席6学时计算，累计后给予相应纪律处分。"},{"id":123,"type":"single","stem":"对违反考场纪律者,给予（）处分,情节严重的,给予（）处分。","options":[["A","警告，严重警告"],["B","严重警告，记过"],["C","记过，留校察看"],["D","留校察看，开除学籍"]],"answer":["B"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":""},{"id":124,"type":"single","stem":"在考试过程中旁窥、交头接耳、互打暗号或者手势的,给予（）处分。","options":[["A","警告"],["B","严重警告"],["C","记过"],["D","留校察看"]],"answer":["C"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"……第二十一条（一）携带与考试内容相关的文字材料或者存储有与考试内容相关资料的电子设备参加考试的，给予记过处分，情节严重的，给予留校察看处分；（二）考试过程中直接或以借用工具书、文具、计算器等方式传接与考试内容相关信息的，给予记过处分，情节严重的，给予留校察看处分；（三）故意损毁试卷、答题卡、答题纸等考试材料的，给予记过处分，情节严重的，给予留校察看处分；（四）抄袭或者协助他人抄袭试题答案或者与考试内容相关资料的，给予记过处分，情节严重的，给予留校察看处分；（五）在考试过程中旁窥、交头接耳、互打暗号或者手势的，给予记过处分；（六）抢夺、窃取他人试卷、答卷或者强迫他人为自己抄袭提供方便的，给予留校察看处分；（七）代替他人或者让他人代替自己参加考试的，给予开除学籍处分；（八）故意扰乱考试秩序，合伙作弊或者组织作弊的，给予开除学籍处分；（九）使用通讯设备或其他器材作弊的，给予开除学籍处分；（十）向他人出售考试试题或答案牟取利益的，给予开除学籍处分；（十一）有其他作弊行为的，视情节轻重，给予记过、留校察看或者开除学籍处分。"},{"id":125,"type":"single","stem":"抢夺、窃取他人试卷、答卷或者强迫他人为自己抄袭提供方便的,给予（）处分。","options":[["A","警告"],["B","严重警告"],["C","记过"],["D","留校察看"]],"answer":["D"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"……第二十一条（一）携带与考试内容相关的文字材料或者存储有与考试内容相关资料的电子设备参加考试的，给予记过处分，情节严重的，给予留校察看处分；（二）考试过程中直接或以借用工具书、文具、计算器等方式传接与考试内容相关信息的，给予记过处分，情节严重的，给予留校察看处分；（三）故意损毁试卷、答题卡、答题纸等考试材料的，给予记过处分，情节严重的，给予留校察看处分；（四）抄袭或者协助他人抄袭试题答案或者与考试内容相关资料的，给予记过处分，情节严重的，给予留校察看处分；（五）在考试过程中旁窥、交头接耳、互打暗号或者手势的，给予记过处分；（六）抢夺、窃取他人试卷、答卷或者强迫他人为自己抄袭提供方便的，给予留校察看处分；（七）代替他人或者让他人代替自己参加考试的，给予开除学籍处分；（八）故意扰乱考试秩序，合伙作弊或者组织作弊的，给予开除学籍处分；（九）使用通讯设备或其他器材作弊的，给予开除学籍处分；（十）向他人出售考试试题或答案牟取利益的，给予开除学籍处分；（十一）有其他作弊行为的，视情节轻重，给予记过、留校察看或者开除学籍处分。"},{"id":126,"type":"single","stem":"代替他人或者让他人代替自己参加考试的,给予（）处分。","options":[["A","严重警告"],["B","记过"],["C","留校察看"],["D","开除学籍"]],"answer":["D"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"……第二十一条（七）代替他人或者让他人代替自己参加考试的，给予开除学籍处分；（八）故意扰乱考试秩序，合伙作弊或者组织作弊的，给予开除学籍处分；（九）使用通讯设备或其他器材作弊的，给予开除学籍处分；（十）向他人出售考试试题或答案牟取利益的，给予开除学籍处分；（十一）有其他作弊行为的，视情节轻重，给予记过、留校察看或者开除学籍处分。"},{"id":127,"type":"single","stem":"故意扰乱考试秩序,合伙作弊或者组织作弊的,给予（）处分。","options":[["A","严重警告"],["B","记过"],["C","留校察看"],["D","开除学籍"]],"answer":["D"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"……第二十一条（七）代替他人或者让他人代替自己参加考试的，给予开除学籍处分；（八）故意扰乱考试秩序，合伙作弊或者组织作弊的，给予开除学籍处分；（九）使用通讯设备或其他器材作弊的，给予开除学籍处分；（十）向他人出售考试试题或答案牟取利益的，给予开除学籍处分；（十一）有其他作弊行为的，视情节轻重，给予记过、留校察看或者开除学籍处分。"},{"id":128,"type":"single","stem":"使用通讯设备或其他器材作弊的,给予（）处分。","options":[["A","严重警告"],["B","记过"],["C","留校察看"],["D","开除学籍"]],"answer":["D"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"……第二十一条（七）代替他人或者让他人代替自己参加考试的，给予开除学籍处分；（八）故意扰乱考试秩序，合伙作弊或者组织作弊的，给予开除学籍处分；（九）使用通讯设备或其他器材作弊的，给予开除学籍处分；（十）向他人出售考试试题或答案牟取利益的，给予开除学籍处分；（十一）有其他作弊行为的，视情节轻重，给予记过、留校察看或者开除学籍处分。"},{"id":129,"type":"single","stem":"向他人出售考试试题或答案牟取利益的,给予（）处分。","options":[["A","严重警告"],["B","记过"],["C","留校察看"],["D","开除学籍"]],"answer":["D"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"……第二十一条（七）代替他人或者让他人代替自己参加考试的，给予开除学籍处分；（八）故意扰乱考试秩序，合伙作弊或者组织作弊的，给予开除学籍处分；（九）使用通讯设备或其他器材作弊的，给予开除学籍处分；（十）向他人出售考试试题或答案牟取利益的，给予开除学籍处分；（十一）有其他作弊行为的，视情节轻重，给予记过、留校察看或者开除学籍处分。"},{"id":130,"type":"single","stem":"偷窃公章、机密文件、档案等物品者,视情节给予（）或（）处分。","options":[["A","警告，严重警告"],["B","严重警告，记过"],["C","记过，留校察看"],["D","留校察看，开除学籍"]],"answer":["D"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":""},{"id":131,"type":"single","stem":"陷害他人者,视其情节轻重,给予（）或者（）处分。","options":[["A","警告，严重警告"],["B","严重警告，记过"],["C","记过，留校察看"],["D","留校察看，开除学籍"]],"answer":["C"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":""},{"id":132,"type":"single","stem":"肇事者用语言污辱或者用其他方式触及他人,引起事端或者激化矛盾者,给予（）处分。","options":[["A","警告"],["B","严重警告"],["C","记过"],["D","留校察看"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"……第二十四条1.用语言污辱或者用其他方式触及他人，引起事端或者激化矛盾者，给予警告处分；2.引起打架后果者，给予严重警告处分；3.勾结本校学生以外人员到校内打架肇事者，给予留校察看处分，对造成严重后果者，给予开除学籍处分。（二）对打人者的处分：1.动手打人未造成伤害者，给予严重警告处分；2.打人致伤者，给予记过处分，手段恶劣或者致伤严重者，给予留校察看或者开除学籍处分；3.寻衅、报复打人者，加重一级处分；4.持械打人、结伙打人者，视情节加重一级处分。（三）对组织及策划打架、打人者的处分：1.造成后果较轻者，给予记过处分；2.造成后果严重者，给予留校察看或者开除学籍处分。（四）对打架中间介入者的处分：中间介入或者以“劝架”为名偏袒一方者，给予严重警告处分；导致事态加重或者造成严重后果者，视情节轻重，给予记过、留校察看或者开除学籍处分。（五）对提供器械者的处分：1.未造成伤害后果者，给予警告处分；"},{"id":133,"type":"single","stem":"肇事者对于采取不正当言行引起打架后果者,给予（）处分。","options":[["A","警告"],["B","严重警告"],["C","记过"],["D","留校察看"]],"answer":["B"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"……第二十四条2.引起打架后果者，给予严重警告处分；3.勾结本校学生以外人员到校内打架肇事者，给予留校察看处分，对造成严重后果者，给予开除学籍处分。（二）对打人者的处分：1.动手打人未造成伤害者，给予严重警告处分；2.打人致伤者，给予记过处分，手段恶劣或者致伤严重者，给予留校察看或者开除学籍处分；3.寻衅、报复打人者，加重一级处分；4.持械打人、结伙打人者，视情节加重一级处分。（三）对组织及策划打架、打人者的处分：1.造成后果较轻者，给予记过处分；2.造成后果严重者，给予留校察看或者开除学籍处分。（四）对打架中间介入者的处分：中间介入或者以“劝架”为名偏袒一方者，给予严重警告处分；导致事态加重或者造成严重后果者，视情节轻重，给予记过、留校察看或者开除学籍处分。"},{"id":134,"type":"single","stem":"动手打人未造成伤害者,给予（）处分。","options":[["A","警告"],["B","严重警告"],["C","记过"],["D","留校察看"]],"answer":["B"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"……第二十四条2.引起打架后果者，给予严重警告处分；3.勾结本校学生以外人员到校内打架肇事者，给予留校察看处分，对造成严重后果者，给予开除学籍处分。（二）对打人者的处分：1.动手打人未造成伤害者，给予严重警告处分；2.打人致伤者，给予记过处分，手段恶劣或者致伤严重者，给予留校察看或者开除学籍处分；3.寻衅、报复打人者，加重一级处分；4.持械打人、结伙打人者，视情节加重一级处分。（三）对组织及策划打架、打人者的处分：1.造成后果较轻者，给予记过处分；2.造成后果严重者，给予留校察看或者开除学籍处分。（四）对打架中间介入者的处分：中间介入或者以“劝架”为名偏袒一方者，给予严重警告处分；导致事态加重或者造成严重后果者，视情节轻重，给予记过、留校察看或者开除学籍处分。"},{"id":135,"type":"single","stem":"对组织及策划打架、打人者造成后果较轻者,给予（）处分。","options":[["A","警告"],["B","严重警告"],["C","记过"],["D","留校察看"]],"answer":["C"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"……第二十四条2.打人致伤者，给予记过处分，手段恶劣或者致伤严重者，给予留校察看或者开除学籍处分；3.寻衅、报复打人者，加重一级处分；4.持械打人、结伙打人者，视情节加重一级处分。（三）对组织及策划打架、打人者的处分：1.造成后果较轻者，给予记过处分；2.造成后果严重者，给予留校察看或者开除学籍处分。（四）对打架中间介入者的处分：中间介入或者以“劝架”为名偏袒一方者，给予严重警告处分；导致事态加重或者造成严重后果者，视情节轻重，给予记过、留校察看或者开除学籍处分。（五）对提供器械者的处分：1.未造成伤害后果者，给予警告处分；2.造成伤害后果者，视情节轻重，给予记过、留校察看或者开除学籍处分。"},{"id":136,"type":"single","stem":"对提供器械供人打架斗殴，未造成伤害后果者,给予（）处分。","options":[["A","警告"],["B","严重警告"],["C","记过"],["D","留校察看"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"……第二十四条1.用语言污辱或者用其他方式触及他人，引起事端或者激化矛盾者，给予警告处分；2.引起打架后果者，给予严重警告处分；3.勾结本校学生以外人员到校内打架肇事者，给予留校察看处分，对造成严重后果者，给予开除学籍处分。（二）对打人者的处分：1.动手打人未造成伤害者，给予严重警告处分；2.打人致伤者，给予记过处分，手段恶劣或者致伤严重者，给予留校察看或者开除学籍处分；3.寻衅、报复打人者，加重一级处分；4.持械打人、结伙打人者，视情节加重一级处分。（三）对组织及策划打架、打人者的处分：1.造成后果较轻者，给予记过处分；2.造成后果严重者，给予留校察看或者开除学籍处分。（四）对打架中间介入者的处分：中间介入或者以“劝架”为名偏袒一方者，给予严重警告处分；导致事态加重或者造成严重后果者，视情节轻重，给予记过、留校察看或者开除学籍处分。（五）对提供器械者的处分：1.未造成伤害后果者，给予警告处分；"},{"id":137,"type":"single","stem":"污辱、谩骂教职员工者,视情节轻重,给予（）或者（）处分。","options":[["A","警告，严重警告"],["B","严重警告，记过"],["C","记过，留校察看"],["D","留校察看，开除学籍"]],"answer":["B"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":""},{"id":138,"type":"single","stem":"殴打教职员工者,给予（）处分,情节严重的,给予（）处分。","options":[["A","警告，严重警告"],["B","严重警告，记过"],["C","记过，留校察看"],["D","留校察看，开除学籍"]],"answer":["D"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":""},{"id":139,"type":"single","stem":"赌博或者变相赌博者,视情节轻重,给予（）或者（）处分。","options":[["A","警告，严重警告"],["B","严重警告，记过"],["C","记过，留校察看"],["D","留校察看，开除学籍"]],"answer":["D"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":""},{"id":140,"type":"single","stem":"包庇、纵容违纪人员,造成不良影响者,给予（）处分。","options":[["A","警告"],["B","严重警告"],["C","记过"],["D","留校察看"]],"answer":["B"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第二十九条对干扰违纪行为调查者的处分：（一）包庇、纵容违纪人员，造成不良影响者，给予严重警告处分；（二）作伪证，或者帮助违纪人员毁灭证据，给调查造成困难者，视情节轻重，给予严重警告或者记过处分；（三）以暴力、威胁、贿赂等方式干扰证人作证或者指使他人作伪证者，视情节轻重，给予记过、留校察看或者开除学籍处分。"},{"id":141,"type":"single","stem":"作伪证,或者帮助违纪人员毁灭证据,给调查造成困难者,视情节轻重,给予（）或者（）处分。","options":[["A","警告，严重警告"],["B","严重警告，记过"],["C","记过，留校察看"],["D","留校察看，开除学籍"]],"answer":["B"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":""},{"id":142,"type":"single","stem":"学生对学校的处分决定有异议的,应在接到学校处分决定书之日起（）日内,向学校学生申诉处理委员会提出书面申诉。","options":[["A","3"],["B","5"],["C","7"],["D","10"]],"answer":["D"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第三十九条学生对学校的处分决定有异议的，可以在接到学校处分决定书之日起10日内，向学校学生申诉处理委员会提出书面申诉。学生申诉处理委员会对学生提出的申诉进行复查，作出复查决定。学生对复查决定有异议的，在接到学校复查决定书之日起15日内，可以向山东省教育厅提出书面申诉。"},{"id":143,"type":"single","stem":"学生对复查决定有异议的,在接到学校复查决定书之日起（）日内,可以向山东省教育厅提出书面申诉。","options":[["A","5"],["B","7"],["C","10"],["D","15"]],"answer":["D"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第三十九条学生对学校的处分决定有异议的，可以在接到学校处分决定书之日起10日内，向学校学生申诉处理委员会提出书面申诉。学生申诉处理委员会对学生提出的申诉进行复查，作出复查决定。学生对复查决定有异议的，在接到学校复查决定书之日起15日内，可以向山东省教育厅提出书面申诉。"},{"id":144,"type":"single","stem":"心理咨询中心接待心理咨询的地点为（）。","options":[["A","学生事务中心三楼332房间心理咨询值班室"],["B","电话预约，上门服务"],["C","17号宿舍公寓楼下心理工作室"],["D","大学生活动中心三楼"]],"answer":["A"],"source":"《心理咨询来访者须知》","category":"心理咨询","excerpt":""},{"id":145,"type":"single","stem":"凡我校本科生在取得本专业培养计划规定学分的同时,还需至少取得（）个自主发展计划学分","options":[["A","5"],["B","10"],["C","15"],["D","20"]],"answer":["B"],"source":"中国石油大学(华东)本科生自主发展计划","category":"自主发展计划","excerpt":""},{"id":146,"type":"single","stem":"“第二课堂成绩单”采用学分认证和学时记录的方法，每个学分对应（）个学时。","options":[["A","10"],["B","20"],["C","30"],["D","40"]],"answer":["B"],"source":"中国石油大学(华东)“第二课堂成绩单实施细则”","category":"自主发展计划","excerpt":""},{"id":147,"type":"single","stem":"对于“第二课堂成绩单”每学期各类课程修满（）个学分（不包括转换所得学分）后将不再进行累计，只进行活动记录。","options":[["A","1"],["B","2"],["C","3"],["D","4"]],"answer":["A"],"source":"中国石油大学(华东)“第二课堂成绩单实施细则”","category":"自主发展计划","excerpt":"……第七条每学期各类课程修满1个学分（不包括转换所得学分）后将不再累计，只进行活动记录。"},{"id":148,"type":"single","stem":"校级大学生创业基地入驻条件中要求项目负责人为（）","options":[["A","我校在校学生"],["B","我校全日制在校学生"],["C","全日制在校学生"],["D","我校在校教师"]],"answer":["B"],"source":"中国石油大学(华东)大学生创业实践管理办法","category":"创新创业","excerpt":"第五条基地入驻条件：1.项目负责人为我校全日制在校学生。2.具有较好市场前景且落地实体运转的创业项目、拥有自主知识产权的创业项目、在国家级或省级创业比赛中获奖的创业项目优先考虑。"},{"id":149,"type":"single","stem":"创业基金资助期原则上为（）年","options":[["A","半"],["B","一"],["C","两"],["D","三"]],"answer":["B"],"source":"中国石油大学(华东)大学生创业实践管理办法","category":"创新创业","excerpt":"第十条基金资助程序：1.项目申报。实行集中申报和评审，项目负责人向办公室提出申请，并提交创业基金申请表、项目可行性研究报告等材料。2.项目遴选。办公室对项目进行初审，并组织相关专家组成评审组对通过初审的项目进行评审，评审过程采用公开答辩的形式。根据评审意见，拟定资助额度。3.项目资助。项目负责人与办公室签订资助协议。基金资助期原则上为一年，初期拨付资助金额的50%，经中期检查通过后，拨付剩余资助金额的50%。"},{"id":150,"type":"single","stem":"创业基金初期拨付资助金额的（）","options":[["A","0.3"],["B","0.4"],["C","0.5"],["D","0.6"]],"answer":["C"],"source":"中国石油大学(华东)大学生创业实践管理办法","category":"创新创业","excerpt":"第十条基金资助程序：1.项目申报。实行集中申报和评审，项目负责人向办公室提出申请，并提交创业基金申请表、项目可行性研究报告等材料。2.项目遴选。办公室对项目进行初审，并组织相关专家组成评审组对通过初审的项目进行评审，评审过程采用公开答辩的形式。根据评审意见，拟定资助额度。3.项目资助。项目负责人与办公室签订资助协议。基金资助期原则上为一年，初期拨付资助金额的50%，经中期检查通过后，拨付剩余资助金额的50%。"},{"id":151,"type":"single","stem":"受资助项目如有盈利,根据项目收益情况,将项目净利润的（）%上交学校大学生创业基金,用以滚动支持更多创业项目。","options":[["A","5"],["B","10"],["C","15"],["D","20"]],"answer":["A"],"source":"中国石油大学(华东)大学生创业实践管理办法","category":"创新创业","excerpt":"第十一条基金运作管理：1.受资助的项目应定期向办公室提交基金使用情况的财务报告和项目运行情况报告，并接受中期检查和期满验收考核。2.受资助的项目因客观原因需对目标、进度和经费等进行调整时，应向办公室提出书面申请，经审核通过方可执行。3.受资助的项目提前退出时，须提前提出书面申请，报办公室审核后，办理清算核销手续。4.受资助项目如有盈利，根据项目收益情况，将项目净利润5%上交学校大学生创业基金，用以滚动支持更多创业项目。第五章扶持政策第十二条办公室负责与政府、企业、校友联系，为大学生创业项目争取场地、技术、资金等扶持政策。"},{"id":152,"type":"single","stem":"大学生创业项目入驻期原则上为（）年","options":[["A","半"],["B","一"],["C","两"],["D","三"]],"answer":["B"],"source":"中国石油大学(华东)大学生创业实践管理办法","category":"创新创业","excerpt":"第六条基地入驻程序：1.项目申报。实行集中申报和评审，项目负责人向办公室提出申请，并提交创业基地入驻申请表、项目可行性研究报告等材料。2.项目遴选。办公室对项目进行初审，并组织相关专家组成评审组对通过初审的项目进行评审，评审过程采用公开答辩的形式。根据评审意见，拟定入驻方案。3.项目入驻。项目负责人与办公室签订入驻协议，办理入驻手续，入驻期原则上为一年。"},{"id":153,"type":"single","stem":"学校设立创新创业资助基金，其中自主创业扶持资金（），每年立项资助（）项左右","options":[["A","70万元/年；50"],["B","80万元/年；50"],["C","80万元/年；60"],["D","70万元/年；60"]],"answer":["B"],"source":"中国石油大学(华东)本科生创新创业教育保障与激励暂行办法","category":"创新创业","excerpt":""},{"id":154,"type":"single","stem":"“三进”提升计划优秀生培养周期为（）年","options":[["A","2年"],["B","1年"],["C","3年"],["D","4年"]],"answer":["A"],"source":"优秀本科生\"三进\"提升计划实施办法","category":"三进提升计划","excerpt":""},{"id":155,"type":"single","stem":"按照每生每（）元的标准,给予科研团队优秀生培养经费资助,主要用于优秀生培养","options":[["A","1000-2000"],["B","3000-5000"],["C","4000-6000"],["D","5000-7000"]],"answer":["B"],"source":"优秀本科生\"三进\"提升计划实施办法","category":"三进提升计划","excerpt":""},{"id":156,"type":"single","stem":"“三进”计划原则上面向（）年级本科生,秋季学期组织, 每年选拔300~500名","options":[["A","一"],["B","二"],["C","三"],["D","四"]],"answer":["B"],"source":"优秀本科生\"三进\"提升计划实施办法","category":"三进提升计划","excerpt":""},{"id":157,"type":"single","stem":"在中国国际“ 互联网+ ”大学生创新创业大赛获得金奖、银奖、铜奖，分别获得奖金（）","options":[["A","5000;3000;1000"],["B","50000;30000;10000"],["C","4000;2000;1000"],["D","40000;20000;10000"]],"answer":["B"],"source":"本科生学科竞赛管理办法","category":"学科竞赛","excerpt":""},{"id":158,"type":"multi","stem":"以下说法错误的是（）。","options":[["A","凡未经学校批准，不在规定时间内交清学费的，不予注册学籍"],["B","学生参加自主发展计划第二课堂活动的，需按所修课程的规定学分交纳学分学费"],["C","通过自主选课重修（做）课程的，按照重修学分交纳学分学费"],["D","学生申请免听、自修课程的，不需交纳学分学费"]],"answer":["B","D"],"source":"《中国石油大学（华东）学分制收费管理暂行办法》","category":"学分制收费","excerpt":""},{"id":159,"type":"multi","stem":"以下说法正确的是（）。","options":[["A","学生因故休学、保留学籍的，停学期间不再交纳学费"],["B","学生在校期间转专业的，转入专业的专业注册学费和原专业不同的，按照多退少补的原则结算"],["C","学生毕业、结业、肄业离校时，应交清所欠学费方能办理离校手续"],["D","学生考试不及格的，如符合补考条件可免费补考二次，学生通过补考取得课程学分的，免交学分学费"]],"answer":["A","B","C"],"source":"《中国石油大学（华东）学分制收费管理暂行办法》","category":"学分制收费","excerpt":""},{"id":160,"type":"multi","stem":"学生在本专业培养方案外（）、（）、（）的，按照所修课程的规定学分交纳学分学费，在基本修业年限内，免交加修专业的专业注册学费。","options":[["A","修读其他课程"],["B","修读双学位"],["C","参加自主发展计划第二课堂活动"],["D","辅修专业"]],"answer":["A","B","D"],"source":"《中国石油大学（华东）学分制收费管理暂行办法》","category":"学分制收费","excerpt":""},{"id":161,"type":"multi","stem":"学生在校期间转专业的，自（）起，按照（）标准交纳专业注册学费。","options":[["A","学籍转换手续办理完成之日"],["B","下一学年"],["C","原专业"],["D","转入专业"]],"answer":["A","D"],"source":"《中国石油大学（华东）学分制收费管理暂行办法》","category":"学分制收费","excerpt":"第十五条学生在校期间转专业的，自学籍转换手续办理完成之日起，按照转入专业的标准交纳专业注册学费，转入专业的专业注册学费和原专业不同的，按照多退少补原则结算。"},{"id":162,"type":"multi","stem":"闭卷考试中下列（）情况，不论看与否，以考试作弊认定。","options":[["A","桌内、座位旁有翻开的或试卷下面垫有与考试内容相关的书、笔记、讲义、复习提纲等物品。"],["B","利用文具盒、衣物或其他用品夹带与考试内容相关的笔记、复习提纲、纸条。"],["C","在桌面、身上等处写有与考试相关的内容。"],["D","在允许使用的工具书上写有与考试相关的内容或夹带相关材料。"]],"answer":["A","B","C","D"],"source":"中国石油大学（华东）学生考试工作管理规定（修订）","category":"考试管理","excerpt":""},{"id":163,"type":"multi","stem":"下列（）情况，属于考试违纪行为。","options":[["A","未按考场规则就座。"],["B","闭卷考试至发试卷时仍将规定以外物品等带入座位。"],["C","自带空白答题纸或草稿纸。"],["D","未经监考人员允许借用他人的书、笔记、资料、计算器等物品。"]],"answer":["A","B","C","D"],"source":"中国石油大学（华东）学生考试工作管理规定（修订）","category":"考试管理","excerpt":""},{"id":164,"type":"multi","stem":"下列（）情况，属于考试违纪行为。","options":[["A","考试中东张西望，企图偷看他人试卷。"],["B","交卷后仍在考场逗留或在考场附近大声喧哗。"],["C","将试卷、答题卡、答题纸、草稿纸等带出考场。"],["D","请人代考或代人考试。"]],"answer":["A","B","C"],"source":"中国石油大学（华东）学生考试工作管理规定（修订）","category":"考试管理","excerpt":""},{"id":165,"type":"multi","stem":"下列（）情况，经调查核实，以作弊论处，该门课程总成绩以零分记。","options":[["A","将试卷、答题卡、答题纸、草稿纸等带出考场。"],["B","以请客、送礼、威胁等手段要求教师提分、加分或隐瞒违纪作弊事实。"],["C","毕业设计（论文）有严重剽窃、抄袭、伪造数据等学术不端行为。"],["D","在教师阅卷或其他情况下发现的作弊情况。"]],"answer":["B","C","D"],"source":"中国石油大学（华东）学生考试工作管理规定（修订）","category":"考试管理","excerpt":""},{"id":166,"type":"multi","stem":"实验教学是培养学生综合实践能力和创新精神的重要教学环节，包括（）。","options":[["A","独立设置的实验课程"],["B","独立设置的上机课程"],["C","课程中含有的实验教学环节"],["D","课程中含有的上机教学环节"]],"answer":["A","B","C","D"],"source":"《中国石油大学（华东）本科实验教学管理办法》","category":"实验教学与实习","excerpt":""},{"id":167,"type":"multi","stem":"在进行实验前，从（）等方面对实验进行预习。","options":[["A","实验原理"],["B","实验内容"],["C","实验方法步骤"],["D","仪器设备操作规程与注意事项"]],"answer":["A","B","C","D"],"source":"《中国石油大学（华东）本科实验教学管理办法》","category":"实验教学与实习","excerpt":""},{"id":168,"type":"multi","stem":"我校开展大学生创新创业训练计划的理念是（）。","options":[["A","兴趣驱动"],["B","学生为主"],["C","教师主导"],["D","注重过程"]],"answer":["A","B","D"],"source":"《中国石油大学（华东）大学生创新创业训练计划项目管理办法》","category":"创新创业","excerpt":"一、指导思想按照“兴趣驱动，学生为主，注重过程”的理念，进一步转变教育思想观念，以大学生创新创业训练计划为突破口，推进以学生为主体的人才培养模式改革，强化创新创业能力训练，增强大学生的创新能力和在创新基础上的创业能力，培养适应创新型国家建设需要的高水平创新人才。"},{"id":169,"type":"multi","stem":"大学生创新创业训练计划的项目类型包括（）。","options":[["A","创新训练项目"],["B","创新实践项目"],["C","创业训练项目"],["D","创业实践项目"]],"answer":["A","C","D"],"source":"《中国石油大学（华东）大学生创新创业训练计划项目管理办法》","category":"创新创业","excerpt":"三、计划内容大学生创新创业训练计划内容包括创新训练项目、创业训练项目和创业实践项目三类。创新训练项目是本科生个人或团队，在导师指导下，自主完成创新性研究项目设计、研究条件准备和项目实施、研究报告撰写、成果（学术）交流等工作。创业训练项目是本科生团队，在导师指导下，团队中每个学生在项目实施过程中扮演一个或多个具体的角色，完成编制商业计划书、开展可行性研究、模拟企业运行、参加企业实践、撰写创业报告等工作。创业实践项目是学生团队，在学校导师和企业导师共同指导下，采用前期创新训练项目（或创新性实验）的成果，提出一项具有市场前景的创新性产品或者服务，以此为基础开展创业实践活动。"},{"id":170,"type":"multi","stem":"毕业设计成绩由哪基本部分综合组成。","options":[["A","评阅教师评价"],["B","答辩成绩"],["C","指导教师评价"],["D","学生自评"]],"answer":["A","B","C"],"source":"《中国石油大学（华东）本科毕业设计（论文）管理规定》","category":"其他","excerpt":""},{"id":171,"type":"multi","stem":"学校对创新创业活动的资助主要包括以下哪几方面？","options":[["A","创新创业训练计划项目"],["B","科研创新项目"],["C","学科竞赛"],["D","课外科技活动"],["E","实验室开放"]],"answer":["B","C","D","E"],"source":"《中国石油大学（华东）本科生创新创业教育保障与激励暂行办法》","category":"创新创业","excerpt":""},{"id":172,"type":"multi","stem":"学生获得哪些高水平创新成果可以得到学校的奖励","options":[["A","高水平学术论文"],["B","发明专利"],["C","科技成果"],["D","著作"]],"answer":["A","B","C","D"],"source":"《中国石油大学（华东）本科生创新成果奖励办法》","category":"学科竞赛","excerpt":""},{"id":173,"type":"multi","stem":"获得学术论文奖励必要条件是（）","options":[["A","我校本科生作为第一作者"],["B","论文已公开发表"],["C","中国石油大学（华东）为第一署名单位"],["D","被SCI、SSCI、EI等检索"]],"answer":["A","B","C"],"source":"《中国石油大学（华东）本科生创新成果奖励办法》","category":"学科竞赛","excerpt":""},{"id":174,"type":"multi","stem":"学校本科专业标准学制四年（建筑学专业五年），实行学分制管理和弹性学习年限，学生可以在标准学制的基础上（）或（）毕业。","options":[["A","提前一年"],["B","提前两年"],["C","延长两年"],["D","延长三年"],["E","延长四年"]],"answer":["A","C"],"source":"《中国石油大学（华东）本科生学籍管理规定》","category":"学籍管理","excerpt":"第三条学校本科专业标准学制四年（建筑学专业学制五年），实行学分制管理和弹性学习年限，学生可在标准学制的基础上提前一年或延长两年毕业。"},{"id":175,"type":"multi","stem":"以下哪些类型的课程，和通识教育选修课、包含实验环节的课程、实习以及其他须随堂修读的课程一样,均不得申请免修、免听？","options":[["A","思想政治理论课"],["B","体育课"],["C","独立实验课"],["D","军训"],["E","毕业设计(论文)"],["F","专业必修课"]],"answer":["A","B","C","D","E"],"source":"《本科生学籍管理规定》","category":"学籍管理","excerpt":"……第十五条3.思想政治理论课、体育课、通识教育选修课、包含实验环节的课程、独立实验课、军训、实习、毕业设计（论文）以及其他须随堂修读的课程，均不得申请免修、免听。"},{"id":176,"type":"multi","stem":"学生有以下哪些情形者,不得参加该课程的结课考核（免听课程除外）？","options":[["A","累计缺课达到该课程计划学时的1/3者"],["B","累计缺交作业(含抄袭作业)达到该门课程所有作业量的1/3者"],["C","课程上课时间4次违反课堂纪律（如睡觉）者"],["D","独立设置的实验(上机)课程,缺做实验学时或缺交实验报告达到1/3者"]],"answer":["A","B","D"],"source":"《中国石油大学（华东）本科生学籍管理规定》","category":"学籍管理","excerpt":"第十六条学生有以下情形之一者，不得参加该课程的结课考核（免听课程除外）：1.累计缺课达到该课程计划学时的1/3者；2.累计缺交作业（含抄袭作业）达到该门课程所有作业量的1/3者；3.独立设置的实验（上机）课程，缺做实验学时或缺交实验报告达到1/3者。"},{"id":177,"type":"multi","stem":"学生参加学校认可的（）等活动以及发表论文、获得专利授权等与专业学习、学业要求相关的经历、成果,经学校认定,可记为相应学分。","options":[["A","开放式网络课程学习"],["B","创新创业"],["C","家教类兼职"],["D","社会实践"]],"answer":["A","B","D"],"source":"《中国石油大学（华东）本科生学籍管理规定》","category":"学籍管理","excerpt":"第二十三条学生参加学校认可的开放式网络课程学习、创新创业、社会实践等活动以及发表论文、获得专利授权等与专业学习、学业要求相关的经历、成果，经学校认定，可记为相应学分。"},{"id":178,"type":"multi","stem":"学生有以下哪些情形之一者,不得转学？","options":[["A","入学未满一学期或毕业前一年的"],["B","高考成绩低于拟转入学校相关专业同一生源地相应年份录取成绩的"],["C","由低学历层次转为高学历层次的"],["D","以定向就业招生录取的"],["E","无正当转学理由的"]],"answer":["A","B","C","D","E"],"source":"《中国石油大学（华东）本科生学籍管理规定》","category":"学籍管理","excerpt":"第二十六条学生有以下情形之一者，不得转学：1.入学未满一学期或毕业前一年的；2.高考成绩低于拟转入学校相关专业同一生源地相应年份录取成绩的；3.由低学历层次转为高学历层次的；4.以定向就业招生录取的；5.无正当转学理由的。"},{"id":179,"type":"multi","stem":"学生有以下哪些情形之一者,可以申请转专业？","options":[["A","对某专业有兴趣和专长,且转入该专业更能发挥特长的"],["B","学生主观上已努力学习,但确实存在学习上的特殊困难,不适合在原专业继续学习的"],["C","以定向就业招生录取的"],["D","休学创业或退役后复学的学生,因自身情况需要转专业的"],["E","学生通过自主选课获得学分满足拟转入专业准入要求的"]],"answer":["A","B","D","E"],"source":"《中国石油大学（华东）本科生学籍管理规定》","category":"学籍管理","excerpt":"第二十八条学生有以下情形之一者，可以申请转专业：1.对某专业有兴趣和专长，且转入该专业更能发挥特长的；2.学生通过自主选课获得学分满足拟转入专业准入要求的；3.因某种疾病或生理缺陷等身体原因，经校医院或校医院指定的二级甲等以上医院诊断证明，不适合在原专业继续学习的；4.学生主观上已努力学习，但确实存在学习上的特殊困难，不适合在原专业继续学习的；5.休学创业或退役后复学的学生，因自身情况需要转专业的。"},{"id":180,"type":"multi","stem":"学生有以下哪些情形之一者,应申请休学？","options":[["A","因病经校医院或校医院指定的二级甲等以上医院诊断后,须停课治疗、休养超过6周的"],["B","请假超过6周的"],["C","经学校认定同意创业休学的"],["D","因某种特殊原因,本人申请休学或学校认为须休学的"],["E","对所学专业暂时不感兴趣的"]],"answer":["A","B","C","D"],"source":"《中国石油大学（华东）本科生学籍管理规定》","category":"学籍管理","excerpt":"第三十二条学生转专业，应按学校规定办理手续；在未完成相关手续办理前，须参加原专业的学习。第六章休学、保留学籍与复学第三十三条学生有以下情形之一者，应申请休学：1.因病经校医院或校医院指定的二级甲等以上医院诊断后，须停课治疗、休养超过6周的（肝炎、肺结核等传染病患者须休学）；2.请假超过6周的；3.经学校认定同意创业休学的；4.因某种特殊原因，本人申请休学或学校认为须休学的。学生休学期间，学校为其保留学籍，但不享受在校学习学生待遇。"},{"id":181,"type":"multi","stem":"学生有以下哪些情形之一者,学校应予退学处理？","options":[["A","连续4学期每学期选课学分数均小于15学分的"],["B","未经批准连续两周未参加学校规定的教学活动的"],["C","试读不合格且本人未申请退学的"],["D","超过学校规定的期限未注册而又无正当理由的"],["E","学校规定的不能完成学业、应予退学的其他情形"]],"answer":["A","B","C","D","E"],"source":"《中国石油大学（华东）本科生学籍管理规定》","category":"学籍管理","excerpt":"……第四十条2.连续4学期每学期选课学分数均小于15学分的；3.休学、保留学籍期满，在学校规定的期限内未提出复学申请或者申请复学经复查不合格的；4.经校医院或校医院指定的二级甲等以上医院诊断，患有疾病或者意外伤残不能继续在校学习的；5.未经批准连续两周未参加学校规定的教学活动的；6.在学校规定的最长学习年限内未完成学业的；7.试读不合格且本人未申请退学的；8.超过学校规定的期限未注册而又无正当理由的；9.学校规定的不能完成学业、应予退学的其他情形。"},{"id":182,"type":"multi","stem":"学校鼓励和支持学生实行（）。学生可根据个人情况,合理、灵活地通过选课安排自己的学习进程,但在校学习年限不能超过学校规定的最长学习年限。","options":[["A","自我管理"],["B","自我服务"],["C","自我教育"],["D","自我监督"]],"answer":["A","B","C","D"],"source":"《中国石油大学（华东）本科生学籍管理规定》","category":"学籍管理","excerpt":"第四条学校鼓励和支持学生实行自我管理、自我服务、自我教育、自我监督。学生可根据个人情况，合理、灵活地通过选课安排自己的学习进程，但在校学习年限不能超过学校规定的最长学习年限。第二章入学与注册第五条新生须持高考准考证、录取通知书和身份证，按照录取通知书规定的时间报到。报到时，学校对新生入学资格进行初步审查，审查合格的办理入学手续，予以注册学籍；审查发现新生的录取通知、考生信息等证明材料，与本人实际情况不符，或者有其他违反国家招生考试规定情形的，取消其入学资格。因故不能按期入学的，须于新生报到入学期间向其所在院部请假，并报本科招生办公室备案，假期不得超过2周。未请假或请假逾期的，除因不可抗力等正当事由以外，视为放弃入学资格。"},{"id":183,"type":"multi","stem":"中国石油大学（华东）本科毕业生符合下列条件者可授予学士学位。","options":[["A","遵守中华人民共和国宪法和法律"],["B","完成本专业培养方案规定的各项要求"],["C","遵守学校的规章制度"],["D","必修课程学分绩≥70分"]],"answer":["A","B","C","D"],"source":"《中国石油大学（华东）学士学位授予办法》","category":"学籍管理","excerpt":""},{"id":184,"type":"multi","stem":"凡属下列情况之一者不授予学士学位","options":[["A","未按要求完成本专业的培养方案"],["B","必修课程学分＜70分"],["C","严重违背学术诚信，有考试作弊、剽窃他人学术成果"],["D","曾受记过及以上处分"]],"answer":["A","B","C","D"],"source":"《中国石油大学（华东）学士学位授予办法》","category":"学籍管理","excerpt":""},{"id":185,"type":"multi","stem":"学生在下列哪些情况下，应交清所欠学费方能正常办理离校手续？","options":[["A","毕业"],["B","结业"],["C","肄业"],["D","休学"]],"answer":["A","B","C"],"source":"《中国石油大学（华东）学分制收费管理暂行办法》","category":"学分制收费","excerpt":"第二十条学生毕业、结业、肄业离校时，应交清所欠学费方能正常办理离校手续。第四章附则第二十一条中外合作办学、校企合作办学的学费标准按照山东省有关部门批复执行。"},{"id":186,"type":"multi","stem":"有以下哪些情况之一者取消其双学位修读资格？","options":[["A","因违纪受到过记过及以上处分者"],["B","主修专业学习成绩明显下降者"],["C","在当年取得的双学位课程学分少于该学年双学位教学培养方案学分一半者"],["D","未按要求修读相关课程者"]],"answer":["A","B","C"],"source":"《中国石油大学（华东）本科生双学位培养管理办法》","category":"双学位与辅修","excerpt":""},{"id":187,"type":"multi","stem":"学生在修读辅修专业过程中,如果出现（）或（）时,学生所在院部有权取消其辅修资格,报教务处备案。","options":[["A","主修专业课程不及格"],["B","辅修专业课程不及格"],["C","主修专业课程成绩有明显下降"],["D","辅修专业课程成绩有明显下降"]],"answer":["A","C"],"source":"《中国石油大学（华东）本科生辅修培养管理办法》","category":"双学位与辅修","excerpt":""},{"id":188,"type":"multi","stem":"辅修专业培养方案由辅修专业开设院部制定,所设课程应是本专业的主要（）和（）。","options":[["A","专业基础课"],["B","专业限选课"],["C","专业课"],["D","选修课"]],"answer":["A","C"],"source":"《中国石油大学（华东）本科生辅修培养管理办法》","category":"双学位与辅修","excerpt":""},{"id":189,"type":"multi","stem":"因创业休学的学生，有下列哪些情况之一者,可申请复学？","options":[["A","创业休学期满"],["B","创业休学期未满,但主动提出复学申请"],["C","无理由"],["D","年度审查认定为不适合继续创业休学"]],"answer":["A","B","D"],"source":"《中国石油大学（华东）本科生创新创业学籍管理办法（试行）》","category":"创新创业","excerpt":"第十二条学分记载及资料存档工作由学生所在院（部）负责。第五章复学第十三条有下列情况之一者，可申请复学：1.创业休学期满；2.创业休学期未满，但主动提出复学申请；3.年度审查认定为不适合继续创业休学。"},{"id":190,"type":"multi","stem":"学生创业实践可申请认定为自主发展计划学分,每学年最高计（）分,累计不超过（）分。","options":[["A","4"],["B","5"],["C","8"],["D","10"]],"answer":["A","D"],"source":"《中国石油大学（华东）本科生创新创业学籍管理办法（试行）》","category":"创新创业","excerpt":""},{"id":191,"type":"multi","stem":"每年12月底前,创业休学学生须向所在院（部）提交项目进展报告,创业满1年的还需提交（）或（）,由院（部）创新创业教育领导小组认定、学校创新创业教育工作领导小组办公审定。","options":[["A","完税证明"],["B","免税证明"],["C","缴税证明"],["D","营业执照副本"]],"answer":["A","B"],"source":"《中国石油大学（华东）本科生创新创业学籍管理办法（试行）》","category":"创新创业","excerpt":"第六条每年12月底前，创业休学学生须向所在院（部）提交项目进展报告，创业满1年的还需提交完税证明或免税证明，由院（部）创新创业教育领导小组认定、学校创新创业教育工作领导小组办公室审定。对于在创业休学期间创业项目无实际进展，或从事与创业计划无关活动，经认定不适合继续创业者，应终止休学。第四章学分认定第七条学生参加创新活动、创业实践，可申请学分认定。同一创新创业实践活动不可重复申请认定。"},{"id":192,"type":"multi","stem":"学生参加（）等创新活动,可申请认定为自主发展计划中的科技创新学分。","options":[["A","学科竞赛"],["B","课外科技活动"],["C","创新项目研究"],["D","发表论文"],["E","获得专利"]],"answer":["A","B","C","D","E"],"source":"《中国石油大学（华东）本科生创新创业学籍管理办法（试行）》","category":"创新创业","excerpt":"第八条学生参加学科竞赛、课外科技活动、创新项目研究、发表论文、获得专利等创新活动，可申请认定为自主发展计划（第二课堂）中的创新创业学分。"},{"id":193,"type":"multi","stem":"在优良学风班评选过程中，符合以下哪些情况之一者不得申报或取消其当年评选资格？","options":[["A","凡班级有学生在评选当年受到学校处分者"],["B","凡班级申报材料弄虚作假者"],["C","凡班级党团组织建设不全者"],["D","凡班级未获得集体荣誉者"]],"answer":["A","B"],"source":"《中国石油大学(华东)优良学风班评选办法》","category":"优良学风班","excerpt":"二、评选标准1.评选优良学风班需具备以下条件：（1）全班学生政治思想状况良好，拥护党的路线、方针、政策；（2）全班学生学习态度端正，学习目的明确，学习气氛浓厚；（3）全班学生遵守法纪，遵守《高等学校学生行为准则》和学校的各项规章制度；（4）班集体凝聚力强，开展集体活动效果良好；（5）全班学生学习效果显著：各门必修课程考试及格率达95%，优良率达60%，各种竞赛成绩和课外科技活动成果突出。2.优良学风标兵班从优良学风班中选出。3.符合以下任一项者不得申报或取消其当年评选资格：（1）凡班级有学生在评选当年受到学校处分者；（2）凡班级申报材料弄虚作假者，一经发现，取消其评奖资格，并不得参加下一年度的申报。"},{"id":194,"type":"multi","stem":"评选优良学风班需具备以下哪些条件?","options":[["A","全班学生学习态度端正,学习目的明确,学习气氛浓厚"],["B","全班学生政治思想状况良好,拥护党的路线、方针、政策"],["C","全班学生遵守法纪,遵守《高等学校学生行为准则》和学校的各项规章制度"],["D","班集体凝聚力强,开展集体活动效果良好"],["E","全班学生学习效果显著"]],"answer":["A","B","C","D","E"],"source":"《中国石油大学(华东)优良学风班评选办法》","category":"优良学风班","excerpt":"二、评选标准1.评选优良学风班需具备以下条件：（1）全班学生政治思想状况良好，拥护党的路线、方针、政策；（2）全班学生学习态度端正，学习目的明确，学习气氛浓厚；（3）全班学生遵守法纪，遵守《高等学校学生行为准则》和学校的各项规章制度；（4）班集体凝聚力强，开展集体活动效果良好；（5）全班学生学习效果显著：各门必修课程考试及格率达95%，优良率达60%，各种竞赛成绩和课外科技活动成果突出。2.优良学风标兵班从优良学风班中选出。3.符合以下任一项者不得申报或取消其当年评选资格：（1）凡班级有学生在评选当年受到学校处分者；（2）凡班级申报材料弄虚作假者，一经发现，取消其评奖资格，并不得参加下一年度的申报。"},{"id":195,"type":"multi","stem":"学生（）、开除学籍以及自愿申请退宿的，应当按照学校规定的流程办理退宿手续。","options":[["A","毕业"],["B","退学"],["C","休学"],["D","转学"],["E","出国"]],"answer":["A","B","C","D","E"],"source":"《中国石油大学（华东）学生公寓管理规定》","category":"学生公寓","excerpt":"第十条学生毕业、退学、休学、转学、出国、开除学籍以及自愿申请退宿的，应当按照学校规定的流程办理退宿手续，物业公司对学生宿舍进行检查，对丢失或损坏公共物品者，要追究赔偿责任。对故意损坏者，责令其赔偿相应损失，结清相关费用后，在规定时间内搬离宿舍。本校本科生、硕士生毕业后继续在我校攻读硕士学位、博士学位者，应按时办理毕业离校退宿手续，在规定时间入校时，再按相关要求办理住宿手续。"},{"id":196,"type":"multi","stem":"下列哪一项不允许在学生公寓内发生？","options":[["A","私自改电线路"],["B","饲养仓鼠"],["C","离开宿舍切断电源"],["D","卫生整洁"]],"answer":["A","B"],"source":"《中国石油大学（华东）学生公寓管理规定》","category":"学生公寓","excerpt":""},{"id":197,"type":"multi","stem":"以下哪种方式不允许在学生公寓内进行？","options":[["A","长明灯"],["B","长流水"],["C","使用易燃易爆物品"],["D","发放广告宣传单"],["E","损坏公共设施"]],"answer":["A","B","C","D","E"],"source":"《中国石油大学（华东）学生公寓管理规定》","category":"学生公寓","excerpt":""},{"id":198,"type":"multi","stem":"以下哪种方式不允许在学生公寓内进行？","options":[["A","装饰"],["B","出租"],["C","出借"],["D","私自加床"]],"answer":["B","C","D"],"source":"《中国石油大学（华东）学生公寓管理规定》","category":"学生公寓","excerpt":"第七条学生入学时与物业公司签订《入住承诺书》，学生按照学校规定流程办理入住手续后方可入住指定床位，要爱护室内门窗、桌椅、衣橱等公共设施。学生不得将床位出借、出租、私自加床或作其他用途。"},{"id":199,"type":"multi","stem":"学生公寓严禁（）等，严禁用任何方式自炊。","options":[["A","酗酒"],["B","抽烟"],["C","点蜡烛"],["D","焚烧物品"],["E","燃放鞭炮"]],"answer":["A","B","C","D","E"],"source":"《中国石油大学（华东）学生公寓管理规定》","category":"学生公寓","excerpt":"第二十六条学生公寓严禁酗酒、抽烟、点蜡烛、焚烧物品、燃放鞭炮等，严禁用任何方式自炊。"},{"id":200,"type":"multi","stem":"学生公寓内严禁使用（）。","options":[["A","明火"],["B","手机充电器"],["C","电暖器"],["D","防限电插座"]],"answer":["A","C","D"],"source":"《中国石油大学（华东）学生公寓管理规定》","category":"学生公寓","excerpt":""},{"id":201,"type":"multi","stem":"学生公寓凭借校园一卡通刷卡进入，严禁（）。","options":[["A","攀爬阳台进入"],["B","带领陌生人进入公寓"],["C","将校园一卡通转借他人"],["D","攀爬窗户进入"]],"answer":["A","B","C","D"],"source":"《中国石油大学（华东）学生公寓管理规定》","category":"学生公寓","excerpt":""},{"id":202,"type":"multi","stem":"严禁在学生公寓内进行（）。","options":[["A","传销活动"],["B","封建迷信活动"],["C","娱乐阅读活动"],["D","传教活动"]],"answer":["A","B","D"],"source":"《中国石油大学（华东）学生公寓管理规定》","category":"学生公寓","excerpt":"第四十五条严禁在学生公寓内进行传销活动、封建迷信活动、宗教活动、传教活动。"},{"id":203,"type":"multi","stem":"关于宿舍门锁和钥匙，不得（）。","options":[["A","随意复制钥匙"],["B","转借舍友钥匙"],["C","私自换锁"],["D","另加门锁"]],"answer":["A","C","D"],"source":"《中国石油大学（华东）学生公寓管理规定》","category":"学生公寓","excerpt":""},{"id":204,"type":"multi","stem":"学校设立学生申诉处理委员会（以下简称申诉委），专门负责处理本校接受普通高等学历教育的（）（以下简称学生）因学校对其作出的处理或者处分决定不服而提出的申诉。","options":[["A","研究生"],["B","本科生"],["C","留学生"],["D","博士生"]],"answer":["A","B"],"source":"《中国石油大学（华东）学生申诉处理办法（修订）》","category":"申诉处理","excerpt":"第二条学校设立学生申诉处理委员会（以下简称申诉委），专门负责处理本校接受普通高等学历教育的研究生和本科生（以下简称学生）因学校对其作出的处理或者处分决定不服而提出的申诉。"},{"id":205,"type":"multi","stem":"申诉委主任由学校监察处处长担任，委员组成原则上应由学校相关负责人、职能部门负责人、（）、负责法律事务的相关机构负责人等组成，学生代表人数应占到委员总人数的1/5以上。","options":[["A","学生家长"],["B","教师代表"],["C","学生代表"],["D","家长委员会"]],"answer":["B","C"],"source":"《中国石油大学（华东）学生申诉处理办法（修订）》","category":"申诉处理","excerpt":"第三条申诉委以公平、公正为原则，以保障和维护学生合法权益为宗旨，对学生申诉的学校具体管理行为的合法性进行复查。第二章机构设置及职能第四条申诉委主任由学校监察处处长担任，委员组成原则上应由学校相关负责人、职能部门负责人、教师代表、学生代表、负责法律事务的相关机构负责人等组成，另外可以聘请校外法律、教育等方面专家参加，学生代表人数应占到委员总人数的1/5以上。具体人数及来源根据学生申诉的具体情况决定，同时根据申诉事由，应邀请相关人员列席会议。直接参与处理学生申诉事由的人员不得为申诉委委员。"},{"id":206,"type":"multi","stem":"自主发展计划学分里至少要取得2个学分的有哪些模块","options":[["A","社会实践"],["B","创新创业"],["C","文体发展"],["D","技能培训"]],"answer":["A","B","C"],"source":"中国石油大学(华东)本科生自主发展计划","category":"自主发展计划","excerpt":"第三条对学生按照学校本科生自主发展计划要求取得的自主发展计划学分，明确具体要求，其中思想成长类不少于1个学分，创新创业类不少于1.5个学分，社会实践与志愿服务类不少于1.5个学分，文体发展类不少于1个学分，工作履历与技能培训不做学分要求。"},{"id":207,"type":"multi","stem":"大学生创业基金主要来源于（）。","options":[["A","学校拨款"],["B","社会捐赠"],["C","创业项目自身投资收益"],["D","自筹"]],"answer":["A","B","C"],"source":"中国石油大学(华东)大学生创业实践管理办法","category":"创新创业","excerpt":"第七条基地管理服务：1.入驻的项目由办公室统一管理，应定期向办公室提交项目运行情况报告，并接受中期检查和期满验收考核。2.入驻的项目可免缴场地租用费，免费享受创业培训、创业指导等服务，免费参加创业经验交流等活动。3.入驻的项目提前退出时，须提前提出书面申请，报办公室审核后，办理退出手续。第四章创业基金第八条创业基金主要来源于学校拨款、社会捐赠及创业项目自身投资收益。"},{"id":208,"type":"multi","stem":"以下属于我校校级大学生创业基地的是（）。","options":[["A","创业孵化基地"],["B","创客空间"],["C","大学科技园创业孵化器"],["D","学生创新实践中心"]],"answer":["A","B","C","D"],"source":"中国石油大学(华东)大学生创业实践管理办法","category":"创新创业","excerpt":"第三条大学生创业协会作为校级学生组织，负责全校大学生创业氛围的营造和创业活动的开展，协助办公室负责创业项目和创业基地的管理。第三章创业基地第四条校级大学生创业基地包括学生创新实践中心、创业孵化基地、创客空间和大学科技园创业孵化器。"},{"id":209,"type":"multi","stem":"图书借阅期限有哪几种类型？（ ）","options":[["A","所有读者均 60天"],["B","教职工、研究生120天"],["C","本科生 30天"],["D","校外读者 60天"]],"answer":["B","C","D"],"source":"中国石油大学（华东）图书馆开架书库借阅管理规定","category":"图书馆","excerpt":"……四、读者类型最大续借次数最大借书量|借期教职工、研究生2次不限|120天本科生、留学生2次不限|30天校外读者2次2册|60天读者所借图书须按期归还，有逾期未还图书将导致无法继续借阅图书。"},{"id":210,"type":"multi","stem":"图书归还时所产生的超期费如何缴纳？图书续借怎么办？如果不及时归还会有什么影响？（ ）","options":[["A","超期费可在各开架书库刷卡缴纳"],["B","读者可通过“网上图书馆”或各服务台续借图书"],["C","每本图书仅能续借1次"],["D","所借图书超过借阅期限，每册每超1天交纳资源占用费0.1元"]],"answer":["A","B","D"],"source":"中国石油大学（华东）图书馆开架书库借阅管理规定","category":"图书馆","excerpt":""},{"id":211,"type":"multi","stem":"读者从图书馆所借的图书丢失了应该如何赔偿？（ ）","options":[["A","购买原版图书赔偿"],["B","原价直接赔偿"],["C","视图书的出版年份处以原价的最低3倍赔偿"],["D","置之不理"]],"answer":["A","C"],"source":"中国石油大学（华东）图书馆开架书库借阅管理规定","category":"图书馆","excerpt":""},{"id":212,"type":"multi","stem":"将条形码更换撕毁、故意损毁图书资料磁条、不办理借阅手续将书带出书库等视为偷窃图书资料行为，应当如何让处置？（ ）","options":[["A","处以图书资料价格10倍罚款"],["B","停止其继续使用图书馆的资格"],["C","在图书馆张榜公布进行批评，并通报当事人所在学院或单位，情节严重的报学校从严处分"],["D","不处罚"]],"answer":["A","B","C"],"source":"中国石油大学（华东）图书馆开架书库借阅管理规定","category":"图书馆","excerpt":"……六、偷窃图书资料者，处以图书资料价格10倍罚款，停止其继续使用图书馆的资格，在图书馆张榜公布进行批评，并通报当事人所在学院或单位，情节严重的报学校从严处分。"},{"id":213,"type":"multi","stem":"请读者自觉爱护图书，不得在书上（ ）","options":[["A","圈划"],["B","撕页"],["C","毁坏条码"],["D","毁坏磁条"]],"answer":["A","B","C","D"],"source":"中国石油大学（华东）图书馆开架书库借阅管理规定","category":"图书馆","excerpt":""},{"id":214,"type":"multi","stem":"我校进入双一流学科建设的学科是（）。","options":[["A","石油与天然气工程"],["B","地质资源与地质工程"],["C","石油工程"],["D","油气储运工程"]],"answer":["A","B"],"source":"《学校概况》 无》","category":"学校概况","excerpt":"学科专业覆盖石油石化工业的各个领域，石油主干学科总体水平处于国内领先地位。有16个博士学位授权一级学科，7个博士学位授权自主设置二级学科，6个博士学位授权自主设置交叉学科，34个硕士学位授权一级学科，58个本科招生专业，13栿个博士后流动站。拥有矿产普查与勘探、油气井工程、油气田开发工程、化学工艺、油气储运工程等5个国家重点学科，以及地球探测与信息技术、工业催化等2个国家重点（培育）学科。工程学、化学、材料科学、地球科学、计算机科学、环境与生态学、社会科学总论、数学、物理学等9个学科领域进入ESI全球学科排名前1%，其中工程学、化学、地球科学、材料科学进入ESI全球学科排名前1曤。地质资源与地质工程、石油与天然气工程2个一级学科入选国家“双一流”建设计划。"},{"id":215,"type":"multi","stem":"我校现已成为为一所（）的大学。","options":[["A","以工为主"],["B","以理工为主"],["C","石油石化特色鲜明"],["D","多学科协调发展"]],"answer":["A","C","D"],"source":"《学校概况》 前言 第I页》","category":"学校概况","excerpt":"栺学校概况中国石油大学（华东）是教育部直属全国重点大学，是国家“211工程”重点建设和开展“985工程优势学科创新平台”建设并建有研究生院的高校之一。学校是教育部和五大能源企业集团公司、教育部和山东省人民政府共建的高校，是石油石化高层次人才培养的重要基地，被誉为“石油科技、管理人才的摇篮”，现已成为一所以工为主、石油石化特色鲜明、多学科协调发展的大学。2017年、2022年均进入国家“双一流”建设高校行列。"},{"id":216,"type":"multi","stem":"以下属于我校二级教学院部的是（）。","options":[["A","石油工程学院"],["B","机电工程学院"],["C","荟萃学院"],["D","后备军官学院"]],"answer":["A","B"],"source":"《学校概况》 前言 第Ⅱ页》","category":"学校概况","excerpt":"学校总占地面积5000余亩，建筑面积170余万平方米，发展形成了“两校区一园区”（青岛唐岛湾校区、古镇口校区以及东营科教园区）的办学格局。青岛两校区地处迷人的帆船之都、海滨之城，享有极高美誉的青岛，东营科教园区地处黄河三角洲的中心城市、生态之城、石油之城———山东东营，“两校区一园区”均位于“蓝黄”两大国家战略重点区域，同时青岛两校区还处于2014年新设立的国家级新区———青岛西海岸新区。学校建有研究生院，有地球科学与技术学院，石油工程学院，化学化工学院，机电工程学院，储运与建筑工程学院，材料科学与工程学院，石大山能新能源学院，海洋与空间信息学院，控制科学与工程学院，青岛软件学院、计算机科学与技术学院，理学院，经济管理学院，外国语学院，文法学院，马克思主义学院，体育教学部等16个教学学院（部），以及荟萃学院、国际教育学院、远程教育学院和继续教育学院。"},{"id":217,"type":"multi","stem":"以下属于我校国家及省部重点实验室和研究机构的是（）。","options":[["A","重质油国家重点实验室"],["B","海洋物探及勘探设备国家工程实验室"],["C","油气加工新技术教育部工程研究中心"],["D","石油石化新型装备与技术教育部工程研究中心"]],"answer":["A","B","C","D"],"source":"《学校概况》 前言 第Ⅳ页》","category":"学校概况","excerpt":""},{"id":218,"type":"multi","stem":"以下说法中属于好学乐业表现的是（）。","options":[["A","以学习为中心,走全面发展之路,践行“勤奋、严谨、求实、创新”优良学风。"],["B","夯实专业基础,善于独立思考,培养自主学习能力。"],["C","只要学好专业知识,就能提高综合素质，应尽量减少课外活动以保证充足的学习时间。"],["D","增强心理素质,勇于面对学习困难和挫折。"]],"answer":["A","B","D"],"source":"《中国石油大学（华东）学生文明行为规范》","category":"其他","excerpt":"……1.以学习为中心，走全面发展之路，践行“勤奋、严谨、求实、创新”优良学风。2.树立学习目标，制定学习计划，主动规划个人学业发展。3.激发学习兴趣，加强时间管理，提高学习效率。4.夯实专业基础，善于独立思考，培养自主学习能力。5.注重课外拓展，培养创新意识，提高综合素质。6.互帮互助、取长补短，形成比、学、赶、帮、超的良好氛围。7.增强心理素质，勇于面对学习困难和挫折。"},{"id":219,"type":"multi","stem":"以下说法中属于诚信守纪表现的是（）。","options":[["A","遵守宪法、法律法规，不参加非法组织和活动，但大学生属于弱势群体，为保护自身安全，应尽量减少与违纪违法行为的冲突，减少斗争。"],["B","遵守校规校纪，自觉维护正常的学习生活秩序。"],["C","遵守考试纪律，诚信应考，不作弊。"],["D","选择正常渠道和合理方式反映意见和诉求，不损害他人利益。"]],"answer":["B","C","D"],"source":"《中国石油大学（华东）学生文明行为规范》","category":"其他","excerpt":""},{"id":220,"type":"multi","stem":"以下行为属于遵守教室文明规范的是（）。","options":[["A","遵守课堂纪律,不迟到、不早退、不旷课。"],["B","上课专心听讲,手机关机或调成震动、静音，不接打电话、收发短信，浏览网页。"],["C","课间休息时，不大声喧哗，主动擦黑板，整理讲台。"],["D","仪容整洁、衣着大方,不穿拖鞋、背心、超短裤、超短裙等进入教室。"]],"answer":["A","B","C","D"],"source":"《中国石油大学（华东）学生文明行为规范》","category":"其他","excerpt":""},{"id":221,"type":"multi","stem":"以下行为属于遵守教室文明规范的是（）。","options":[["A","爱护教学设施,不乱刻乱画,不拆移或损坏室内设备。"],["B","不在教室内占座、聊天、睡觉、看电影,不随便占用教室从他与学习无关的活动。"],["C","保持教室卫生,不在教室内抽烟、乱扔垃圾、随地吐痰等。"],["D","不带食品进入教室,不在教室吃东西。"]],"answer":["A","B","C","D"],"source":"《中国石油大学（华东）学生文明行为规范》","category":"其他","excerpt":""},{"id":222,"type":"multi","stem":"关于在图书馆中的行为举止，以下说法中正确的是（）。","options":[["A","刷卡入馆,按时离馆。衣着得体,不穿拖鞋。"],["B","遵章守纪,举止文明。自觉不占座,规范乘电梯。"],["C","保持安静,交谈低声。不在馆内朗读,手机震动静音。"],["D",".公共空间,保持卫生。不带食品,严禁吸烟。"]],"answer":["A","B","C","D"],"source":"《中国石油大学（华东）学生文明行为规范》","category":"其他","excerpt":""},{"id":223,"type":"multi","stem":"关于在计算机机房中的行为举止，以下说法中正确的是（）。","options":[["A","严格按规程操作机器,不随便操作教师主控台机器。"],["B","机房内保持安静,控制音响音量,手机关机或调成震动、静音,不接打电话。"],["C","自由上机时,不玩游戏,不浏览色情网站。"],["D","上机结束后,将设备整理好放回原位。"]],"answer":["A","B","C","D"],"source":"《中国石油大学（华东）学生文明行为规范》","category":"其他","excerpt":"……二、3.严格按规程操作机器，不随便操作教师主控台机器。4.爱护设备，不重敲键盘，不移动设备，不乱拔网线、电源线等。5.认真完成老师布置的上机任务，不从事与上机无关的事情。6.机房内保持安静，控制音响音量，手机关机或调成震动、静音，不接打电话。7.自由上机时，不玩游戏，不浏览色情网站。8.上机结束后，将设备整理好放回原位。"},{"id":224,"type":"multi","stem":"以下行为中属于遵守宿舍文明规范的是（）。","options":[["A","遵守公寓管理规定,自觉营造安全、文明、整洁的生活和学习环境。"],["B","出入公寓时,主动配合工作人员检查,刷卡进入,不翻越阳台。"],["C","访客进入宿舍时,应主动问好,热情交谈,访客离开时应起身相送。"],["D","严禁无故夜不归宿,晚归要主动如实登记并说明原因。"]],"answer":["A","B","C","D"],"source":"《中国石油大学（华东）学生文明行为规范》","category":"其他","excerpt":"……三、1.遵守公寓管理规定，自觉营造安全、文明、整洁的生活和学习环境。2.出入公寓时，主动配合工作人员检查，刷卡进入，不翻越阳台。3.遵守作息制度，按时起床就寝，合理制定并严格执行宿舍值日制度。4.起床后及时整理内务卫生，保持床铺、桌面、地面、阳台干净整洁。5.宿舍环境布置要健康向上、高雅大方，不乱拉电线、网线，不乱贴乱画。6.宿舍同学间团结互助，和睦相处，营造温馨的宿舍氛围。7.访客进入宿舍时，应主动问好，热情交谈，访客离开时应起身相送。8.严禁无故夜不归宿，晚归要主动如实登记并说明原因。"},{"id":225,"type":"multi","stem":"以下行为中属于遵守宿舍文明规范的是（）。","options":[["A","公寓内不抽烟、不酗酒,不大声喧哗,不饲养宠物,不留宿他人。"],["B","不将易燃、易爆物品带入宿舍,不使用明火,不焚烧杂物,不使用违规电器,不在宿舍内做饭。"],["C","增强自我防范意识,休息或外出时锁好门、关好窗、关闭电源,发现可疑人员立即询问、报告。"],["D","尊重宗教活动自由，可一定程度上在公寓内从事小规模的宗教活动,但禁止在公寓内张贴、散发宗教类宣传品。"]],"answer":["A","B","C"],"source":"《中国石油大学（华东）学生文明行为规范》","category":"其他","excerpt":"……三、9.公寓内不抽烟、不酗酒，不大声喧哗，不饲养宠物，不留宿他人。10.不将易燃、易爆物品带入宿舍，不使用明火，不焚烧杂物，不使用违规电器，不在宿舍内做饭。11.增强自我防范意识，休息或外出时锁好门、关好窗、关闭电源，发现可疑人员立即询问、报告。"},{"id":226,"type":"multi","stem":"现代生活越来越离不开网络，以下说法中正确的是（）。","options":[["A","合理安排上网时间,不占用正常的学习时间上网,不通宵上网以免影响他人的正常作息。"],["B","合理使用网络,利用网络资源充实自己,不沉迷于网络游戏或网络小说。"],["C","遵守不同网站和论坛的相关规则,不进行网络欺诈、网络赌博、网络恶意投票等行为。"],["D","增强自我保护意识,不轻易相信网络信息,不随意与网友见面。"]],"answer":["A","B","C","D"],"source":"《中国石油大学（华东）学生文明行为规范》","category":"其他","excerpt":"……三、1.合理安排上网时间，不占用正常的学习时间上网，不通宵上网以免影响他人的正常作息。2.合理使用网络，利用网络资源充实自己，不沉迷于网络游戏或网络小说。3.遵守不同网站和论坛的相关规则，不进行网络欺诈、网络赌博、网络恶意投票等行为。4.增强自我保护意识，不轻易相信网络信息，不随意与网友见面。"},{"id":227,"type":"multi","stem":"现代生活越来越离不开网络，以下说法中正确的是（）。","options":[["A","明辨网络信息,保持清醒头脑,不造谣,不信谣,不传谣。"],["B","文明上网,不使用粗俗和挑衅的语言,不对他人进行人身攻击,不公开他人隐私。"],["C","不浏览不良信息,不转发、推送不文明、不健康的信息或邮件,不观看或传播色情网站。"],["D","大的门户网站推送的信息都是经过严格审查的，可以根据标题直接转发，以尽快起到宣传效果。"]],"answer":["A","B","C"],"source":"《中国石油大学（华东）学生文明行为规范》","category":"其他","excerpt":"……三、5.明辨网络信息，保持清醒头脑，不造谣，不信谣，不传谣。6.文明上网，不使用粗俗和挑衅的语言，不对他人进行人身攻击，不公开他人隐私。7.不浏览不良信息，不转发、推送不文明、不健康的信息或邮件，不观看或传播色情网站。"},{"id":228,"type":"multi","stem":"学生综合素质测评工作分（）、班级测评、（）、院部复核和学校审批五个步骤进行。","options":[["A","个人测评"],["B","个人自评"],["C","年级测评"],["D","学联测评"]],"answer":["B","C"],"source":"《中国石油大学（华东）学生综合素质测评办法（试行）》","category":"综合素质测评","excerpt":"……第七条第三章测评流程第八条学生综合素质测评工作分个人自评、班级测评、年级测评、院部复核和学校审批五个步骤进行。（一）个人自评：学生根据自己日常表现，向班级测评小组提交相关证明材料。（二）班级测评：班级测评小组据实做好每名学生的专业学习、基础性素质和发展性素质测评工作。其中，基础性素质成绩根据记实和评议得出；发展性素质成绩根据学生所获荣誉、奖励及实际参加各类活动情况记实得出。（三）年级测评：辅导员带领班长审核班级测评成绩，进行年级专业排名，并向院部学生综合素质测评工作小组提交测评结果。"},{"id":229,"type":"multi","stem":"学生综合素质测评成绩由以下哪些部分组成。","options":[["A","专业学习测评成绩"],["B","基础性素质测评成绩"],["C","发展性素质测评成绩"],["D","第二课堂素质测评成绩"]],"answer":["A","B","C"],"source":"《中国石油大学（华东）学生综合素质测评办法（试行）》","category":"综合素质测评","excerpt":"……第七条第四章测评体系第九条学生综合素质测评成绩由专业学习测评成绩、基础性素质测评成绩和发展性素质测评成绩按一定比例计算得出。……计算公式为：学生综合素质测评成绩=专业学习测评成绩暳80%+基础性素质测评成绩暳10%+发展性素质测评成绩暳10%。……（一）专业学习测评专业学习测评成绩计算公式如下：专业学习测评成绩（平均学分绩点）=暺（Ii暳Xi）暺XiIi：修读课程绩点=修读课程成绩/10-5Xi：所选课程学分计算平均学分绩点时，课程成绩不足60分的，课程绩点记为0；五级记分制与百分制的对应关系：优秀-95，良好-85，中等-75，及格-65，不及格-40；二级记分制与百分制的对应关系：通过-80，不通过-40。……当学年所有课程按参加考试所得分数计入测评。……（二）基础性素质测评……1.基础性素质内容包括：思想政治表现、道德品质修养、身心健康素质、日常行为规范4类测评指标，满分100分。……思想政治表现：主要评议学生政治表现、思想水平、法纪观念等。……道德品质修养：主要评议学生道德品质、集体观念、劳动观念、生活态度等。……身心健康素质：主要评议学生体育活动情况、体能测试情况、心理健康状况等。……日常行为规范：主要评议学生遵守校规校纪情况、《学生文明行为规范》及《学生公寓管理规定》表现等。……基础性素质测评成绩由“记实”分值与“评议”分值相加组成，“记实”分值占60%，“评议”分值占40%，最终成绩分为“A”、“B”、“C”、“D”四个等级，其中，评定等级为“A”的比例不超过50%。……成绩曒90分评定等级为“A”；90分>成绩曒80分评定等级为“B”；80分>成绩曒60分评……"},{"id":230,"type":"multi","stem":"基础性素质内容包括（）等测评指标,满分100分。","options":[["A","思想政治表现"],["B","道德品质修养"],["C","身康素质"],["D","日常行为规范"]],"answer":["A","B","C","D"],"source":"《中国石油大学（华东）学生综合素质测评办法（试行）》","category":"综合素质测评","excerpt":""},{"id":231,"type":"multi","stem":"基础性素质测评成绩由（）分值与（）分值相加组成。","options":[["A","记实"],["B","评议"],["C","必修"],["D","选修"]],"answer":["A","B"],"source":"《中国石油大学（华东）学生综合素质测评办法（试行）》","category":"综合素质测评","excerpt":"……第七条其中，基础性素质成绩根据记实和评议得出；发展性素质成绩根据学生所获荣誉、奖励及实际参加各类活动情况记实得出。……（三）年级测评：辅导员带领班长审核班级测评成绩，进行年级专业排名，并向院部学生综合素质测评工作小组提交测评结果。……（四）院部复核：院部学生综合素质测评工作小组对测评结果进行复核，确认无误后公示3天。……若有异议，院部学生综合素质测评工作小组要根据反映情况是否属实及时做出解释或调整；如无异议，将结果报党委学生工作部、武装部。……（五）学校审批：学校学生综合素质测评工作领导小组对各院部测评结果进行审批。……第四章测评体系第九条学生综合素质测评成绩由专业学习测评成绩、基础性素质测评成绩和发展性素质测评成绩按一定比例计算得出。……计算公式为：学生综合素质测评成绩=专业学习测评成绩暳80%+基础性素质测评成绩暳10%+发展性素质测评成绩暳10%。……（一）专业学习测评专业学习测评成绩计算公式如下：专业学习测评成绩（平均学分绩点）=暺（Ii暳Xi）暺XiIi：修读课程绩点=修读课程成绩/10-5Xi：所选课程学分计算平均学分绩点时，课程成绩不足60分的，课程绩点记为0；五级记分制与百分制的对应关系：优秀-95，良好-85，中等-75，及格-65，不及格-40；二级记分制与百分制的对应关系：通过-80，不通过-40。……当学年所有课程按参加考试所得分数计入测评。……（二）基础性素质测评……1.基础性素质内容包括：思想政治表现、道德品质修养、身心健康素质、日常行为规范4类测评指标，满分100分。……思想政治表现：主要评议学生政治表现、思想水平、法纪观念等。……道德品质修养……"},{"id":232,"type":"multi","stem":"我校的奖学金的类别主要有（）。","options":[["A","综合奖学金"],["B","单项奖学金"],["C","专项奖学金"],["D","集体奖学金"]],"answer":["A","B","C","D"],"source":"《中国石油大学（华东）学生奖学金管理细则》","category":"奖学金与资助","excerpt":"……第五条第二章奖学金的类型、标准与比例第六条奖学金分为综合奖学金、单项奖学金、专项奖学金、集体奖学金四大类。……（一）综合奖学金……1.国家奖学金奖励对象：国家奖学金由中央政府出资设立，用于奖励在德、智、体、美、劳等方面全面发展，综合素质特别优秀的学生。……奖励标准：8000元/人。……评选要求：国家奖学金每学年评选1次，名额由教育部下达，学生基础性素质测评等级为“A”方可参评，具体评选标准参照《中国石油大学（华东）本科生国家奖学金、国家励志奖学金、国家助学金实施细则》执行。……2.国家励志奖学金奖励对象：国家励志奖学金由中央和地方政府共同出资设立，用于奖励资助勤奋学习、努力进取，在德、智、体、美、劳等方面全面发展，品学兼优的家庭经济困难的学生。……奖励标准：5000元/人。……评选要求：国家励志奖学金每学年评选1次，名额由教育部下达，具体评选标准参照《中国石油大学（华东）本科生国家奖学金、国家励志奖学金、国家助学金实施细则》执行。……3.综合优秀奖学金奖励对象：奖励品学兼优，综合素质全面发展的学生。……奖励标准：该奖项分为三个等级：一等奖学金4000元/人，按学生数的3%评定；二等奖学金2000元/人，按学生数的7%评定；三等奖学金1000元/人，按学生数的15%评定。……评选要求：参评学生应为二年级以上（含二年级）学生。……各院部严格按照《中国石油大学（华东）学生综合素质测评办法》的标准，对学生进行综合素质测评。……4.企事业奖学金奖励对象：奖励品学兼优，综合素质全面发展，符合设奖单位（个人）评选要求的学生。……奖励标准：奖励标准和奖励名额由学校与设奖单位（个人）协商确定……"},{"id":233,"type":"multi","stem":"单项奖学金主要奖励在校生某一方面表现特别突出的情况，主要包括（）。","options":[["A","学习优秀奖学金"],["B","社会工作奖学金"],["C","文体奖学金"],["D","科技创新奖学金"],["E","学习进步奖学金"],["F","突出成绩奖学金"]],"answer":["A","B","C","D","E","F"],"source":"《中国石油大学（华东）学生奖学金管理细则(试行)》","category":"奖学金与资助","excerpt":""},{"id":234,"type":"multi","stem":"综合奖学金是指考虑学生多方面综合情况发放的奖学金，主要包括（）。","options":[["A","国家奖学金"],["B","国家励志奖学金"],["C","综合优秀奖学金"],["D","学习优秀奖学金"],["E","企事业奖学金"]],"answer":["A","B","C","E"],"source":"《中国石油大学（华东）学生奖学金管理细则(试行)》","category":"奖学金与资助","excerpt":"……第五条1.国家奖学金奖励对象：国家奖学金由中央政府出资设立，用于奖励在德、智、体、美、劳等方面全面发展，综合素质特别优秀的学生。奖励标准：8000元/人。评选要求：国家奖学金每学年评选1次，名额由教育部下达，学生基础性素质测评等级为“A”方可参评，具体评选标准参照《中国石油大学（华东）本科生国家奖学金、国家励志奖学金、国家助学金实施细则》执行。2.国家励志奖学金奖励对象：国家励志奖学金由中央和地方政府共同出资设立，用于奖励资助勤奋学习、努力进取，在德、智、体、美、劳等方面全面发展，品学兼优的家庭经济困难的学生。奖励标准：5000元/人。评选要求：国家励志奖学金每学年评选1次，名额由教育部下达，具体评选标准参照《中国石油大学（华东）本科生国家奖学金、国家励志奖学金、国家助学金实施细则》执行。3.综合优秀奖学金奖励对象：奖励品学兼优，综合素质全面发展的学生。奖励标准：该奖项分为三个等级：一等奖学金4000元/人，按学生数的3%评定；二等奖学金2000元/人，按学生数的7%评定；三等奖学金1000元/人，按学生数的15%评定。评选要求：参评学生应为二年级以上（含二年级）学生。各院部严格按照《中国石油大学（华东）学生综合素质测评办法》的标准，对学生进行综合素质测评。4.企事业奖学金奖励对象：奖励品学兼优，综合素质全面发展，符合设奖单位（个人）评选要求的学生。"},{"id":235,"type":"multi","stem":"以下奖学金种类，属于专项奖学金奖的是（）。","options":[["A","创新创业实践卓越之星奖学金"],["B","国际交流奖学金"],["C","道德风尚奖学金"],["D","国家奖学金"]],"answer":["A","B","C"],"source":"《中国石油大学（华东）学生奖学金管理细则(试行)》","category":"奖学金与资助","excerpt":""},{"id":236,"type":"multi","stem":"集体奖学金包括（）。","options":[["A","先进班集体"],["B","创新创业实践卓越之星奖学金"],["C","道德风尚奖学金"],["D","优良学风班"]],"answer":["A","D"],"source":"《中国石油大学（华东）学生奖学金管理细则(试行)》","category":"奖学金与资助","excerpt":""},{"id":237,"type":"multi","stem":"“十大学生标兵”是指在某一方面或者多个方面表现突出的在校学生，以属于加分项目的是（）。","options":[["A","学习优秀"],["B","科技创新能力强"],["C","组织能力突出"],["D","具有文体特长"],["E","积极参加社会实践和志愿服务活动"],["F","自强不息"]],"answer":["A","B","C","D","E","F"],"source":"《中国石油大学（华东）十大学生标兵评选实施细则》","category":"其他","excerpt":""},{"id":238,"type":"multi","stem":"申请国家励志奖学金者需具备以下条件（）。","options":[["A","热爱祖国,拥护中国共产党的领导,坚持四项基本原则,积极践行社会主义核心价值观"],["B","参评学生应为二年级以上(含二年级)的全日制普通本科在校生,且学习态度端正,勤奋刻苦,当学年修读的课程不低于30学分,原则上专业学习测评成绩与综合素质测评成绩排名均位于前30%。"],["C","家庭经济困难，生活简朴"],["D","品行端正,诚实守信,当学年基础性素质测评等级为“B”及以上"]],"answer":["A","B","C","D"],"source":"《中国石油大学（华东）“国家奖学金”、“国家励志奖学金”、“国家助学金”评选实施细则》","category":"奖学金与资助","excerpt":""},{"id":239,"type":"multi","stem":"申请国家助学金者需具备以下条件（）。","options":[["A","热爱祖国,拥护中国共产党的领导,坚持四项基本原则,积极践行社会主义核心价值观"],["B","自觉遵守国家法律,无违法违纪记录;遵守各项校规校纪,未受警告及以上处分"],["C","品行端正,诚实守信,当学年基础性素质测评等级为“C”及以上"],["D","家庭经济困难，生活简朴"]],"answer":["A","B","C","D"],"source":"《中国石油大学（华东）“国家奖学金”、“国家励志奖学金”、“国家助学金”评选实施细则》","category":"奖学金与资助","excerpt":""},{"id":240,"type":"multi","stem":"以下属于对违反学校纪律的学生的处分的是（）。","options":[["A","警告"],["B","严重警告"],["C","记过"],["D","留校察看"],["E","开除学籍"],["F","开除党籍"]],"answer":["A","B","C","D","E"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第五条对有违反法律法规、《普通高等学校学生管理规定》以及学校纪律行为的学生，学校给予批评教育，并视情节轻重，给予如下纪律处分：（一）警告；（二）严重警告；（三）记过；（四）留校察看；（五）开除学籍。"},{"id":241,"type":"multi","stem":"违反治安管理处罚法,受行政拘留者,视情节轻重，给予（）处分。","options":[["A","严重警告"],["B","记过"],["C","留校察看"],["D","开除学籍"]],"answer":["B","C","D"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第十条对触犯国家法律法规，受处罚者，给予如下处分：（一）构成刑事犯罪，受刑事处罚者，给予开除学籍处分；因过失犯罪者，给予留校察看或者开除学籍处分；（二）违反治安管理处罚法，受行政拘留者，视情节轻重，给予记过、留校察看或者开除学籍处分；受警告或者罚款者，给予警告或者严重警告处分。"},{"id":242,"type":"multi","stem":"对侵犯学校知识产权行为者的处分（）。","options":[["A","未经许可,私自转让、许可使用学校知识产权者,给予严重警告处分,情节严重的,给予记过或者留校察看处分;"],["B","违反保密规定,泄露学校科技成果,包括技术秘密者,给予记过处分,造成严重后果的,给予留校察看或者开除学籍处分;"],["C","其他违反学校有关知识产权规定行为者,给予警告或者严重警告处分,使学校权益受到损失者,给予记过、留校察看或者开除学籍处分。"],["D","学生对于知识产权的概念不清的，可以从轻处分。"]],"answer":["A","B","C"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第十七条对侵犯学校知识产权行为者的处分：（一）未经许可，私自转让、许可使用学校知识产权者，给予严重警告处分，情节严重的，给予记过或者留校察看处分；（二）违反保密规定，泄露学校科技成果，包括技术秘密者，给予记过处分，造成严重后果的，给予留校察看或者开除学籍处分；（三）其他违反学校有关知识产权规定行为者，给予警告或者严重警告处分，使学校权益受到损失者，给予记过、留校察看或者开除学籍处分。"},{"id":243,"type":"multi","stem":"以下行为中，属于违反考试纪律的是（）。","options":[["A","未按考场规则就座。"],["B","携带规定以外的物品进入考场或者未放在指定位置"],["C","用自带的草稿纸和计算器进行演算"],["D","经过监考人员许可后，借用给其他人书、笔记、资料、计算器等"],["E","考试中东张西望,企图偷看他人试卷,不服从考试工作人员管理"]],"answer":["A","B","C","E"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":""},{"id":244,"type":"multi","stem":"对有违纪行为的学生,学校给予批评教育,批评教育的方式包括（）。","options":[["A","口头批评"],["B","书面警示"],["C","通报批评"],["D","开除学籍"]],"answer":["A","B","C"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第三十条本规定未列举的其他违纪行为，视情节轻重，可参照相关规定，给予相应纪律处分。第四章处分程序和管理第三十一条对有违纪行为的学生，学校给予批评教育，批评教育的方式包括口头批评、书面警示和通报批评等，具体由学院（部）负责实施。通报批评下达后5天内报党委学生工作部、武装部备案。"},{"id":245,"type":"multi","stem":"心理咨询服务的时间为每周一至周五的（）。","options":[["A","上午8:00-12:00"],["B","上午8:00-11:00"],["C","下午14:00-17:30"],["D","下午14:00-18:00"]],"answer":["A","C"],"source":"《心理咨询来访者须知》","category":"心理咨询","excerpt":"6.心理咨询服务的时间为每周一至周五的上午8：00-12：00；下午14：00-17：30。接待心理咨询的地点为学生事务中心（校医院）三楼333-9心理咨询值班室。"},{"id":246,"type":"multi","stem":"自主发展计划学分里至少要取得2个学分的有哪些模块","options":[["A","社会实践"],["B","创新创业"],["C","文体发展"],["D","技能培训"]],"answer":["A","B","C"],"source":"中国石油大学(华东)本科生自主发展计划","category":"自主发展计划","excerpt":"第三条对学生按照学校本科生自主发展计划要求取得的自主发展计划学分，明确具体要求，其中思想成长类不少于1个学分，创新创业类不少于1.5个学分，社会实践与志愿服务类不少于1.5个学分，文体发展类不少于1个学分，工作履历与技能培训不做学分要求。"},{"id":247,"type":"multi","stem":"“第二课堂成绩单”思想成长类课程主要包括（）","options":[["A","入党入团情况"],["B","党团主题教育"],["C","社会实践"],["D","形式政策教育"]],"answer":["A","B","D"],"source":"中国石油大学(华东)“第二课堂成绩单实施细则”","category":"自主发展计划","excerpt":""},{"id":248,"type":"multi","stem":"创业训练项目是本科生团队，在导师指导下，团队中每个学生在项目实施过程中扮演一个或多个角色，完成（）等工作","options":[["A","编制商业计划书"],["B","开展可行性研究"],["C","模拟企业运行"],["D","参加企业实践"],["E","撰写创业报告"],["F","实际项目运营"]],"answer":["A","B","C","D","E"],"source":"中国石油大学(华东)大学生创新创业训练计划项目管理办法","category":"创新创业","excerpt":"三、计划内容大学生创新创业训练计划内容包括创新训练项目、创业训练项目和创业实践项目三类。创新训练项目是本科生个人或团队，在导师指导下，自主完成创新性研究项目设计、研究条件准备和项目实施、研究报告撰写、成果（学术）交流等工作。创业训练项目是本科生团队，在导师指导下，团队中每个学生在项目实施过程中扮演一个或多个具体的角色，完成编制商业计划书、开展可行性研究、模拟企业运行、参加企业实践、撰写创业报告等工作。创业实践项目是学生团队，在学校导师和企业导师共同指导下，采用前期创新训练项目（或创新性实验）的成果，提出一项具有市场前景的创新性产品或者服务，以此为基础开展创业实践活动。"},{"id":249,"type":"multi","stem":"大学生创新创业训练计划内容包括（）","options":[["A","创新训练项目"],["B","创业训练项目"],["C","创业实践项目"],["D","创新实践项目"]],"answer":["A","B","C"],"source":"中国石油大学(华东)大学生创新创业训练计划项目管理办法","category":"创新创业","excerpt":"三、计划内容大学生创新创业训练计划内容包括创新训练项目、创业训练项目和创业实践项目三类。创新训练项目是本科生个人或团队，在导师指导下，自主完成创新性研究项目设计、研究条件准备和项目实施、研究报告撰写、成果（学术）交流等工作。创业训练项目是本科生团队，在导师指导下，团队中每个学生在项目实施过程中扮演一个或多个具体的角色，完成编制商业计划书、开展可行性研究、模拟企业运行、参加企业实践、撰写创业报告等工作。创业实践项目是学生团队，在学校导师和企业导师共同指导下，采用前期创新训练项目（或创新性实验）的成果，提出一项具有市场前景的创新性产品或者服务，以此为基础开展创业实践活动。"},{"id":250,"type":"multi","stem":"申请“三进”计划学生须具备以下条件（）","options":[["A","思想品德良好, 遵纪守法, 在校期间无违反校规校纪行为"],["B","学习态度端正,对科研创新有浓厚兴趣,愿意加入科研团队从事科学研究"],["C","学有余力,必修课程没有不及格现象"],["D","非本研一体化班学生"]],"answer":["A","B","C","D"],"source":"优秀本科生\"三进\"提升计划实施办法","category":"三进提升计划","excerpt":"第十条申请学生须具备以下条件：1.思想品德良好，遵纪守法，在校期间无违反校规校纪行为；2.学习态度端正，对科研创新有浓厚兴趣，愿意加入科研团队从事科学研究；3.学有余力，必修课程没有不及格现象；4.非本研一体化班学生。"},{"id":251,"type":"multi","stem":"“三大赛”包括（）","options":[["A","中国国际“ 互联网+ ”大学生创新创业大赛"],["B","”挑战杯”全国大学生课外学术科技作品竞赛"],["C","“ 挑战杯”中国大学生创业计划竞赛"],["D","大学生创新创业大赛"]],"answer":["A","B","C"],"source":"本科生学科竞赛管理办法","category":"学科竞赛","excerpt":""},{"id":252,"type":"judge","stem":"学分制收费是按照专业注册学费和学分学费两部分计收学费的收费管理制度。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学分制收费管理暂行办法》","category":"学分制收费","excerpt":"第四条本办法所称学分制收费，是按照专业注册学费和学分学费两部分计收学费的收费管理制度。学分制收费执行政府定价或政府指导价。第二章收费项目及标准第五条专业注册学费是学生进行专业学习注册取得专业课程选修资格需缴纳的费用。专业注册学费由学校按照不同专业生均培养成本等因素合理确定。专业注册学费按学年计收。学校在每学年初向学生收取专业注册学费，为学生办理专业注册手续，授予学生本学年选课资格。学校按照学生实际修业年限收取专业注册学费。"},{"id":253,"type":"judge","stem":"学分学费根据学生每学期选课的总学分收取。无论是否取得该学分，均收取学分学费。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学分制收费管理暂行办法》","category":"学分制收费","excerpt":"第六条学分学费是学生选择修读课程并取得课程考核资格缴纳的费用。学分学费按学期计收，实行先选课后缴费。学校根据每学期学生选课情况，按照课程对应学分数与收费标准，在学生完成选课后即时收取。"},{"id":254,"type":"judge","stem":"考试结束时，考生须将试卷、草稿纸全部交回，禁止带出考场。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"中国石油大学（华东）学生考试工作管理规定（修订）","category":"考试管理","excerpt":"第二十六条试卷和草稿纸由监考人员统一发放，禁止考生自带草稿纸。考试结束时，考生须将试卷、草稿纸全部交回，禁止带出考场。提前交卷应举手示意，交回试卷并经监考人员同意后，方可离开。考试结束，考生应立即停止答题，在座位上等待监考人员收取试卷。待监考人员清点完试卷并下达允许离场的指令后，方可离开。"},{"id":255,"type":"judge","stem":"考试时，所有考试规定以外的物品必须按监考人员的要求放置。未经监考人员同意，不得两人共用一套文具或计算器。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"中国石油大学（华东）学生考试工作管理规定（修订）","category":"考试管理","excerpt":"第二十七条考试时，所有考试规定以外的物品必须按监考人员的要求放置。未经监考人员同意，不得两人共用一套文具或计算器。"},{"id":256,"type":"judge","stem":"考试时，为他人提供偷看自己试卷的机会，自己没有偷看，不是作弊。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"中国石油大学（华东）学生考试工作管理规定（修订）","category":"考试管理","excerpt":"……第三十条（三）为他人提供偷看机会，或偷看他人试卷、草稿纸；"},{"id":257,"type":"judge","stem":"考试违纪或作弊了，只要不在《考试违纪情况登记表》上签字，就不会受到处分。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"中国石油大学（华东）学生考试工作管理规定（修订）","category":"考试管理","excerpt":"第二十二条考试过程中，监考人员应认真核对考生证件和试卷上填写的姓名，如有不符，应立即查处。如发现考生有违纪作弊苗头，应及时给予警告。如发现考生有违纪作弊行为，须立即予以制止，收回其试卷并暂扣作弊的材料、工具等物证，如实填写《考试违纪情况登记表》并要求考生签字确认后，将其清理出考场。考生拒不签字的，监考人员应在登记表中予以说明。"},{"id":258,"type":"judge","stem":"请人代考或代人考试，以考试作弊认定，该门课程总成绩以零分记。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"中国石油大学（华东）学生考试工作管理规定（修订）","category":"考试管理","excerpt":"第三十条考试过程中有下列情况之一者，以考试作弊认定，该门课程总成绩以零分记："},{"id":259,"type":"judge","stem":"强拿他人试卷、草稿纸（不论是否抄用），以考试违纪认定。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"中国石油大学（华东）学生考试工作管理规定（修订）","category":"考试管理","excerpt":"……第三十条（二）强拿他人试卷、草稿纸（不论是否抄用）；"},{"id":260,"type":"judge","stem":"为他人提供偷看机会，或偷看他人试卷、草稿纸，以考试作弊认定。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"中国石油大学（华东）学生考试工作管理规定（修订）","category":"考试管理","excerpt":"……第三十条（三）为他人提供偷看机会，或偷看他人试卷、草稿纸；"},{"id":261,"type":"judge","stem":"用某种示意、动作互相传递有关考试信息，以考试违纪认定。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"中国石油大学（华东）学生考试工作管理规定（修订）","category":"考试管理","excerpt":"……第三十条（四）用某种示意、动作互相传递有关考试信息；"},{"id":262,"type":"judge","stem":"考试中直接或以借用工具书、文具、计算器等方式传接答卷或纸条的行为双方，以考试作弊认定。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"中国石油大学（华东）学生考试工作管理规定（修订）","category":"考试管理","excerpt":"……第三十条（五）考试中直接或以借用工具书、文具、计算器等方式传接答卷或纸条的行为双方；"},{"id":263,"type":"judge","stem":"用某种示意、动作互相传递有关考试信息，以违反考试纪律认定。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"中国石油大学（华东）学生考试工作管理规定（修订）","category":"考试管理","excerpt":"……第三十条（四）用某种示意、动作互相传递有关考试信息；"},{"id":264,"type":"judge","stem":"违反考场规则使用有文字存储功能的电子设备，或使用手机等无线通讯工具查看信息，以考试违纪认定。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"中国石油大学（华东）学生考试工作管理规定（修订）","category":"考试管理","excerpt":"……第三十条（六）违反考场规则使用有文字存储功能的电子设备，或使用手机等无线通讯工具查看信息；"},{"id":265,"type":"judge","stem":"偷看有关考试内容的资料,或与他人交谈有关考试内容，以考试作弊认定。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"中国石油大学（华东）学生考试工作管理规定（修订）","category":"考试管理","excerpt":"……第三十条（七）偷看有关考试内容的资料，或与他人交谈有关考试内容；"},{"id":266,"type":"judge","stem":"故意损毁试卷、答题卡、答题纸等考试材料，以考试违纪认定。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"中国石油大学（华东）学生考试工作管理规定（修订）","category":"考试管理","excerpt":"……第三十条（八）故意损毁试卷、答题卡、答题纸等考试材料；"},{"id":267,"type":"judge","stem":"监考人员发现的考生违纪作弊行为会进行处理，巡考人员发现的，不进行处理。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"中国石油大学（华东）学生考试工作管理规定（修订）","category":"考试管理","excerpt":"第三十三条巡考人员发现考生违纪作弊，应立即向考场监考人员说明情况，由监考人员按上述办法处理。巡考人员应在《考场情况记录表》上签名。教师在阅卷或其他情况下发现有作弊问题时，要及时将书面报告（连同物证）交教务处。"},{"id":268,"type":"judge","stem":"学校内部的考试，迟到40分钟以内，可以入场。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"中国石油大学（华东）学生考试工作管理规定（修订）","category":"考试管理","excerpt":"第二十四条监考人员须严格遵守教学纪律，认真履行监考职责，自始至终维持好考场秩序。对不认真履行职责者，按学校有关规定处理。第七章考试纪律第二十五条考生要按规定的考试时间提前15分钟进入考场，按照监考人员的安排就座；将有效证件放在桌面，无有效证件者不准参加考试。迟到30分钟以上和无故不参加考试者，按“缺考”处理。开考30分钟后，准予交卷出场。未交卷且未经监考人员允许擅自离开考场者，不得重新进入考场。考生交卷后应离开考场，不得在考场内逗留或在考场附近大声喧哗。"},{"id":269,"type":"judge","stem":"考试中东张西望，企图偷看他人试卷，但没有成功，不属于考试违纪行为。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"中国石油大学（华东）学生考试工作管理规定（修订）","category":"考试管理","excerpt":"第二十八条考生要严格遵守考场规则，在规定的时间内独立完成答卷。凡不服从监考人员安排，违反考试纪律或作弊者，按学校有关规定处理。第八章考试违纪、作弊的认定及处理第二十九条考生有下列情况之一者，视为违反考试纪律，要当场给予口头警告并予以纠正：（一）未按考场规则就座；（二）闭卷考试至发试卷时仍将规定以外物品等带入座位；（三）自带空白答题纸或草稿纸；（四）未经监考人员允许借用他人的书、笔记、资料、计算器等物品；（五）考试中东张西望，企图偷看他人试卷；（六）交卷后仍在考场逗留或在考场附近大声喧哗；（七）将试卷、答题卡、答题纸、草稿纸等带出考场。对具有上述任意一种行为，无视警告且不纠正者，取消考试资格，该门课程总成绩以零分记。"},{"id":270,"type":"judge","stem":"提前交卷后，在不影响他人的情况下，可以继续坐在考场中。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"中国石油大学（华东）学生考试工作管理规定（修订）","category":"考试管理","excerpt":"第二十八条考生要严格遵守考场规则，在规定的时间内独立完成答卷。凡不服从监考人员安排，违反考试纪律或作弊者，按学校有关规定处理。第八章考试违纪、作弊的认定及处理第二十九条考生有下列情况之一者，视为违反考试纪律，要当场给予口头警告并予以纠正：（一）未按考场规则就座；（二）闭卷考试至发试卷时仍将规定以外物品等带入座位；（三）自带空白答题纸或草稿纸；（四）未经监考人员允许借用他人的书、笔记、资料、计算器等物品；（五）考试中东张西望，企图偷看他人试卷；（六）交卷后仍在考场逗留或在考场附近大声喧哗；（七）将试卷、答题卡、答题纸、草稿纸等带出考场。对具有上述任意一种行为，无视警告且不纠正者，取消考试资格，该门课程总成绩以零分记。"},{"id":271,"type":"judge","stem":"闭卷考试中，桌内、座位旁有翻开的或试卷下面垫有与考试内容相关的书、笔记、讲义、复习提纲等物品，没有翻看的话，不算考试作弊。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"中国石油大学（华东）学生考试工作管理规定（修订）","category":"考试管理","excerpt":"……第三十条1.桌内、座位旁有翻开的或试卷下面垫有与考试内容相关的书、笔记、讲义、复习提纲等物品；"},{"id":272,"type":"judge","stem":"闭卷考试中，利用文具盒、衣物或其他用品夹带与考试内容相关的笔记、复习提纲、纸条，拿出观看的，以考试作弊认定，未拿出观看的认定为违反考试纪律。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"中国石油大学（华东）学生考试工作管理规定（修订）","category":"考试管理","excerpt":"……第三十条2.利用文具盒、衣物或其他用品夹带与考试内容相关的笔记、复习提纲、纸条；"},{"id":273,"type":"judge","stem":"用某种示意、动作互相传递有关考试信息，没有实物证据，不以考试作弊认定，可从轻处理。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"中国石油大学（华东）学生考试工作管理规定（修订）","category":"考试管理","excerpt":"……第三十条（四）用某种示意、动作互相传递有关考试信息；"},{"id":274,"type":"judge","stem":"实验课如因特殊情况请假的，须经指导教师同意，可不用进行补做。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）本科实验教学管理办法》","category":"实验教学与实习","excerpt":"第十五条实验课原则上不允许请假，如因特殊情况需请假的，须经指导教师同意，并及时进行补做。"},{"id":275,"type":"judge","stem":"实验课成绩考核可采用百分制或五级记分制记载。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）本科实验教学管理办法》","category":"实验教学与实习","excerpt":"第十八条实验课成绩应从学生实验态度、预习情况、操作表现、实验数据、实验报告、考核等多方面进行综合评定，可采用百分制（60分为及格）或五级记分制（优秀、良好、中等、及格、不及格）记载。"},{"id":276,"type":"judge","stem":"大学生创新创业训练计划中的创业实践项目实行学校和企业双导师制。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）大学生创新创业训练计划项目管理办法》","category":"创新创业","excerpt":"……五、创业实践项目实行学校和企业双导师制。"},{"id":277,"type":"judge","stem":"大学生创新创业训练计划项目负责人可以任意更换。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）大学生创新创业训练计划项目管理办法》","category":"创新创业","excerpt":"八、经费管理1.大学生创新创业训练计划项目经费由教育部专项经费和学校配套经费组成，项目经费专款专用。2.学生在导师指导下自主使用项目经费。经费主要用于资助项目实验、材料、书籍、论文发表、学术交流、调研差旅等项目运行所需费用，不得挪作他用。导师不得使用学生项目经费。3.经费报销严格遵守学校财务制度，报销不得超过项目经费总额。报销单据须由项目负责人和导师签字，由教务处审核后方可报销。4.项目资助学生为第一作者发表的论文以及项目研究形成的专利、软件、专著等成果，第一作者或专利权人单位署为“中国石油大学（华东）”，同时应标注“中国石油大学（华东）大学生创新创业训练计划资助项目（编号）”。5.资助项目形成的固定资产的处置、知识产权的归属按照学校相关规定执行。6.对存在学术不端行为或经费使用不当的项目，学校将终止项目运行并收回资助经费。"},{"id":278,"type":"judge","stem":"大学生创新创业训练计划项目中，对未能通过中期检查或工作无明显进展的项目，学校将终止其运行并追回垫付费用。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）大学生创新创业训练计划项目管理办法》","category":"创新创业","excerpt":"……七、7.对未能通过中期检查或工作无明显进展的项目，学校将终止其运行。"},{"id":279,"type":"judge","stem":"申报大学生创新创业训练计划项目时，同一研究内容已获学校其他项目资助的只要研究主题符合，可重复申报。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）大学生创新创业训练计划项目管理办法》","category":"创新创业","excerpt":"……五、已获得项目资助且未结题者不得参与申报，同一研究内容已获学校其他项目资助的不得重复申报。"},{"id":280,"type":"judge","stem":"对存在学术不端兴伟或经费使用不当的大学生创新创业训练计划项目，学校将终止项目运行并收回资助费用。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）大学生创新创业训练计划项目管理办法》","category":"创新创业","excerpt":"八、经费管理1.大学生创新创业训练计划项目经费由教育部专项经费和学校配套经费组成，项目经费专款专用。2.学生在导师指导下自主使用项目经费。经费主要用于资助项目实验、材料、书籍、论文发表、学术交流、调研差旅等项目运行所需费用，不得挪作他用。导师不得使用学生项目经费。3.经费报销严格遵守学校财务制度，报销不得超过项目经费总额。报销单据须由项目负责人和导师签字，由教务处审核后方可报销。4.项目资助学生为第一作者发表的论文以及项目研究形成的专利、软件、专著等成果，第一作者或专利权人单位署为“中国石油大学（华东）”，同时应标注“中国石油大学（华东）大学生创新创业训练计划资助项目（编号）”。5.资助项目形成的固定资产的处置、知识产权的归属按照学校相关规定执行。6.对存在学术不端行为或经费使用不当的项目，学校将终止项目运行并收回资助经费。"},{"id":281,"type":"judge","stem":"学生在实习期间，经指导教师批准，可以调换实习岗位。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）本科实习教学管理办法》","category":"实验教学与实习","excerpt":"第二十六条指导教师应与实习单位一起对学生进行安全教育和职业道德教育，明确告知学生在实习过程中的安全责任与义务等，确保实习期间学生的人身安全。"},{"id":282,"type":"judge","stem":"毕业设计题目为防止工作量计算上的困难，须一人一题。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）本科毕业设计（论文）管理规定》","category":"其他","excerpt":"……第六条5.毕业设计可一人一题，也可多人合作完成一题。"},{"id":283,"type":"judge","stem":"在校外做毕业设计的学生不需要配备校内指导教师。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）本科毕业设计（论文）管理规定》","category":"其他","excerpt":"……第二十二条6.在校外做毕业设计的学生，原则上要在校内答辩，如确需在校外答辩，须经学院审批同意后，确定其答辩地点和答辩方式，要求成立不少于3人的答辩小组，且至少有1人为校内教师。"},{"id":284,"type":"judge","stem":"对在创新创业实践活动中取得优秀成绩的学生，学校将给予自主发展计划学分认定、综合素质测评加分等奖励，并在研究生“推免”工作中予以政策倾斜。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）本科生创新创业教育保障与激励暂行办法》","category":"创新创业","excerpt":""},{"id":285,"type":"judge","stem":"学校设有创新创业专项奖学金。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）本科生创新创业教育保障与激励暂行办法》","category":"创新创业","excerpt":""},{"id":286,"type":"judge","stem":"因健康原因不能正常上体育课的学生,经校医院或校医院指定的二级甲等以上医院诊断证明,并经体育教学部同意后,可改修保健课并免予执行《学生体质健康标准》。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）本科生学籍管理规定》","category":"学籍管理","excerpt":"第十八条体育课成绩和《学生体质健康标准》成绩须分别进行评定。体育课成绩评定应突出过程管理，根据考勤、课内教学、课外锻炼活动和体质健康等情况综合评定。因健康原因不能正常上体育课的学生，经校医院或校医院指定的二级甲等以上医院诊断证明，并经体育教学部同意后，可改修保健课并免予执行《学生体质健康标准》。"},{"id":287,"type":"judge","stem":"新生入学后，学校在3个月内按照国家招生规定对其进行复查。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）本科生学籍管理规定》","category":"学籍管理","excerpt":"第七条新生入学后，学校在3个月内按照国家招生规定对其进行复查。复查内容主要包括以下方面：1.录取手续及程序等是否合乎国家招生规定；2.所获得的录取资格是否真实、合乎相关规定；3.本人及身份证明与录取通知、考生档案等是否一致；4.身心健康状况是否符合报考专业或者专业类别体检要求，能否保证在校正常学习、生活；5.艺术、体育等特殊类型录取学生的专业水平是否符合录取要求。复查中发现存在弄虚作假、徇私舞弊情形的，一经查实，学校即取消其学籍；情节严重的，移交有关部门调查处理。"},{"id":288,"type":"judge","stem":"学生不请假或请假未获批准而无故缺席的,以旷课论处,并根据学校学生纪律处分相关规定给予批评教育;情节严重的,直接给予开除学籍的纪律处分。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）本科生学籍管理规定》","category":"学籍管理","excerpt":"第十条学生应当按照本科培养方案的要求，认真参加各项教育教学活动。学生因病或其他原因不能按时参加的，应当事先请假并获得批准。学生不请假或请假未获批准而无故缺席的，以旷课论处，并根据学校学生纪律处分相关规定给予批评教育；情节严重的，给予相应的纪律处分。理论课旷课时间的计算以学生课程表的课时数为准。对于本科培养方案规定的实践性教学环节和学校规定必须参加的其他各项教学活动，无故缺席的，按每天6学时计旷课。"},{"id":289,"type":"judge","stem":"学生对本科培养方案规定的课程通过自学等途径确已掌握,可以申请免修。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）本科生学籍管理规定》","category":"学籍管理","excerpt":"……第十五条1.课程免修（1）学生对本科培养方案规定的课程通过自学等途径确已掌握，可以申请免修；（2）学生申请免修原则上应在学期初2周内向开课院部提出申请；（3）开课院部根据课程学习要求等情况，决定是否接受免修申请。"},{"id":290,"type":"judge","stem":"学生补考时间为每学期的开学初,补考课程为前一学期考核不及格的必修或限选课程,且申请补考的课程成绩必须达45分（含）以上。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）本科生学籍管理规定》","category":"学籍管理","excerpt":"第十七条凡结课（含免修）考核不及格的课程，可通过重新选课修读或补考取得该课程的学分。考核成绩合格，但成绩不理想的课程，也可重新选课修读。1.在学校规定的最长学习年限内，重新选课修读不限制次数，所有修读成绩均如实记载；2.补考时间为每学期的开学初，补考课程为前一学期考核不及格的必修或限选课程，且申请补考的课程成绩必须达50分（含）以上；3.实验课程、实习实训、毕业设计等实践性教学环节以及无结课考核环节的课程不能补考；4.学生补考及格获得该课程学分，补考不及格须重新选课修读。"},{"id":291,"type":"judge","stem":"本校学生学分绩的计算方式为：学分绩=Σ（修读课程成绩X课程总学分）/Σ修读课程学分。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）本科生学籍管理规定》","category":"学籍管理","excerpt":"第二十一条学分绩、课程绩点、平均学分绩点的计算方法：1.学分绩=暺（修读课程成绩暳课程学分）/暺修读课程学分；2.课程绩点=修读课程成绩/10-5；3.平均学分绩点=暺（修读课程绩点暳课程学分）/暺修读课程学分；4.课程成绩不足60分的，课程绩点记为0；五级记分制与百分制的对应关系：优秀-95，良好-85，中等-75，及格-65，不及格-40；二级记分制与百分制的对应关系：通过-80，不通过-40；5.学分绩、课程绩点、平均学分绩点计算结果保留到小数点后两位数。"},{"id":292,"type":"judge","stem":"因病（持校医院或校医院指定的二级甲等以上医院诊断证明）或其他特殊原因确实不能参加结课考核的学生,应于考试前提出申请并提供相关证明材料办理缓考手续,经所在院部同意,报教务处审批。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）本科生学籍管理规定》","category":"学籍管理","excerpt":"第十九条因病（持校医院或校医院指定的二级甲等以上医院诊断证明）或其他特殊原因确实不能参加结课考核的学生，应于考试前提出申请并提供相关证明材料办理缓考手续，经所在院部同意，报教务处审批。"},{"id":293,"type":"judge","stem":"转专业学生须达到原专业本科培养方案规定的要求方可毕业。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）本科生学籍管理规定》","category":"学籍管理","excerpt":"第三十一条转专业学生须达到转入专业本科培养方案规定的要求方可毕业。转专业前已取得学分的课程，如果符合转入专业本科培养方案的要求，可办理课程学分冲抵手续。"},{"id":294,"type":"judge","stem":"学生转专业,应按学校规定办理手续;在未完成相关手续办理前,应参加两个专业共有的或可完成学分认证的相应课程。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）本科生学籍管理规定》","category":"学籍管理","excerpt":"第三十二条学生转专业，应按学校规定办理手续；在未完成相关手续办理前，须参加原专业的学习。第六章休学、保留学籍与复学第三十三条学生有以下情形之一者，应申请休学：1.因病经校医院或校医院指定的二级甲等以上医院诊断后，须停课治疗、休养超过6周的（肝炎、肺结核等传染病患者须休学）；2.请假超过6周的；3.经学校认定同意创业休学的；4.因某种特殊原因，本人申请休学或学校认为须休学的。学生休学期间，学校为其保留学籍，但不享受在校学习学生待遇。"},{"id":295,"type":"judge","stem":"学生毕业时未修满本科培养方案规定的学分要求,可申请延长学习年限或结业。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）本科生学籍管理规定》","category":"学籍管理","excerpt":"第四十六条学生毕业时未修满本科培养方案规定的学分要求，可申请延长学习年限或结业。1.延长学习年限（1）延长学习年限应由学生本人提出申请，所在院部审核批准后报教务处备案，但其累计在校时间不能超过学校规定的最长学习年限；（2）延长学习年限的学生，享受在校生待遇。2.结业（1）毕业时累计欠本科培养方案规定的学分要求15学分以内（含15学分）的学生，经本人申请，所在院部审核，学校批准后，可办理结业手续；（2）学生结业后1年之内回校完成相关课程修读，达到本科培养方案规定的学分要求的，学校准予毕业，符合学士学位授予标准的，授予学士学位。合格后颁发的毕业证书、学位证书，毕业时间、获学位时间按发证日期填写；（3）学生结业1年后仍未达到本科培养方案规定的学分要求的，不再换发毕业证书。"},{"id":296,"type":"judge","stem":"学校所发的毕业证书、学位证书、结业证书和肄业证书等如有遗失或者损坏,经本人申请,学校可提供其副本。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）本科生学籍管理规定》","category":"学籍管理","excerpt":"第五十一条学校所发的毕业证书、学位证书、结业证书和肄业证书均属一次性证件。如有遗失或者损坏，经本人申请，学校可出具相应的证明书，证明书与原证书具有同等效力。第十章附则第五十二条学校对学生作出取消入学资格、取消学籍、退学、转学等涉及学生重大利益的决定，事先进行合法性审查，并提交校长办公会或者校长授权的专门会议研究决定。学生对学籍处理决定有异议的，可按照学校学生申诉相关规定提出申诉。"},{"id":297,"type":"judge","stem":"学生退学且学满2学年以上的,学校可发给肄业证书。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）本科生学籍管理规定》","category":"学籍管理","excerpt":"第四十九条学生退学且学满1学年以上的，学校可发给肄业证书。开除学籍或未满1学年退学的学生，学校只出具学习证明。"},{"id":298,"type":"judge","stem":"新生和在校学生应征参加中国人民解放军（含中国人民武装警察部队）,学校保留其入学资格或学籍至退役后2年,保留学籍时间不计入学习年限。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）本科生学籍管理规定》","category":"学籍管理","excerpt":"第三十七条新生和在校学生应征参加中国人民解放军（含中国人民武装警察部队），学校保留其入学资格或学籍至退役后2年，保留学籍时间不计入学习年限。"},{"id":299,"type":"judge","stem":"学生应当诚实守信,遵从学术规范,恪守学术道德,遵守保护知识产权的有关规定。 对学生学业、学术、品行等方面有严重失信行为的,可按相关规定给予相应的纪律处分,对违背学术诚信的,学校将对其获得学位及学术称号、荣誉等作出限制。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）本科生学籍管理规定》","category":"学籍管理","excerpt":"第十二条学生应当诚实守信，遵从学术规范，恪守学术道德，遵守保护知识产权的有关规定。对学生学业、学术、品行等方面有严重失信行为的，可按相关规定给予相应的纪律处分，对违背学术诚信的，学校将对其获得学位及学术称号、荣誉等作出限制。第四章课程考核与成绩记载第十三条学生应当参加学校本科培养方案规定的课程和各项教育教学环节（以下统称课程）的考核，其考核成绩记入成绩单，并归入学籍档案。学校真实、完整地记载、出具学生学业成绩，学生重学成绩、补考成绩均予以标注。"},{"id":300,"type":"judge","stem":"对违反国家招生规定入学者,学校取消其学籍,不发给学历、学位证书;已发的学历、学位证书,学校依法予以撤销。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）本科生学籍管理规定》","category":"学籍管理","excerpt":"第五十条对违反国家招生规定入学者，学校取消其学籍，不发给学历、学位证书；已发的学历、学位证书，学校依法予以撤销。对以作弊、剽窃、抄袭等学术不端行为或者其他不正当手段获得学历证书、学位证书的，学校依法予以撤销。被撤销的学历证书、学位证书已注册的，学校予以注销并报教育行政部门宣布无效。"},{"id":301,"type":"judge","stem":"学业警示级别根据学生已选必修课程中累计未取得学分数（Q）或每学期选课学分数（X）确定,分为一级警示、二级警示、三级警示等3个级别。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）本科生学籍管理规定》","category":"学籍管理","excerpt":"……第三十八条学业警示级别根据学生已选必修课程中累计未取得学分数（Q）或每学期选课学分数（X）确定，分为一级警示（10学分<Q曑15学分或者X<15）、二级警示（15<Q<25学分或者连续2学期X<15）、三级警示（Q曒25学分或者连续3学期X<15）等3个级别。"},{"id":302,"type":"judge","stem":"学校真实、完整地记载、出具学生学业成绩,学生重学成绩、补考成绩视情况予以标注。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）本科生学籍管理规定》","category":"学籍管理","excerpt":"第十二条学生应当诚实守信，遵从学术规范，恪守学术道德，遵守保护知识产权的有关规定。对学生学业、学术、品行等方面有严重失信行为的，可按相关规定给予相应的纪律处分，对违背学术诚信的，学校将对其获得学位及学术称号、荣誉等作出限制。第四章课程考核与成绩记载第十三条学生应当参加学校本科培养方案规定的课程和各项教育教学环节（以下统称课程）的考核，其考核成绩记入成绩单，并归入学籍档案。学校真实、完整地记载、出具学生学业成绩，学生重学成绩、补考成绩均予以标注。"},{"id":303,"type":"judge","stem":"学生入学后,一般不予转学。 如因患病或者确有特殊困难和需要,无法继续在校学习者或不适应学校学习要求的,可以申请转学。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）本科生学籍管理规定》","category":"学籍管理","excerpt":"第二十四条学生因退学等情况中止学业，其在校学习期间所修课程及已获得学分，予以记录。学生退学后2年内重新参加普通高等学校招生全国统一考试，被学校录取并取得学籍的，其已获得学分，经学校认定符合相关专业本科培养方案要求，可予以承认。第五章转学与转专业第二十五条学生入学后，一般不予转学。如因患病或者确有特殊困难和需要，无法继续在校学习者或不适应学校学习要求的，可以申请转学。"},{"id":304,"type":"judge","stem":"本科毕业生，曾有记过及以上处分，不可授予学士学位。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学士学位授予办法》","category":"学籍管理","excerpt":"第三条本细则适用于学校普通高等教育全日制本科毕业生。第二章学位授予标准第四条达到以下标准者，可在规定时间内向学校提出申请，经学校学位评定委员会审查通过后，授予学士学位：（一）拥护中国共产党的领导、拥护社会主义制度，遵守宪法和法律法规，遵守学校规章制度，遵守学术道德和学术规范。（二）在校学习且学习时间在学校规定最长学习年限内，或结业后不满1年。（三）完成本专业培养方案规定的各项要求，掌握本专业的基础理论、专业知识和基本技能，达到毕业要求，具有从事学术研究或者承担专业实践工作的初步能力。（四）必修课程[含毕业设计（论文）]学分绩不低于70分。（五）在校学习期间曾受记过及以上处分的，处分解除后方可申请授予学士学位。"},{"id":305,"type":"judge","stem":"学生因退学、转学等原因终止学业的，按月结算专业注册学费；每学年按10个月计算，不足1个月的，按1个月计算。学分学费按实际修读学分结算。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学分制收费管理暂行办法》","category":"学分制收费","excerpt":"第十七条学生退学的，根据学生实际学习时间按月计退专业注册学费。专业注册费按每学年10个月计算，不足1个月的，按1个月计算，学生办理完成退学手续时即时退费。学生学分学费已缴纳但未修完课程的，按照课程学分及收费标准于每学期末或下学期初全部退还。"},{"id":306,"type":"judge","stem":"学生参加自主发展计划第二课堂活动的，免交学分学费。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学分制收费管理暂行办法》","category":"学分制收费","excerpt":"第十二条学生参加自主发展计划第二课堂活动的，免交学分学费。"},{"id":307,"type":"judge","stem":"入学复查不合格取消入学资格的新生，学校不予退还已交学费。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）学分制收费管理暂行办法》","category":"学分制收费","excerpt":"第十六条学生放弃入学资格或入学复查不合格取消入学资格的，学校退还已交学费。"},{"id":308,"type":"judge","stem":"学生确因家庭经济困难无法及时足额交费的，可通过学校大学生资助中心申请缓交，经认定后方可注册、选课，学费缓交期间课程成绩暂不登记入档。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学分制收费管理暂行办法》","category":"学分制收费","excerpt":""},{"id":309,"type":"judge","stem":"凡在校普通全日制本科生，品学兼优、学有余力者均可申请修读双学位。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）本科生双学位培养管理办法》","category":"双学位与辅修","excerpt":""},{"id":310,"type":"judge","stem":"双学位专业开设院部对申请双学位的同学进行必要考核，并根据考核择优录取。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）本科生双学位培养管理办法》","category":"双学位与辅修","excerpt":""},{"id":311,"type":"judge","stem":"双学位单个专业人数较少且公共时间难以调整，因此不单独组班上课。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）本科生双学位培养管理办法》","category":"双学位与辅修","excerpt":""},{"id":312,"type":"judge","stem":"修读双学位学生须获得主修专业学士学位，同时达到双学位专业培养方案的要求，方可授予双学位。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）本科生双学位培养管理办法》","category":"双学位与辅修","excerpt":""},{"id":313,"type":"judge","stem":"辅修专业开设院部和学生所在院部共同负责辅修学生的学习成绩管理。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）本科生辅修培养管理办法》","category":"双学位与辅修","excerpt":""},{"id":314,"type":"judge","stem":"主、辅修专业应属于相同专业类。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）本科生辅修培养管理办法》","category":"双学位与辅修","excerpt":""},{"id":315,"type":"judge","stem":"在校本科生学生因创业需要,可申请创业休学。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）本科生创新创业学籍管理办法（试行）》","category":"创新创业","excerpt":"中国石油大学（华东）本科生创新创业学籍管理办法（中石大东发[2023]34号）第一章总则第一条为贯彻落实《国务院办公厅关于进一步支持大学生创新创业的指导意见》（国办发暡2021暢35号）等相关文件精神，支持本科生创新创业，结合学校学籍管理有关规定，特制定本办法。第二章学习年限第二条学生因创业需要，可申请创业休学。"},{"id":316,"type":"judge","stem":"对于在创业休学期间创业项目无实际进展,或从事与创业计划无关活动,经认定不适合继续创业者,应终止休学。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）本科生创新创业学籍管理办法（试行）》","category":"创新创业","excerpt":"第六条每年12月底前，创业休学学生须向所在院（部）提交项目进展报告，创业满1年的还需提交完税证明或免税证明，由院（部）创新创业教育领导小组认定、学校创新创业教育工作领导小组办公室审定。对于在创业休学期间创业项目无实际进展，或从事与创业计划无关活动，经认定不适合继续创业者，应终止休学。第四章学分认定第七条学生参加创新活动、创业实践，可申请学分认定。同一创新创业实践活动不可重复申请认定。"},{"id":317,"type":"judge","stem":"连续创业2年及以上,且表现突出、成效显著的,可免修自主发展计划全部学分。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）本科生创新创业学籍管理办法（试行）》","category":"创新创业","excerpt":"第八条学生参加学科竞赛、课外科技活动、创新项目研究、发表论文、获得专利等创新活动，可申请认定为自主发展计划（第二课堂）中的创新创业学分。"},{"id":318,"type":"judge","stem":"学生参与创新活动,研究过程和取得成绩确能体现其学科专长和创新潜质,且转入相关专业更利于其发展的,可申请转专业。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）本科生创新创业学籍管理办法（试行）》","category":"创新创业","excerpt":"第十四条复学按以下规定办理：1.每学期初2周内，向所在院（部）提出申请，填写《创业复学申请表》，经院（部）创新创业教育领导小组认定、学校创新创业教育工作领导小组办公室审定后，报学校审批。审批通过者，办理复学手续。2.院（部）要对申请复学的学生进行必要的审查，如发现其在休学期间有严重的违法违纪行为，取消复学资格。3.休学期满或年度审查认定不适合继续创业者，在学校规定的期限内未提出复学申请的，应予退学处理。第六章转专业第十五条学生参与创新活动，研究过程和取得成绩确能体现其学科专长和创新潜质，且转入相关专业更利于其发展的，可申请转专业。"},{"id":319,"type":"judge","stem":"“优良学风班”评选每年组织一次,同一个行政班级在两年内不可以连续申报。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学(华东)优良学风班评选办法》","category":"优良学风班","excerpt":"四、其他1.“优良学风班”每年组织一次，符合条件者可连续申报。2.获得“优良学风班”和“优良学风标兵班”的班级，学校颁发荣誉证书并给予奖励。3.本办法自公布之日施行，由教务处负责解释。原《石油大学（华东）建设、评选优良学风班办法》（石大东发暡1998暢105号）同时废止。"},{"id":320,"type":"judge","stem":"宿舍夜间断电后，违规使用计算机影响他人休息者，学校师生、宿舍管理人员等均有权进行劝说、制止。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生公寓管理规定》","category":"学生公寓","excerpt":"第四十七条宿舍内使用计算机应自觉遵守管理规定和作息制度，不影响他人学习和休息。宿舍夜间断电后，违规使用计算机影响他人休息者，学校师生、宿舍管理人员等均有权进行劝说、制止。第五节维修管理第四十八条学生公寓设施日常维修由物业公司负责，物业工作人员定期或不定期进行巡检，专项维修由物业公司上报后勤管理处后安排实施。"},{"id":321,"type":"judge","stem":"严禁私自在学生公寓内安装使用洗衣机。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生公寓管理规定》","category":"学生公寓","excerpt":"第四十六条严禁私自在学生公寓内安装使用洗衣机。"},{"id":322,"type":"judge","stem":"学生在公寓中的表现纳入学生素质综合评价体系，与学生荣誉称号评选及奖学金评定等结合。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生公寓管理规定》","category":"学生公寓","excerpt":"第六十九条学生在公寓中的表现纳入学生素质综合评价体系，与学生荣誉称号评选及奖学金评定等结合。"},{"id":323,"type":"judge","stem":"学生公寓卫生的总体要求是：洁净、整齐。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生公寓管理规定》","category":"学生公寓","excerpt":"第三十条学生公寓实行传染病申报制度。凡有《中华人民共和国传染病防治法》规定的各类传染病患者，应主动报告学生工作部门或校医院，在治愈前或排除传染病嫌疑前，应服从学校安排。第三节卫生管理第三十一条学生公寓卫生的总体要求是：洁净、整齐。"},{"id":324,"type":"judge","stem":"学生公寓内学生在使用充电器具时，房间内无须有人，但离开宿舍须切断电源。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）学生公寓管理规定》","category":"学生公寓","excerpt":"第二十九条学生在使用充电器具时，房间内必须有人，离开宿舍须切断电源。"},{"id":325,"type":"judge","stem":"学生进入学生公寓时，对尾随跟入的陌生人，有义务劝止。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生公寓管理规定》","category":"学生公寓","excerpt":"第十九条学生凭校园一卡通刷卡（或智能门禁识别）进入学生公寓，严禁以攀爬阳台、护栏、窗户等非正常手段强行进入，严禁将校园一卡通转借他人，严禁带领陌生人进入公寓。对尾随跟入的陌生人，有义务劝止。"},{"id":326,"type":"judge","stem":"毕业生办理完退宿手续后不必保持学生公寓房间内卫生洁净、整齐。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）学生公寓管理规定》","category":"学生公寓","excerpt":"第三十八条毕业生办理完退宿手续后应保持房间内卫生洁净、整齐。第四节秩序管理第三十九条学生公寓早5：30开门，晚23：00关门，学生要严格遵守学校作息制度和学生公寓管理规定，按时归宿。晚归或断电后外出学生需主动出示有效证件，配合物业管理人员做好登记后方可出入。"},{"id":327,"type":"judge","stem":"学生公寓楼道内严禁停放自行车。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生公寓管理规定》","category":"学生公寓","excerpt":"第四十一条楼道及房间内严禁停放自行车，自行车要整齐停放在“停车线”内。"},{"id":328,"type":"judge","stem":"学生公寓严禁乱拉线（灯），特殊情况须经后勤管理处批准，由物业公司统一布线，违者拆除。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生公寓管理规定》","category":"学生公寓","excerpt":"第二十八条学生公寓严禁乱拉线（灯），特殊情况须经后勤管理处批准，由物业公司统一布线，违者拆除。"},{"id":329,"type":"judge","stem":"学生公寓用电按照“满足基本需要、杜绝浪费、定额管理、超额自负”的原则，实行定额内免费供电和超定额部分自己承担费用相结合的管理办法.","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生公寓管理规定》","category":"学生公寓","excerpt":"第五十五条学生公寓用电按照“满足基本需要、杜绝浪费、定额管理、超额自负”的原则，实行定额内免费供电和超定额部分自己承担费用相结合的管理办法。"},{"id":330,"type":"judge","stem":"学生公寓原则上不允许异性进入，特殊情况须持有效证件登记后方可进入。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生公寓管理规定》","category":"学生公寓","excerpt":"第四十二条学生公寓原则上不允许异性进入，特殊情况须持有效证件登记后方可进入。"},{"id":331,"type":"judge","stem":"学生公寓内发现可疑人员应及时报告公寓值班人员或公安（保卫）处。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生公寓管理规定》","category":"学生公寓","excerpt":"第二十一条学生离开宿舍时要关好门窗，现金及贵重物品妥善保管。发现可疑人员应及时报告公寓值班人员或保卫处。"},{"id":332,"type":"judge","stem":"学生公寓配备消防设备，可以移动、挪用，但不能损坏消防器材。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）学生公寓管理规定》","category":"学生公寓","excerpt":"第二十五条学生公寓配备消防设备，严禁移动、挪用、损坏消防器材。"},{"id":333,"type":"judge","stem":"学生公寓实行传染病申报制度。凡有《中华人民共和国传染病防治法》规定的各类传染病患者，应主动报告学生工作部门或校医院，在治愈前或排除传染病嫌疑前，应服从学校安排。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生公寓管理规定》","category":"学生公寓","excerpt":"第三十条学生公寓实行传染病申报制度。凡有《中华人民共和国传染病防治法》规定的各类传染病患者，应主动报告学生工作部门或校医院，在治愈前或排除传染病嫌疑前，应服从学校安排。第三节卫生管理第三十一条学生公寓卫生的总体要求是：洁净、整齐。"},{"id":334,"type":"judge","stem":"学生公寓早5:30开门，晚24：00关门。晚归或断电后外出学生需主动出示有效证件，配合物业管理人员做好登记后方可出入。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）学生公寓管理规定》","category":"学生公寓","excerpt":"第三十八条毕业生办理完退宿手续后应保持房间内卫生洁净、整齐。第四节秩序管理第三十九条学生公寓早5：30开门，晚23：00关门，学生要严格遵守学校作息制度和学生公寓管理规定，按时归宿。晚归或断电后外出学生需主动出示有效证件，配合物业管理人员做好登记后方可出入。"},{"id":335,"type":"judge","stem":"本校本科生、硕士生毕业后继续在我校攻读硕士学位、博士学位者，应按时办理毕业离校退宿手续，在规定时间入校时，再按相关要求办理住宿手续。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生公寓管理规定》","category":"学生公寓","excerpt":"第十条学生毕业、退学、休学、转学、出国、开除学籍以及自愿申请退宿的，应当按照学校规定的流程办理退宿手续，物业公司对学生宿舍进行检查，对丢失或损坏公共物品者，要追究赔偿责任。对故意损坏者，责令其赔偿相应损失，结清相关费用后，在规定时间内搬离宿舍。本校本科生、硕士生毕业后继续在我校攻读硕士学位、博士学位者，应按时办理毕业离校退宿手续，在规定时间入校时，再按相关要求办理住宿手续。"},{"id":336,"type":"judge","stem":"宿舍内可以储藏但不能使用易燃、易爆、强腐蚀性物品。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）学生公寓管理规定》","category":"学生公寓","excerpt":"第二十七条宿舍内严禁储藏或使用易燃、易爆、强腐蚀性物品，严禁使用明火、违章电器、防限电插座，严禁盗用公共用电。"},{"id":337,"type":"judge","stem":"学生要爱护公物，养成节水、节电的良好习惯，严禁有踢、拆、砸、烧等损坏公共设施的行为。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生公寓管理规定》","category":"学生公寓","excerpt":"第四十四条学生要爱护公物，养成节水、节电的良好习惯，严禁有踢、拆、砸、烧等损坏公共设施的行为。严禁在学生公寓内赌博、打麻将、酗酒、打架、斗殴及其他违法违纪活动。严禁在公寓内饲养和携带动物。"},{"id":338,"type":"judge","stem":"申诉委应在接到书面申诉之日起15日内作出复查结论，告知申诉人，并出具复查决定书。情况复杂不能在规定限期内作出结论的，经学校负责人批准，可延长15日。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生申诉处理办法（修订）》","category":"申诉处理","excerpt":"第十二条申诉委应在接到书面申诉之日起15日内作出复查结论，告知申诉人，并出具复查决定书。情况复杂不能在规定限期内作出结论的，经学校负责人批准，可延长15日。"},{"id":339,"type":"judge","stem":"学生申诉过程中，自处理、处分或者复查决定书送达之日起，学生在申诉期内未提出申诉的视为放弃申诉，学校或者省级教育行政部门不再受理其提出的申诉。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《普通高等学校学生管理规定》（教育部令第 号）》","category":"其他","excerpt":""},{"id":340,"type":"judge","stem":"学校本科专业标准学制四年（建筑学专业学制五年），实行学分制管理和弹性学习年限，学生可在标准学制的基础上提前两年或延长一年毕业。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）本科生学籍管理规定》","category":"学籍管理","excerpt":"第三条学校本科专业标准学制四年（建筑学专业学制五年），实行学分制管理和弹性学习年限，学生可在标准学制的基础上提前一年或延长两年毕业。"},{"id":341,"type":"judge","stem":"成绩的评定，可采用百分制（60分为及格）、五级记分制（优秀、良好、中等、及格、不及格）或二级记分制（及格、不及格）记载，及格及以上成绩取得该门课程学分。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）本科生学籍管理规定》","category":"学籍管理","excerpt":"第十四条成绩的评定，可采用百分制（60分为及格）、五级记分制（优秀、良好、中等、及格、不及格）或二级记分制（通过、不通过）记载，及格及以上成绩（或通过）取得该门课程学分。"},{"id":342,"type":"judge","stem":"连续4学期每学期选课学分数均小于20学分的学生，学校应予退学处理。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）本科生学籍管理规定》","category":"学籍管理","excerpt":"……第四十条2.连续4学期每学期选课学分数均小于15学分的；"},{"id":343,"type":"judge","stem":"学分制收费，是按照学分计收学费的收费管理制度。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"中国石油大学（华东）学分制收费管理暂行办法","category":"学分制收费","excerpt":"第四条本办法所称学分制收费，是按照专业注册学费和学分学费两部分计收学费的收费管理制度。学分制收费执行政府定价或政府指导价。第二章收费项目及标准第五条专业注册学费是学生进行专业学习注册取得专业课程选修资格需缴纳的费用。专业注册学费由学校按照不同专业生均培养成本等因素合理确定。专业注册学费按学年计收。学校在每学年初向学生收取专业注册学费，为学生办理专业注册手续，授予学生本学年选课资格。学校按照学生实际修业年限收取专业注册学费。"},{"id":344,"type":"judge","stem":"社团会员可以不是我校学生。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"中国石油大学（华东）学生社团管理办法","category":"学生社团","excerpt":""},{"id":345,"type":"judge","stem":"本专科生奖学金每人每年最高不超过6000元，研究生奖学金每人每年最高不超过10000元。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"中国石油大学（华东）国家助学贷款实施办法（修订）","category":"奖学金与资助","excerpt":"……第三条3.申请金额本专科生每人每年最高不超过20000元，研究生每人每年最高不超过25000元。"},{"id":346,"type":"judge","stem":"学生公寓严禁酗酒、抽烟、点蜡烛、焚烧物品、燃放鞭炮等，严禁用任何方式自炊。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"中国石油大学（华东）学生公寓管理规定","category":"学生公寓","excerpt":"第二十六条学生公寓严禁酗酒、抽烟、点蜡烛、焚烧物品、燃放鞭炮等，严禁用任何方式自炊。"},{"id":347,"type":"judge","stem":"获得计算机三级等级证书，可以计2学分。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"中国石油大学(华东)本科生自主发展计划","category":"自主发展计划","excerpt":""},{"id":348,"type":"judge","stem":"校级大学生创业基地入驻条件中要求项目负责人为我校在读学生。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"中国石油大学(华东)大学生创业实践管理办法","category":"创新创业","excerpt":"第五条基地入驻条件：1.项目负责人为我校全日制在校学生。2.具有较好市场前景且落地实体运转的创业项目、拥有自主知识产权的创业项目、在国家级或省级创业比赛中获奖的创业项目优先考虑。"},{"id":349,"type":"judge","stem":"大学生创业基地入驻项目应定期向办公室提交项目运行情况报告,并接受中期检查和期满验收考核","options":[["A","对"],["B","错"]],"answer":["A"],"source":"中国石油大学(华东)大学生创业实践管理办法","category":"创新创业","excerpt":"第十一条基金运作管理：1.受资助的项目应定期向办公室提交基金使用情况的财务报告和项目运行情况报告，并接受中期检查和期满验收考核。2.受资助的项目因客观原因需对目标、进度和经费等进行调整时，应向办公室提出书面申请，经审核通过方可执行。3.受资助的项目提前退出时，须提前提出书面申请，报办公室审核后，办理清算核销手续。4.受资助项目如有盈利，根据项目收益情况，将项目净利润5%上交学校大学生创业基金，用以滚动支持更多创业项目。第五章扶持政策第十二条办公室负责与政府、企业、校友联系，为大学生创业项目争取场地、技术、资金等扶持政策。"},{"id":350,"type":"judge","stem":"读者可以通过“网上图书馆”或在各服务台预约图书，预约仅限不在馆藏图书，每次预约仅限5册。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"中国石油大学（华东）图书馆开架书库借阅管理规定","category":"图书馆","excerpt":"……四、读者可以通过“网上图书馆”（微信公众号或图书馆主页均可）或在各服务台预约、续借图书，预约仅限不在馆藏图书，每次预约仅限1册。"},{"id":351,"type":"judge","stem":"文艺书库每日开放时间为上午8点至12点，下午2点至5点半，晚上7点至10点。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"中国石油大学（华东）图书馆开架书库借阅管理规定","category":"图书馆","excerpt":""},{"id":352,"type":"judge","stem":"借书时需要消磁，人工还书时需要充磁。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"中国石油大学（华东）图书馆开架书库借阅管理规定","category":"图书馆","excerpt":""},{"id":353,"type":"judge","stem":"自助还书机无法识别的图书，在工作时间交给值班人员，非工作时间扔在还书台的台面上即可。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"中国石油大学（华东）图书馆开架书库借阅管理规定","category":"图书馆","excerpt":""},{"id":354,"type":"judge","stem":"书太多，背来背去很麻烦，索性放在图书馆的阅览桌上，还可以占座。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"中国石油大学（华东）图书馆开架书库借阅管理规定","category":"图书馆","excerpt":""},{"id":355,"type":"judge","stem":"2005年1月，学校更名为中国石油大学。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《学校概况》 前言 第I页》","category":"学校概况","excerpt":"……2005年1月，学校更名为中国石油大学。"},{"id":356,"type":"judge","stem":"2010年,学校成为国家首批实施“卓越工程师教育培养计的61所高校之一。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《学校概况》 前言 第Ⅱ页》","category":"学校概况","excerpt":"栻2006年10月，学校以“优秀”成绩通过教育部本科教学工作水平评估。2010年，学校成为国家首批实施“卓越工程师教育培养计划”的61所试点高校之一和承担国家“专业学位研究生教育综合改革试点工作”的32家部属高校之一。2014年4月，教育部与中国石油天然气集团公司、中国石油化工集团公司、中国海洋石油总公司、神华集团有限责任公司、陕西延长石油（集团）有限责任公司等五大能源企业集团公司签署共建中国石油大学协议。2018年12月，教育部、山东省人民政府重点共建中国石油大学（华东）。2021年，学校注册地调整至青岛。"},{"id":357,"type":"judge","stem":"学校现有青岛、东营两个校区,校园总面积2500亩,建筑面积99万平方米,图书馆藏书140万册。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《学校概况》 前言 第Ⅱ页》","category":"学校概况","excerpt":"学校总占地面积5000余亩，建筑面积170余万平方米，发展形成了“两校区一园区”（青岛唐岛湾校区、古镇口校区以及东营科教园区）的办学格局。青岛两校区地处迷人的帆船之都、海滨之城，享有极高美誉的青岛，东营科教园区地处黄河三角洲的中心城市、生态之城、石油之城———山东东营，“两校区一园区”均位于“蓝黄”两大国家战略重点区域，同时青岛两校区还处于2014年新设立的国家级新区———青岛西海岸新区。学校建有研究生院，有地球科学与技术学院，石油工程学院，化学化工学院，机电工程学院，储运与建筑工程学院，材料科学与工程学院，石大山能新能源学院，海洋与空间信息学院，控制科学与工程学院，青岛软件学院、计算机科学与技术学院，理学院，经济管理学院，外国语学院，文法学院，马克思主义学院，体育教学部等16个教学学院（部），以及荟萃学院、国际教育学院、远程教育学院和继续教育学院。"},{"id":358,"type":"judge","stem":"个人自评:学生根据自己日常表现,向院部测评小组提交相关证明材料。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）学生综合素质测评办法（试行）》","category":"综合素质测评","excerpt":"……第七条（一）个人自评：学生根据自己日常表现，向班级测评小组提交相关证明材料。"},{"id":359,"type":"judge","stem":"发展性素质成绩根据记实和评议得出；基础性素质成绩根据学生所获荣誉、奖励及实际参加各类活动情况记实得出。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）学生综合素质测评办法（试行）》","category":"综合素质测评","excerpt":"……第七条其中，基础性素质成绩根据记实和评议得出；发展性素质成绩根据学生所获荣誉、奖励及实际参加各类活动情况记实得出。"},{"id":360,"type":"judge","stem":"思想政治表现:主要评议学生政治表现、思想水平、法纪观念等。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生综合素质测评办法（试行）》","category":"综合素质测评","excerpt":"……第七条思想政治表现：主要评议学生政治表现、思想水平、法纪观念等。"},{"id":361,"type":"judge","stem":"道德品质修养:主要评议学生道德品质、集体观念、劳动观念、生活态度等。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生综合素质测评办法（试行）》","category":"综合素质测评","excerpt":"……第七条道德品质修养：主要评议学生道德品质、集体观念、劳动观念、生活态度等。"},{"id":362,"type":"judge","stem":"身心健康素质:主要评议学生体育活动情况、体能测试情况、心理健康状况等。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生综合素质测评办法（试行）》","category":"综合素质测评","excerpt":"……第七条身心健康素质：主要评议学生体育活动情况、体能测试情况、心理健康状况等。"},{"id":363,"type":"judge","stem":"日常行为规范:主要评议学生遵守校规校纪情况、《学生文明行为规范》及《学生公寓管理规定》表现等。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生综合素质测评办法（试行）》","category":"综合素质测评","excerpt":"……第七条日常行为规范：主要评议学生遵守校规校纪情况、《学生文明行为规范》及《学生公寓管理规定》表现等。"},{"id":364,"type":"judge","stem":"基础性素质测评成绩中的记实部分是指院部对学生在日常学习、生活和工作中的行为记录。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生综合素质测评办法（试行）》","category":"综合素质测评","excerpt":"……第七条2.“记实”是指院部对学生在日常学习、生活和工作中的行为进行记录。"},{"id":365,"type":"judge","stem":"学生违纪处理后，应在发展性素质测评分数中扣除相应分值。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）学生综合素质测评办法（试行）》","category":"综合素质测评","excerpt":"……第七条4.学生违纪处理扣分参考标准：批评教育扣10分、通报批评扣20分、警告扣30分、严重警告扣40分；记过及以上处分者基础性素质测评成绩为0分。"},{"id":366,"type":"judge","stem":"基础性素质测评成绩中的评议部分是指，根据思想政治表现、道德品质修养、身心健康、日常行为规范等方面相关内容,对学生的现实表现做出评议。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生综合素质测评办法（试行）》","category":"综合素质测评","excerpt":"……第七条3.“评议”是指根据思想政治表现、道德品质修养、身心健康素质、日常行为规范等方面相关内容，对学生的现实表现做出评议，由两部分组成。"},{"id":367,"type":"judge","stem":"发展性素质内容包括:“创新创业能力”、“社会实践能力”、“文体活动能力”及“其他4类测评指标,满分100分。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生综合素质测评办法（试行）》","category":"综合素质测评","excerpt":"……第七条1.发展性素质内容包括：“创新创业能力”、“社会实践能力”、“文体活动能力”及“其他”4类测评指标，满分100分，各院部结合《中国石油大学（华东）本科生自主发展计划》组织实施。"},{"id":368,"type":"judge","stem":"发展性素质中的社会实践能力主要评议学生参与社会实践活动、志愿服务活动等校外实践活动情况。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）学生综合素质测评办法（试行）》","category":"综合素质测评","excerpt":"……第七条社会实践能力：主要评议学生参与社会实践活动、志愿服务活动、各级学生组织活动情况及表现等。"},{"id":369,"type":"judge","stem":"发展性素质中的文体活动能力主要评议学生参与各级各类文化、艺术、体育活动情况及表现等。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生综合素质测评办法（试行）》","category":"综合素质测评","excerpt":"……第七条文体活动能力：主要评议学生参与各级各类文化、艺术、体育活动情况及表现等。"},{"id":370,"type":"judge","stem":"发展性素质中的创新创业能力主要评议学生参与各类科技竞赛、科技活动、大学生创新创业训练计划项目、创新创业推广、创新创业实施情况及表现等。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生综合素质测评办法（试行）》","category":"综合素质测评","excerpt":"……第七条创新创业能力：主要评议学生参与各类科技竞赛、科技活动、大学生创新创业训练计划项目、创新创业推广、创新创业实施情况及表现等。"},{"id":371,"type":"judge","stem":"综合优秀一等奖学金4000元/人,按学生数的3%评定;二等奖学金2000元/人,按学生数的6%评定;三等奖学金1000元/人,按学生数的10%评定。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）学生奖学金管理细则(试行)》","category":"奖学金与资助","excerpt":"……第五条奖励标准：该奖项分为三个等级：一等奖学金4000元/人，按学生数的3%评定；二等奖学金2000元/人，按学生数的7%评定；三等奖学金1000元/人，按学生数的15%评定。"},{"id":372,"type":"judge","stem":"社会工作奖学金奖励标准是800元/人,按学生数的10%评定。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）学生奖学金管理细则(试行)》","category":"奖学金与资助","excerpt":"……第五条奖励标准：该奖项分为三个等级：一等奖学金4000元/人，按学生数的3%评定；二等奖学金2000元/人，按学生数的7%评定；三等奖学金1000元/人，按学生数的15%评定。"},{"id":373,"type":"judge","stem":"文体奖学金奖励标准是800元/人,按学生数的10%评定。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生奖学金管理细则(试行)》","category":"奖学金与资助","excerpt":"……第五条奖励标准：该奖项分为三个等级：一等奖学金4000元/人，按学生数的3%评定；二等奖学金2000元/人，按学生数的7%评定；三等奖学金1000元/人，按学生数的15%评定。"},{"id":374,"type":"judge","stem":"科技创新奖学金奖励标准是800元/人,按学生数的5%评定。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生奖学金管理细则(试行)》","category":"奖学金与资助","excerpt":"……第五条奖励标准：该奖项分为三个等级：一等奖学金4000元/人，按学生数的3%评定；二等奖学金2000元/人，按学生数的7%评定；三等奖学金1000元/人，按学生数的15%评定。"},{"id":375,"type":"judge","stem":"按照学生申办地点及工作流程不同,国家助学贷款分为校园地国家助学贷款与生源地信用助学贷款两种模式。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）国家助学贷款实施办法》","category":"奖学金与资助","excerpt":"……第三条第二章贷款模式第四条按照学生申办地点及工作流程不同，国家助学贷款分为校园地国家助学贷款与生源地信用助学贷款两种模式。"},{"id":376,"type":"judge","stem":"全日制普通本专科生在同一学年可以重复申请获得校园地国家助学贷款和生源地信用助学贷款。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）国家助学贷款实施办法》","category":"奖学金与资助","excerpt":"……第三条全日制普通本专科生在同一学年不得重复申请获得校园地国家助学贷款和生源地信用助学贷款，只能选择申请办理其中一种贷款。"},{"id":377,"type":"judge","stem":"校园地国家助学贷款借款学生在校学习期间利息全部由财政补贴,毕业后的利息由借款学生本人全额支付。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）国家助学贷款实施办法》","category":"奖学金与资助","excerpt":"……第三条借款学生在校学习期间利息全部由财政补贴，毕业后的利息由借款学生本人全额支付。"},{"id":378,"type":"judge","stem":"校园地国家助学贷款借款学生毕业后,在还款期内继续攻读学位的,可申请继续财政贴息。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）国家助学贷款实施办法》","category":"奖学金与资助","excerpt":"……第三条借款学生毕业后，在还款期内继续攻读学位的，可申请继续贴息，应及时向组织办理校园地国家助学贷款的原高校提供书面证明，经办机构审核后，报经办银行确认，继续攻读学位期间发生的贷款利息，由原贴息财政部门继续全额贴息。……7.还款期限和还款方式校园地国家助学贷款期限原则上按学制加15年确定，最长不超过22年。……学生在校及毕业后5年期间为偿还本金宽限期，偿还本金宽限期结束后，由学生按借款合同约定，分期偿还贷款本息。……8.违约后果栙国家助学贷款的借款学生如未按照与经办银行签订的还款协议约定的期限、数额偿还贷款，经办银行将对其违约还款金额计收罚息；栚经办银行将违约情况录入中国人民银行的金融信用信息基础数据库，供全国各金融机构依法查询。……对恶意拖欠贷款的违约借款人采取限制措施，不予提供住房贷款、汽车贷款等金融服务；栛对于连续拖欠还款行为严重的借款人，有关行政管理部门和银行将通过新闻媒体和网络等信息渠道公布其姓名、公民身份号码、毕业学校及具体违约行为等信息；栜严重违约的借款人还将承担相关法律责任。……第四章生源地信用助学贷款家庭经济困难的全日制本科生、第二学士学位学生和研究生，通过户籍所在县（市、区）的学生资助管理机构申请办理（有的地区直接到相关金融机构申请）的国家助学贷款。……学生和家长为共同借款人，共同承担还款责任。……2.办理程序生源地信用助学贷款按年度申请、审批和发放。……学生在新学期开始前，向家庭所在县（市、区）的学生资助管理中心提出贷款申请（有的地区直接到相关金融机构申请）。……县级学生资助管理中心负责对学生提交的申请进行资格初审。……金融机构负责最终审批并发放贷款。………"},{"id":379,"type":"judge","stem":"生源地信用助学贷款申请学生在新学期开始前,需向家庭所在县（市、区）的学生资助管理中心提出贷款申请（有的地区直接到相关金融机构申请）。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）国家助学贷款实施办法》","category":"奖学金与资助","excerpt":"……第三条第四章生源地信用助学贷款家庭经济困难的全日制本科生、第二学士学位学生和研究生，通过户籍所在县（市、区）的学生资助管理机构申请办理（有的地区直接到相关金融机构申请）的国家助学贷款。学生和家长为共同借款人，共同承担还款责任。1.申请条件栙具有中华人民共和国国籍；栚诚实守信，遵纪守法；栛已被我校正式录取，取得真实、合法、有效的录取通知书的新生或我校在读的本科学生、第二学士学位学生和研究生；栜学生本人入学前户籍、其父母（或其他法定监护人）户籍均在本县（市、区）；栞家庭经济困难，所能获得的收入不足以支付在校期间完成学业所需的基本费用。2.办理程序生源地信用助学贷款按年度申请、审批和发放。学生在新学期开始前，向家庭所在县（市、区）的学生资助管理中心提出贷款申请（有的地区直接到相关金融机构申请）。"},{"id":380,"type":"judge","stem":"生源地信用助学贷款借款学生在校学习期间利息全部由财政补贴,毕业后的利息由借款学生本人全额支付。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）国家助学贷款实施办法》","category":"奖学金与资助","excerpt":"……第三条借款学生在校学习期间利息全部由财政补贴，毕业后的利息由借款学生本人全额支付。"},{"id":381,"type":"judge","stem":"生源地信用助学贷款借款学生毕业后,在还款期内继续攻读学位的,可申请继续财政贴息。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）国家助学贷款实施办法》","category":"奖学金与资助","excerpt":"……第三条借款学生毕业后，在还款期内继续攻读学位的，可申请继续贴息，应及时向组织办理校园地国家助学贷款的原高校提供书面证明，经办机构审核后，报经办银行确认，继续攻读学位期间发生的贷款利息，由原贴息财政部门继续全额贴息。……7.还款期限和还款方式校园地国家助学贷款期限原则上按学制加15年确定，最长不超过22年。……学生在校及毕业后5年期间为偿还本金宽限期，偿还本金宽限期结束后，由学生按借款合同约定，分期偿还贷款本息。……8.违约后果栙国家助学贷款的借款学生如未按照与经办银行签订的还款协议约定的期限、数额偿还贷款，经办银行将对其违约还款金额计收罚息；栚经办银行将违约情况录入中国人民银行的金融信用信息基础数据库，供全国各金融机构依法查询。……对恶意拖欠贷款的违约借款人采取限制措施，不予提供住房贷款、汽车贷款等金融服务；栛对于连续拖欠还款行为严重的借款人，有关行政管理部门和银行将通过新闻媒体和网络等信息渠道公布其姓名、公民身份号码、毕业学校及具体违约行为等信息；栜严重违约的借款人还将承担相关法律责任。……第四章生源地信用助学贷款家庭经济困难的全日制本科生、第二学士学位学生和研究生，通过户籍所在县（市、区）的学生资助管理机构申请办理（有的地区直接到相关金融机构申请）的国家助学贷款。……学生和家长为共同借款人，共同承担还款责任。……2.办理程序生源地信用助学贷款按年度申请、审批和发放。……学生在新学期开始前，向家庭所在县（市、区）的学生资助管理中心提出贷款申请（有的地区直接到相关金融机构申请）。……县级学生资助管理中心负责对学生提交的申请进行资格初审。……金融机构负责最终审批并发放贷款。………"},{"id":382,"type":"judge","stem":"同一学年内,获得国家奖学金的家庭经济困难学生可以同时申请并获得国家助学金,但不能同时获得国家励志奖学金。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）“国家奖学金”、“国家励志奖学金”、“国家助学金”评选实施细则》","category":"奖学金与资助","excerpt":"第七条国家助学金（不含退役士兵学生国家助学金）用于资助纳入全国招生计划内的全日制本科（不含退役士兵学生）在校生中的家庭经济困难学生，帮助其顺利完成学业。全日制在校退役士兵学生全部享受本科生国家助学金。第四章申请条件第八条申请国家奖学金、国家励志奖学金、国家助学金的基本条件：（一）具有中华人民共和国国籍；（二）热爱祖国，拥护中国共产党的领导；（三）遵守宪法和法律，无违法违规记录；遵守学校规章制度，未受警告及以上处分；（四）诚实守信，道德品质优良；（五）积极参加体育锻炼，身体素质良好，达到《国家学生体质健康标准》要求。"},{"id":383,"type":"judge","stem":"十大学生标兵的事迹将通过校报、网络等媒体进行广泛宣传,并将在此范围内推荐山东省十大优秀学生人选。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）十大学生标兵评选实施细则》","category":"其他","excerpt":"四、奖励事项：十大学生标兵事迹将通过校报、网络等媒体进行广泛宣传，并将在此范围内推荐山东省十大优秀学生人选。"},{"id":384,"type":"judge","stem":"个别同学出现违纪行为是个人行为，不应该让其他班级同学受到牵连，其所在班级仍然具有参评先进班集体的资格，但应按相关规定扣除一部分分数。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）先进班集体、优秀学生、优秀学生干部评选标准》","category":"优良学风班","excerpt":""},{"id":385,"type":"judge","stem":"同一学年内,获得国家奖学金、国家励志奖学金的学生只要条件符合，可重复获得其它1000元（含1000元）以上奖学金。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）“国家奖学金”、“国家励志奖学金”、“国家助学金”评选实施细则》","category":"奖学金与资助","excerpt":"第七条国家助学金（不含退役士兵学生国家助学金）用于资助纳入全国招生计划内的全日制本科（不含退役士兵学生）在校生中的家庭经济困难学生，帮助其顺利完成学业。全日制在校退役士兵学生全部享受本科生国家助学金。第四章申请条件第八条申请国家奖学金、国家励志奖学金、国家助学金的基本条件：（一）具有中华人民共和国国籍；（二）热爱祖国，拥护中国共产党的领导；（三）遵守宪法和法律，无违法违规记录；遵守学校规章制度，未受警告及以上处分；（四）诚实守信，道德品质优良；（五）积极参加体育锻炼，身体素质良好，达到《国家学生体质健康标准》要求。"},{"id":386,"type":"judge","stem":"学生违反法律法规，并依照有关法律追究其法律责任的，学校应以法律优先，不再予以其校内处分。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第三条学校给予学生处分，应当坚持教育与惩戒相结合，与学生违法、违纪行为的性质和过错的严重程度相适应。学校对学生的处分，要做到证据充分、依据明确、定性准确、程序正当、处分适当。第二章处分的种类和适用第四条学生有违反法律法规的行为，应依照有关法律规定追究法律责任，同时依照本规定给予纪律处分。"},{"id":387,"type":"judge","stem":"在违纪过程中,主动有效地制止事件（事态）发生、发展的，可以减轻处分。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第七条学生有以下情形之一的，可以从轻或者减轻处分：（一）在违纪过程中，主动有效地制止事件（事态）发生、发展；（二）主动交代错误事实，承认错误，且有明显悔改表现；（三）积极配合有关部门调查、核实情况或者提供重要证据、线索，能主动提供情况揭发他人违纪行为并经查证属实；（四）被他人胁迫或者诱骗，并能主动揭发事件；（五）其他可以从轻或者减轻处分的情形。"},{"id":388,"type":"judge","stem":"主动交待错误事实,承认错误,且有明显悔改表现的，可以减轻处分。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第七条学生有以下情形之一的，可以从轻或者减轻处分：（一）在违纪过程中，主动有效地制止事件（事态）发生、发展；（二）主动交代错误事实，承认错误，且有明显悔改表现；（三）积极配合有关部门调查、核实情况或者提供重要证据、线索，能主动提供情况揭发他人违纪行为并经查证属实；（四）被他人胁迫或者诱骗，并能主动揭发事件；（五）其他可以从轻或者减轻处分的情形。"},{"id":389,"type":"judge","stem":"积极配合有关部门调查、核实情况或者提供重要证据、线索,能主动提供情况揭发他人违纪行为并经查证属实的，可以减轻处分。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第七条学生有以下情形之一的，可以从轻或者减轻处分：（一）在违纪过程中，主动有效地制止事件（事态）发生、发展；（二）主动交代错误事实，承认错误，且有明显悔改表现；（三）积极配合有关部门调查、核实情况或者提供重要证据、线索，能主动提供情况揭发他人违纪行为并经查证属实；（四）被他人胁迫或者诱骗，并能主动揭发事件；（五）其他可以从轻或者减轻处分的情形。"},{"id":390,"type":"judge","stem":"被他人胁迫或者诱骗,并能主动揭发事件，可以减轻处分。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第七条学生有以下情形之一的，可以从轻或者减轻处分：（一）在违纪过程中，主动有效地制止事件（事态）发生、发展；（二）主动交代错误事实，承认错误，且有明显悔改表现；（三）积极配合有关部门调查、核实情况或者提供重要证据、线索，能主动提供情况揭发他人违纪行为并经查证属实；（四）被他人胁迫或者诱骗，并能主动揭发事件；（五）其他可以从轻或者减轻处分的情形。"},{"id":391,"type":"judge","stem":"曾为学校获得过较高荣誉的，可凭对学校的突出贡献减轻处分。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第三十九条学生对学校的处分决定有异议的，可以在接到学校处分决定书之日起10日内，向学校学生申诉处理委员会提出书面申诉。学生申诉处理委员会对学生提出的申诉进行复查，作出复查决定。学生对复查决定有异议的，在接到学校复查决定书之日起15日内，可以向山东省教育厅提出书面申诉。"},{"id":392,"type":"judge","stem":"在供认违纪过程中，互相串供,隐瞒真相的，应从重处分。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第八条学生有以下情形之一的，可以从重或者加重处分：（一）互相串供，隐瞒真相；（二）对有关人员打击报复、威胁恫吓；（三）贿赂违纪处理人员或者以其他方式干扰违纪处理工作；（四）作为集体违纪事件组织策划者，或者教唆、煽动他人违纪并造成严重后果；（五）同时有两种以上违纪行为或者屡次违纪；（六）其他可以从重或者加重处分的情形。第三章违纪行为和处分第九条对有违反宪法，反对四项基本原则行为者，给予开除学籍处分。"},{"id":393,"type":"judge","stem":"为逃避责任，对有关人员打击报复、威胁恫吓的，应从重处分。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第八条学生有以下情形之一的，可以从重或者加重处分：（一）互相串供，隐瞒真相；（二）对有关人员打击报复、威胁恫吓；（三）贿赂违纪处理人员或者以其他方式干扰违纪处理工作；（四）作为集体违纪事件组织策划者，或者教唆、煽动他人违纪并造成严重后果；（五）同时有两种以上违纪行为或者屡次违纪；（六）其他可以从重或者加重处分的情形。第三章违纪行为和处分第九条对有违反宪法，反对四项基本原则行为者，给予开除学籍处分。"},{"id":394,"type":"judge","stem":"为逃避责任，贿赂违纪处理人员或者以其他方式干扰违纪处理工作，应从重处分。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第八条学生有以下情形之一的，可以从重或者加重处分：（一）互相串供，隐瞒真相；（二）对有关人员打击报复、威胁恫吓；（三）贿赂违纪处理人员或者以其他方式干扰违纪处理工作；（四）作为集体违纪事件组织策划者，或者教唆、煽动他人违纪并造成严重后果；（五）同时有两种以上违纪行为或者屡次违纪；（六）其他可以从重或者加重处分的情形。第三章违纪行为和处分第九条对有违反宪法，反对四项基本原则行为者，给予开除学籍处分。"},{"id":395,"type":"judge","stem":"作为集体违纪事件组织策划者,或者教唆、煽动他人违纪并造成严重后果的，应从重处分。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第八条学生有以下情形之一的，可以从重或者加重处分：（一）互相串供，隐瞒真相；（二）对有关人员打击报复、威胁恫吓；（三）贿赂违纪处理人员或者以其他方式干扰违纪处理工作；（四）作为集体违纪事件组织策划者，或者教唆、煽动他人违纪并造成严重后果；（五）同时有两种以上违纪行为或者屡次违纪；（六）其他可以从重或者加重处分的情形。第三章违纪行为和处分第九条对有违反宪法，反对四项基本原则行为者，给予开除学籍处分。"},{"id":396,"type":"judge","stem":"学生同时有两种以上违纪行为或者屡次违纪,可以从重或者加重处分。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第八条学生有以下情形之一的，可以从重或者加重处分：（一）互相串供，隐瞒真相；（二）对有关人员打击报复、威胁恫吓；（三）贿赂违纪处理人员或者以其他方式干扰违纪处理工作；（四）作为集体违纪事件组织策划者，或者教唆、煽动他人违纪并造成严重后果；（五）同时有两种以上违纪行为或者屡次违纪；（六）其他可以从重或者加重处分的情形。第三章违纪行为和处分第九条对有违反宪法，反对四项基本原则行为者，给予开除学籍处分。"},{"id":397,"type":"judge","stem":"对泄露党和国家机密者,视情节轻重,给予留校察看或者开除学籍处分。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第十一条对泄露党和国家机密者，视情节轻重，给予留校察看或者开除学籍处分。"},{"id":398,"type":"judge","stem":"对破坏民族团结、挑拨民族纠纷者,给予记过处分;情节严重的,给予留校察看或者开除学籍处分。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第十二条对破坏民族团结、挑拨民族纠纷者，给予记过处分；情节严重的，给予留校察看或者开除学籍处分。"},{"id":399,"type":"judge","stem":"组织、煽动闹事、破坏安定团结、扰乱校园秩序未造成严重后果,经教育尚能改正者,给予记过处分。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"……第十四条（一）组织、煽动闹事、破坏安定团结、扰乱校园秩序未造成严重后果，经教育尚能改正者，给予留校察看处分，造成严重后果者，给予开除学籍处分；"},{"id":400,"type":"judge","stem":"组织、煽动闹事、破坏安定团结、扰乱校园秩序未造成严重后果者,给予开除学籍处分。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"……第十四条（一）组织、煽动闹事、破坏安定团结、扰乱校园秩序未造成严重后果，经教育尚能改正者，给予留校察看处分，造成严重后果者，给予开除学籍处分；"},{"id":401,"type":"judge","stem":"张贴、投递、散发非法宣传品,散布、传播虚假信息或者有害信息者,情节较轻的，给予严重警告或者记过处分。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"……第十四条（三）张贴、投递、散发非法宣传品，散布、传播虚假信息或者有害信息者，给予警告或者严重警告处分，造成严重后果或者恶劣影响者，给予记过处分；"},{"id":402,"type":"judge","stem":"参与各种非法集会、游行、示威,不听劝阻者,给予警告或者严重警告处分。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"……第十四条（二）参与各种非法集会、游行、示威，不听劝阻者，给予警告或者严重警告处分，情节严重的，给予记过处分；"},{"id":403,"type":"judge","stem":"在校内参与宗教活动、封建迷信活动者,给予严重警告处分,情节严重的,给予记过处分。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"……第十四条（五）在校内参与宗教活动、封建迷信活动者，给予严重警告处分，情节严重的，给予记过处分；"},{"id":404,"type":"judge","stem":"在校内组织宗教活动或者传播宗教者,给予记过处分,情节严重的,给予留校察看或者开除学籍处分。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"……第十四条（六）在校内组织宗教活动或者传播宗教者，给予记过处分，情节严重的，给予留校察看或者开除学籍处分；"},{"id":405,"type":"judge","stem":"破坏学校教育教学秩序、生活秩序以及公共场所管理秩序者,给予记过或者留校察看处分,情节严重的,给予开除学籍处分。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"……第十四条（七）破坏学校教育教学秩序、生活秩序以及公共场所管理秩序者，给予记过或者留校察看处分，情节严重的，给予开除学籍处分；"},{"id":406,"type":"judge","stem":"主动参与非法传销者,给予记过处分,情节严重的,给予留校察看或者开除学籍处分。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"……第十四条（四）主动参与非法传销者，给予记过处分，情节严重的，给予留校察看或者开除学籍处分；"},{"id":407,"type":"judge","stem":"有窥看、滋扰等侵犯他人合法权益行为者,给予警告或者严重警告处分;情节严重或经教育不改者,给予记过、留校察看或者开除学籍处分。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第十五条对从事或者参与有损大学生形象、有悖社会公序良俗的活动者的处分：（一）破坏环境，情节严重者，给予警告处分；（二）侮辱、诽谤或恐吓他人者，给予警告处分，情节恶劣的，给予记过处分；（三）有窥看、滋扰等侵犯他人合法权益行为者，给予警告或者严重警告处分；情节严重或经教育不改者，给予记过、留校察看或者开除学籍处分；（四）聚众观看淫秽书刊或者声像制品者，给予严重警告处分；（五）在公共设施上乱涂乱画者，给予严重警告或者记过处分；（六）传播、复制、贩卖违规书刊和音像制品者，给予记过处分，情节严重的，给予留校察看处分；（七）宿舍内留宿异性及到异性宿舍留宿者，给予留校察看或者开除学籍处分；（八）其他有损大学生形象、有悖社会公序良俗行为者，视情节轻重，给予相应纪律处分。"},{"id":408,"type":"judge","stem":"传播、复制、贩卖违规书刊和音像制品者,给予严重警告处分,情节严重的,给予记过或者留校察看处分。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第十五条对从事或者参与有损大学生形象、有悖社会公序良俗的活动者的处分：（一）破坏环境，情节严重者，给予警告处分；（二）侮辱、诽谤或恐吓他人者，给予警告处分，情节恶劣的，给予记过处分；（三）有窥看、滋扰等侵犯他人合法权益行为者，给予警告或者严重警告处分；情节严重或经教育不改者，给予记过、留校察看或者开除学籍处分；（四）聚众观看淫秽书刊或者声像制品者，给予严重警告处分；（五）在公共设施上乱涂乱画者，给予严重警告或者记过处分；（六）传播、复制、贩卖违规书刊和音像制品者，给予记过处分，情节严重的，给予留校察看处分；（七）宿舍内留宿异性及到异性宿舍留宿者，给予留校察看或者开除学籍处分；（八）其他有损大学生形象、有悖社会公序良俗行为者，视情节轻重，给予相应纪律处分。"},{"id":409,"type":"judge","stem":"宿舍内留宿异性及到异性宿舍留宿者,给予留校察看或者开除学籍处分。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第十五条对从事或者参与有损大学生形象、有悖社会公序良俗的活动者的处分：（一）破坏环境，情节严重者，给予警告处分；（二）侮辱、诽谤或恐吓他人者，给予警告处分，情节恶劣的，给予记过处分；（三）有窥看、滋扰等侵犯他人合法权益行为者，给予警告或者严重警告处分；情节严重或经教育不改者，给予记过、留校察看或者开除学籍处分；（四）聚众观看淫秽书刊或者声像制品者，给予严重警告处分；（五）在公共设施上乱涂乱画者，给予严重警告或者记过处分；（六）传播、复制、贩卖违规书刊和音像制品者，给予记过处分，情节严重的，给予留校察看处分；（七）宿舍内留宿异性及到异性宿舍留宿者，给予留校察看或者开除学籍处分；（八）其他有损大学生形象、有悖社会公序良俗行为者，视情节轻重，给予相应纪律处分。"},{"id":410,"type":"judge","stem":"转借、借用、冒用他人证件用于不正当行为者,给予警告处分,情节严重的,给予严重警告或者记过处分。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第十六条对违背个人诚信、学术诚信者的处分：（一）转借、借用、冒用他人证件用于不正当行为者，给予警告处分，情节严重的，给予严重警告或者记过处分；（二）伪造、涂改证件及相关证明材料者，给予严重警告处分，情节严重的，给予记过或者留校察看处分；（三）课程作业、结业论文以及实验报告存在剽窃、抄袭、伪造等行为者，视情节轻重，给予严重警告或者记过处分；（四）学位论文、公开发表的研究成果存在抄袭、篡改、伪造等学术不端行为者，给予留校察看处分；情节严重的，或者代写论文、买卖论文的，给予开除学籍处分；（五）其他违背个人诚信、学术诚信行为者，视情节轻重，给予相应的纪律处分。"},{"id":411,"type":"judge","stem":"伪造、涂改证件及相关证明材料者,给予警告处分,情节严重的,给予记过处分。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第十六条对违背个人诚信、学术诚信者的处分：（一）转借、借用、冒用他人证件用于不正当行为者，给予警告处分，情节严重的，给予严重警告或者记过处分；（二）伪造、涂改证件及相关证明材料者，给予严重警告处分，情节严重的，给予记过或者留校察看处分；（三）课程作业、结业论文以及实验报告存在剽窃、抄袭、伪造等行为者，视情节轻重，给予严重警告或者记过处分；（四）学位论文、公开发表的研究成果存在抄袭、篡改、伪造等学术不端行为者，给予留校察看处分；情节严重的，或者代写论文、买卖论文的，给予开除学籍处分；（五）其他违背个人诚信、学术诚信行为者，视情节轻重，给予相应的纪律处分。"},{"id":412,"type":"judge","stem":"学位论文、公开发表的研究成果存在抄袭、篡改、伪造等学术不端行为者,给予留校察看处分;情节严重的,或者代写论文、买卖论文的,给予开除学籍处分。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第十六条对违背个人诚信、学术诚信者的处分：（一）转借、借用、冒用他人证件用于不正当行为者，给予警告处分，情节严重的，给予严重警告或者记过处分；（二）伪造、涂改证件及相关证明材料者，给予严重警告处分，情节严重的，给予记过或者留校察看处分；（三）课程作业、结业论文以及实验报告存在剽窃、抄袭、伪造等行为者，视情节轻重，给予严重警告或者记过处分；（四）学位论文、公开发表的研究成果存在抄袭、篡改、伪造等学术不端行为者，给予留校察看处分；情节严重的，或者代写论文、买卖论文的，给予开除学籍处分；（五）其他违背个人诚信、学术诚信行为者，视情节轻重，给予相应的纪律处分。"},{"id":413,"type":"judge","stem":"实验、实习过程中,违反学校实验室安全管理和实习相关规定,发生安全事故,造成经济损失或者人身伤害的,给予警告或者严重警告处分,情节严重的,给予记过、留校察看或者开除学籍处分。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第十八条实验、实习过程中，违反学校实验室安全管理和实习相关规定，发生安全事故，造成经济损失或者人身伤害的，给予警告或者严重警告处分，情节严重的，给予记过、留校察看或者开除学籍处分。"},{"id":414,"type":"judge","stem":"受到留校察看处分,经教育不改,因无故缺席再次达到纪律处分条件的,给予开除学籍处分。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第十九条对无故缺席不参加教育教学计划规定的活动者，情节严重的，给予如下处分，以一学期为限计算：（一）累计无故缺席10~19学时者，给予警告处分；（二）累计无故缺席20~39学时者，给予严重警告处分；（三）累计无故缺席40~59学时者，给予记过处分；（四）累计无故缺席60~80学时者，给予留校察看处分；（五）受到留校察看处分，经教育不改，因无故缺席再次达到纪律处分条件的，给予开除学籍处分；（六）无故迟到、早退累计3次按无故缺席1学时计算；无故不参加实践教学、军训等活动者，每天按无故缺席6学时计算；未经批准擅自离校，每天按无故缺席6学时计算，累计后给予相应纪律处分。"},{"id":415,"type":"judge","stem":"对无故缺席不参加教育教学计划规定的活动者,情节严重的,应给与一定处分。辅导员及班委有责任做好日常考勤，自入学起算，建个人档案。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第十九条对无故缺席不参加教育教学计划规定的活动者，情节严重的，给予如下处分，以一学期为限计算：（一）累计无故缺席10~19学时者，给予警告处分；（二）累计无故缺席20~39学时者，给予严重警告处分；（三）累计无故缺席40~59学时者，给予记过处分；（四）累计无故缺席60~80学时者，给予留校察看处分；（五）受到留校察看处分，经教育不改，因无故缺席再次达到纪律处分条件的，给予开除学籍处分；（六）无故迟到、早退累计3次按无故缺席1学时计算；无故不参加实践教学、军训等活动者，每天按无故缺席6学时计算；未经批准擅自离校，每天按无故缺席6学时计算，累计后给予相应纪律处分。"},{"id":416,"type":"judge","stem":"考试结束后，应将试卷、答题卡、答题纸一律交予监考老师，草稿纸不做要求。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第二十条对违反考试纪律者的处分：对不遵守考场纪律，不服从考试工作人员的安排与要求，有下列行为之一的，认定为违反考试纪律：（一）未按考场规则就座；（二）携带规定以外的物品进入考场或者未放在指定位置；（三）不按规定自带空白答题纸或者草稿纸；（四）未经监考人员允许借用他人的书、笔记、资料、计算器等物品；（五）考试中东张西望，企图偷看他人试卷，不服从考试工作人员管理；（六）交卷后仍在考场逗留或在考场附近大声喧哗，影响考场秩序；（七）未按规定私自将试卷、答题卡、答题纸、草稿纸等带出考场；（八）其他违反考场规则但尚未构成作弊的行为。对违反考场纪律者，给予严重警告处分，情节严重的，给予记过处分。"},{"id":417,"type":"judge","stem":"携带与考试内容相关的文字材料或者存储有与考试内容相关资料的电子设备参加考试的,给予记过处分,情节严重的,给予留校察看处分。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"……第二十一条（一）携带与考试内容相关的文字材料或者存储有与考试内容相关资料的电子设备参加考试的，给予记过处分，情节严重的，给予留校察看处分；"},{"id":418,"type":"judge","stem":"考试过程中直接或以借用工具书、文具、计算器等方式传接与考试内容相关信息的,给予记过处分,情节严重的,给予留校察看处分。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"……第二十一条（二）考试过程中直接或以借用工具书、文具、计算器等方式传接与考试内容相关信息的，给予记过处分，情节严重的，给予留校察看处分；"},{"id":419,"type":"judge","stem":"故意损毁试卷、答题卡、答题纸等考试材料的,给予记过处分,情节严重的,给予留校察看处分。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"……第二十一条（三）故意损毁试卷、答题卡、答题纸等考试材料的，给予记过处分，情节严重的，给予留校察看处分；"},{"id":420,"type":"judge","stem":"抄袭或者协助他人抄袭试题答案或者与考试内容相关资料的,给予留校察看处分,情节严重的,给予开除学籍处分。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"……第二十一条（四）抄袭或者协助他人抄袭试题答案或者与考试内容相关资料的，给予记过处分，情节严重的，给予留校察看处分；"},{"id":421,"type":"judge","stem":"有盗窃、勒索、诈骗、冒领、侵占公私财物者,给予警告或者严重警告处分,财物价值较大的,给予记过或者留校察看处分,财物价值大并造成严重后果的,给予开除学籍处分。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第二十二条对以各种手段违规占有国家、集体或者个人财物，或有其他盗窃、欺骗行为者，给予如下处分：（一）有盗窃、勒索、诈骗、冒领、侵占公私财物者，给予警告或者严重警告处分，财物价值较大的，给予记过或者留校察看处分，财物价值大并造成严重后果的，给予开除学籍处分；（二）盗用他人（含单位）账号或者各类卡证损害他人（含单位）利益者，给予记过处分，情节严重的，给予留校察看处分；（三）偷窃公章、机密文件、档案等物品者，给予留校察看处分，情节严重的，给予开除学籍处分；（四）有意为他人提供工具或者知情不报者，比违纪人降一级处分；（五）有意协助违纪人保存或销售所得财物者，与违纪人同等处分；（六）陷害他人者，视其情节轻重，给予记过或者留校察看处分。"},{"id":422,"type":"judge","stem":"有意为他人违法违纪提供工具或者知情不报者,与违纪者同等处分。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第二十二条对以各种手段违规占有国家、集体或者个人财物，或有其他盗窃、欺骗行为者，给予如下处分：（一）有盗窃、勒索、诈骗、冒领、侵占公私财物者，给予警告或者严重警告处分，财物价值较大的，给予记过或者留校察看处分，财物价值大并造成严重后果的，给予开除学籍处分；（二）盗用他人（含单位）账号或者各类卡证损害他人（含单位）利益者，给予记过处分，情节严重的，给予留校察看处分；（三）偷窃公章、机密文件、档案等物品者，给予留校察看处分，情节严重的，给予开除学籍处分；（四）有意为他人提供工具或者知情不报者，比违纪人降一级处分；（五）有意协助违纪人保存或销售所得财物者，与违纪人同等处分；（六）陷害他人者，视其情节轻重，给予记过或者留校察看处分。"},{"id":423,"type":"judge","stem":"有意协助违纪人保存或销售所得财物者,与违纪人同等处分。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第二十二条对以各种手段违规占有国家、集体或者个人财物，或有其他盗窃、欺骗行为者，给予如下处分：（一）有盗窃、勒索、诈骗、冒领、侵占公私财物者，给予警告或者严重警告处分，财物价值较大的，给予记过或者留校察看处分，财物价值大并造成严重后果的，给予开除学籍处分；（二）盗用他人（含单位）账号或者各类卡证损害他人（含单位）利益者，给予记过处分，情节严重的，给予留校察看处分；（三）偷窃公章、机密文件、档案等物品者，给予留校察看处分，情节严重的，给予开除学籍处分；（四）有意为他人提供工具或者知情不报者，比违纪人降一级处分；（五）有意协助违纪人保存或销售所得财物者，与违纪人同等处分；（六）陷害他人者，视其情节轻重，给予记过或者留校察看处分。"},{"id":424,"type":"judge","stem":"盗用他人（含单位）账号或者各类卡证损害他人（含单位）利益者,给予记过处分,情节严重的,给予留校察看处分。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第二十二条对以各种手段违规占有国家、集体或者个人财物，或有其他盗窃、欺骗行为者，给予如下处分：（一）有盗窃、勒索、诈骗、冒领、侵占公私财物者，给予警告或者严重警告处分，财物价值较大的，给予记过或者留校察看处分，财物价值大并造成严重后果的，给予开除学籍处分；（二）盗用他人（含单位）账号或者各类卡证损害他人（含单位）利益者，给予记过处分，情节严重的，给予留校察看处分；（三）偷窃公章、机密文件、档案等物品者，给予留校察看处分，情节严重的，给予开除学籍处分；（四）有意为他人提供工具或者知情不报者，比违纪人降一级处分；（五）有意协助违纪人保存或销售所得财物者，与违纪人同等处分；（六）陷害他人者，视其情节轻重，给予记过或者留校察看处分。"},{"id":425,"type":"judge","stem":"故意损坏公物者,应当按价赔偿,并根据损坏公物的价值以及后果的严重程度,给予警告、严重警告或者记过处分,对于后果特别严重的,给予留校察看或者开除学籍处分。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第二十三条故意损坏公物者，应当按价赔偿，并根据损坏公物的价值以及后果的严重程度，给予警告、严重警告或者记过处分，对于后果特别严重的，给予留校察看或者开除学籍处分。"},{"id":426,"type":"judge","stem":"勾结本校学生以外人员到校内打架肇事者,给予留校察看处分,对造成严重后果者,给予开除学籍处分。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"……第二十四条3.勾结本校学生以外人员到校内打架肇事者，给予留校察看处分，对造成严重后果者，给予开除学籍处分。"},{"id":427,"type":"judge","stem":"打人致伤者,给予记过处分,手段恶劣或者致伤严重者,给予留校察看或者开除学籍处分。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"……第二十四条2.打人致伤者，给予记过处分，手段恶劣或者致伤严重者，给予留校察看或者开除学籍处分；"},{"id":428,"type":"judge","stem":"寻衅、报复打人者,按照其情节与打架斗殴相关规定同等处分。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"……第二十四条3.寻衅、报复打人者，加重一级处分；"},{"id":429,"type":"judge","stem":"持械打人、结伙打人者,视情节加重一级处分。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"……第二十四条4.持械打人、结伙打人者，视情节加重一级处分。"},{"id":430,"type":"judge","stem":"对组织及策划打架、打人者造成后果严重者,给予留校察看或者开除学籍处分。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"……第二十四条2.造成后果严重者，给予留校察看或者开除学籍处分。"},{"id":431,"type":"judge","stem":"中间介入或者以“劝架“为名偏袒一方者,给予严重警告处分;导致事态加重或者造成严重后果者,视情节轻重,给予记过或者留校察看处分。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"……第二十四条（四）对打架中间介入者的处分：中间介入或者以“劝架”为名偏袒一方者，给予严重警告处分；导致事态加重或者造成严重后果者，视情节轻重，给予记过、留校察看或者开除学籍处分。"},{"id":432,"type":"judge","stem":"对提供器械供人打架斗殴，造成伤害后果者,视情节轻重,给予记过、留校察看或者开除学籍处分。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"……第二十四条2.造成伤害后果者，视情节轻重，给予记过、留校察看或者开除学籍处分。"},{"id":433,"type":"judge","stem":"酗酒滋事者,给予记过处分,造成严重后果者,给予留校察看或者开除学籍处分。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第二十六条对酗酒滋事、赌博者的处分：（一）酗酒滋事者，给予记过处分，造成严重后果者，给予留校察看或者开除学籍处分；（二）赌博或者变相赌博者，视情节轻重，给予留校察看或者开除学籍处分。"},{"id":434,"type":"judge","stem":"违反作息制度,严重影响他人休息者,给予严重警告处分,屡次违反的,给予记过处分。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第二十七条对违反学生公寓管理规定者的处分：（一）违反作息制度，严重影响他人休息者，给予警告处分，屡次违反的，给予记过处分；（二）未按规定办理手续，擅自在校外租房居住者，给予严重警告处分，经教育仍不改正者，给予记过处分；（三）违反宿舍消防、用电等有关规定者，给予警告或者严重警告处分，引发严重后果者，给予记过、留校察看或者开除学籍处分；（四）其他违反学生公寓管理规定的行为，视情节轻重，给予相应的纪律处分。"},{"id":435,"type":"judge","stem":"未按规定办理手续,擅自在校外租房居住者,给予严重警告处分,经教育仍不改正者,给予记过处分。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第二十七条对违反学生公寓管理规定者的处分：（一）违反作息制度，严重影响他人休息者，给予警告处分，屡次违反的，给予记过处分；（二）未按规定办理手续，擅自在校外租房居住者，给予严重警告处分，经教育仍不改正者，给予记过处分；（三）违反宿舍消防、用电等有关规定者，给予警告或者严重警告处分，引发严重后果者，给予记过、留校察看或者开除学籍处分；（四）其他违反学生公寓管理规定的行为，视情节轻重，给予相应的纪律处分。"},{"id":436,"type":"judge","stem":"违反宿舍消防、用电等有关规定者,给予警告或者严重警告处分,引发严重后果者,给予记过、留校察看或者开除学籍处分。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第二十七条对违反学生公寓管理规定者的处分：（一）违反作息制度，严重影响他人休息者，给予警告处分，屡次违反的，给予记过处分；（二）未按规定办理手续，擅自在校外租房居住者，给予严重警告处分，经教育仍不改正者，给予记过处分；（三）违反宿舍消防、用电等有关规定者，给予警告或者严重警告处分，引发严重后果者，给予记过、留校察看或者开除学籍处分；（四）其他违反学生公寓管理规定的行为，视情节轻重，给予相应的纪律处分。"},{"id":437,"type":"judge","stem":"未经允许,修改、移动、破坏、复制、下载他人或者组织的计算机等设备中的文件或者其他信息,给予警告处分；情节严重的,给予严重警告或者记过处分。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第二十八条对利用计算机、网络等技术手段违纪的处分：（一）未经允许，修改、移动、破坏、复制、下载他人或者组织的计算机等设备中的文件或者其他信息，给予警告或者严重警告处分，情节严重的，给予记过或者留校察看处分；（二）制造、故意传播和应用计算机病毒，或者非法侵入他人或者组织的计算机等设备系统，给予严重警告或者记过处分，情节严重的，给予留校察看或者开除学籍处分；（三）利用计算机网络发表、传播反动、淫秽、暴力、恐怖、邪教等内容的言论、图像、视频者，视情节轻重，给予严重警告、记过、留校察看或者开除学籍处分；（四）在校园网或者其他公共网络平台上发布有损他人形象或者侵犯他人隐私的言论或者图片，给他人或者集体造成不良影响，或发布虚假信息骗取财物者，给予严重警告处分，情节严重的，给予记过或者留校察看处分。"},{"id":438,"type":"judge","stem":"制造、故意传播和应用计算机病毒,或者非法侵入他人或者组织的计算机等设备系统,给予严重警告或者记过处分,情节严重的,给予留校察看或者开除学籍处分。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第二十八条对利用计算机、网络等技术手段违纪的处分：（一）未经允许，修改、移动、破坏、复制、下载他人或者组织的计算机等设备中的文件或者其他信息，给予警告或者严重警告处分，情节严重的，给予记过或者留校察看处分；（二）制造、故意传播和应用计算机病毒，或者非法侵入他人或者组织的计算机等设备系统，给予严重警告或者记过处分，情节严重的，给予留校察看或者开除学籍处分；（三）利用计算机网络发表、传播反动、淫秽、暴力、恐怖、邪教等内容的言论、图像、视频者，视情节轻重，给予严重警告、记过、留校察看或者开除学籍处分；（四）在校园网或者其他公共网络平台上发布有损他人形象或者侵犯他人隐私的言论或者图片，给他人或者集体造成不良影响，或发布虚假信息骗取财物者，给予严重警告处分，情节严重的，给予记过或者留校察看处分。"},{"id":439,"type":"judge","stem":"利用计算机网络发表、传播反动、淫秽、暴力、恐怖、邪教等内容的言论、图像、视频者,视情节轻重,给予严重警告、记过、留校察看或者开除学籍处分。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第二十八条对利用计算机、网络等技术手段违纪的处分：（一）未经允许，修改、移动、破坏、复制、下载他人或者组织的计算机等设备中的文件或者其他信息，给予警告或者严重警告处分，情节严重的，给予记过或者留校察看处分；（二）制造、故意传播和应用计算机病毒，或者非法侵入他人或者组织的计算机等设备系统，给予严重警告或者记过处分，情节严重的，给予留校察看或者开除学籍处分；（三）利用计算机网络发表、传播反动、淫秽、暴力、恐怖、邪教等内容的言论、图像、视频者，视情节轻重，给予严重警告、记过、留校察看或者开除学籍处分；（四）在校园网或者其他公共网络平台上发布有损他人形象或者侵犯他人隐私的言论或者图片，给他人或者集体造成不良影响，或发布虚假信息骗取财物者，给予严重警告处分，情节严重的，给予记过或者留校察看处分。"},{"id":440,"type":"judge","stem":"在校园网或者其它公共网站上发布有损他人形象或者侵犯他人隐私的言论或者图片,给他人或者集体造成不良影响,或发布虚假信息骗取财物者,给予严重警告处分,情节严重给予记过或者留校察看处分。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第二十八条对利用计算机、网络等技术手段违纪的处分：（一）未经允许，修改、移动、破坏、复制、下载他人或者组织的计算机等设备中的文件或者其他信息，给予警告或者严重警告处分，情节严重的，给予记过或者留校察看处分；（二）制造、故意传播和应用计算机病毒，或者非法侵入他人或者组织的计算机等设备系统，给予严重警告或者记过处分，情节严重的，给予留校察看或者开除学籍处分；（三）利用计算机网络发表、传播反动、淫秽、暴力、恐怖、邪教等内容的言论、图像、视频者，视情节轻重，给予严重警告、记过、留校察看或者开除学籍处分；（四）在校园网或者其他公共网络平台上发布有损他人形象或者侵犯他人隐私的言论或者图片，给他人或者集体造成不良影响，或发布虚假信息骗取财物者，给予严重警告处分，情节严重的，给予记过或者留校察看处分。"},{"id":441,"type":"judge","stem":"以暴力、威胁、贿赂等方式干扰证人作证或者指使他人作伪证者,视情节轻重,给予记过、留校察看或者开除学籍处分。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第二十九条对干扰违纪行为调查者的处分：（一）包庇、纵容违纪人员，造成不良影响者，给予严重警告处分；（二）作伪证，或者帮助违纪人员毁灭证据，给调查造成困难者，视情节轻重，给予严重警告或者记过处分；（三）以暴力、威胁、贿赂等方式干扰证人作证或者指使他人作伪证者，视情节轻重，给予记过、留校察看或者开除学籍处分。"},{"id":442,"type":"judge","stem":"处分告知书及处分决定书,应当直接送达学生本人,学生拒绝签收的,以本人拒收的实际情况记录作知情送达处理。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第三十六条处分告知书及处分决定书，应当直接送达学生本人，学生拒绝签收的，以留置方式送达；已离校的，采取邮寄方式送达；难于联系的，利用学校网站、新闻媒体等以公告方式送达。"},{"id":443,"type":"judge","stem":"已离校的,采取邮寄的方式送达处分告知书及处分决定书，难于联系的,利用学校网站、新闻媒体等以公告方式送达。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第三十六条处分告知书及处分决定书，应当直接送达学生本人，学生拒绝签收的，以留置方式送达；已离校的，采取邮寄方式送达；难于联系的，利用学校网站、新闻媒体等以公告方式送达。"},{"id":444,"type":"judge","stem":"学生在处分期间内表现良好,未再发生违纪行为的,处分期满后,由本人申请,学院（部）审核,主管部门召开专门会议审议批准,可予以解除,并以书面形式通知本人。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第三十七条学生在处分期间内表现良好，未再发生违纪行为的，处分期满后，由本人申请，学院（部）审核，主管部门召开专门会议审议批准，可予以解除，并以书面形式通知本人。"},{"id":445,"type":"judge","stem":"受处分学生因表现良好解除处分的，其处分及解除处分材料不归入学校文书档案和本人档案。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"《中国石油大学（华东）学生纪律处分规定》","category":"学生纪律处分","excerpt":"第四十一条处分决定、解除处分决定自下达之日起生效。学生的处分及解除处分材料归入学校文书档案和本人档案。第五章附则第四十二条我校保留学籍赴校外参加校际交流或联合培养的学生，在交流期间发生违纪行为的，参照本规定执行；若所在校际交流或联合培养的单位已给予处分的，我校不再追加处分。在我校借读的、进修的学生，在借读或进修期间发生违纪行为的，视情况参照本规定执行或将违纪情况反馈至其单位。"},{"id":446,"type":"judge","stem":"学生心理健康教育中心的每一位心理咨询老师,将以真诚的心,接纳,尊重每一位来访的学生,中心遵循为来访者保密的原则。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"《心理咨询来访者须知》","category":"心理咨询","excerpt":"3.中心的每一位心理咨询老师，将以真诚的心，接纳、尊重每一位来访的学生。中心遵循为来访者保密的原则。"},{"id":447,"type":"judge","stem":"根据“第二课堂成绩单”制度要求，若第二课堂学分在毕业前不能满足毕业要求，能按时正常毕业。","options":[["A","对"],["B","错"]],"answer":["B"],"source":"中国石油大学(华东)“第二课堂成绩单实施细则”","category":"自主发展计划","excerpt":"……第四条第二章课程设置第五条“第二课堂成绩单”制度设置的5类课程具体为："},{"id":448,"type":"judge","stem":"早进实验室、早进团队、早进项目, 为优秀生继续深造提供发展平台,学校决定实施优秀本科生“ 三进提”升计划","options":[["A","对"],["B","错"]],"answer":["A"],"source":"优秀本科生\"三进\"提升计划实施办法","category":"三进提升计划","excerpt":""},{"id":449,"type":"judge","stem":"对于“三进”培养周期的考核合格的优秀生，可获得自主发展计划创新创业类2学分","options":[["A","对"],["B","错"]],"answer":["A"],"source":"优秀本科生\"三进\"提升计划实施办法","category":"三进提升计划","excerpt":""},{"id":450,"type":"judge","stem":"对于“三进”培养周期的考核合格的优秀生，在满足学校推荐免试研究生基本条件基础上, 培养周期考核合格的优秀生,管理院部研究生推免领导小组同意,可获得推荐免试研究生资格。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"优秀本科生\"三进\"提升计划实施办法","category":"三进提升计划","excerpt":""},{"id":451,"type":"judge","stem":"获国家级银奖（一等奖） 的项目,团队成员本科生中排前3,经审核认定做出重要贡献者,可获得推荐免试攻读研究生资格","options":[["A","对"],["B","错"]],"answer":["A"],"source":"本科生学科竞赛管理办法","category":"学科竞赛","excerpt":""},{"id":452,"type":"judge","stem":"获省级金奖（ 特等奖） 的项目, 本科生作为项目负责人, 可获得推荐免试攻读研究生资格","options":[["A","对"],["B","错"]],"answer":["A"],"source":"本科生学科竞赛管理办法","category":"学科竞赛","excerpt":""},{"id":453,"type":"judge","stem":"对在创新创业实践活动中取得优秀成绩的本科生,学校给予自主发展计划学分认定、综合素质测评加分、同层次成果 认定等奖励,并在研究生“推免”工作中予以政策倾斜。","options":[["A","对"],["B","错"]],"answer":["A"],"source":"本科生学科竞赛管理办法","category":"学科竞赛","excerpt":""},{"id":454,"type":"multi","stem":"“第二课堂成绩单”制度设置的课程具体为：","options":[["A","思想成长类"],["B","创新创业类"],["C","社会实践与志愿服务类"],["D","文体发展类"],["E","工作履历与技能培训类"]],"answer":["A","B","C","D","E"],"source":"中国石油大学(华东)“第二课堂成绩单实施细则”","category":"自主发展计划","excerpt":"……第四条（一）思想成长类，主要包括理想信念教育、入党入团集中培训、党团主题教育、爱校荣校主题教育、爱国主义教育、青马工程、就业价值观教育等各类思想政治引领活动。（二）创新创业类，主要包括各级各类创新创业竞赛、学科竞赛、学术报告、课题研究、专利申请等。（三）社会实践与志愿服务类，主要包括“三下乡”社会实践、校内外单位实习锻炼、社会调查与研究以及校内志愿服务岗、校外社区志愿服务等各类志愿服务活动。（四）文体发展类，主要包括文化、艺术、体育、心理健康等各级各类活动。（五）工作履历与技能培训类，主要包括在校内党、团、学组织的工作任职和参加各类职业生涯教育辅导、国际交流项目辅导、技能培训及取得相应资格认证情况。"},{"id":455,"type":"multi","stem":"大学生创业基金主要来源于（）","options":[["A","学校拨款"],["B","个人储蓄"],["C","社会捐赠"],["D","创业项目自身投资收益"]],"answer":["A","C","D"],"source":"中国石油大学(华东)大学生创业实践管理办法","category":"创新创业","excerpt":"第七条基地管理服务：1.入驻的项目由办公室统一管理，应定期向办公室提交项目运行情况报告，并接受中期检查和期满验收考核。2.入驻的项目可免缴场地租用费，免费享受创业培训、创业指导等服务，免费参加创业经验交流等活动。3.入驻的项目提前退出时，须提前提出书面申请，报办公室审核后，办理退出手续。第四章创业基金第八条创业基金主要来源于学校拨款、社会捐赠及创业项目自身投资收益。"},{"id":456,"type":"fillin","stem":"学校于（　）年建校，时称北京石油学院，（　）年迁校山东，改称华东石油学院。（　）年，学校更名为石油大学。（　）年1月，学校更名为中国石油大学。","options":[],"answer":[["1953"],["1969"],["1988"],["2005"]],"source":"《学校概况》校史","note":"","category":"学校概况","excerpt":"追溯学校历史，1953年新中国成立之初，国民经济建设急需石油资源，石油工业发展急需专业人才。在这种形势下，以清华大学石油工程系为基础，汇聚北京大学、天津大学、大连工学院等著名高校的相关师资力量和办学条件，组建成立了新中国第一所石油高等学府———北京石油学院，隶属燃料工业部，是当时北京著名的八大学院之一。1960年10月，学校被确定为全国重点高校。1969年，学校迁至胜利油田所在地———山东东营，更名为华东石油学院。1981年6月在北京石油学院原校址内成立研究生部。1988年，学校更名为石油大学，逐步形成山东、北京两地办学格局。1997年，石油大学正式进入国家“211工程”首批重点建设高校行列。2000年，石油大学由中国石油天然气集团公司划归教育部。2000年6月，经教育部批准，学校成立研究生院。2003年10月，教育部与国家四大石油公司签署共建石油大学协议。2004年8月，教育部批准石油大学（华东）立项建设青岛校区。2005年1月，学校更名为中国石油大学。2005年8月，教育部与山东省人民政府签署共建中国石油大学（华东）协议。"},{"id":457,"type":"fillin","stem":"除开除学籍处分以外，给予学生处分设置一定期限：警告处分期限为（　）个月，严重警告处分期限为（　）个月，记过处分期限为（　）个月，留校察看处分期限为（　）个月。","options":[],"answer":[["6","六"],["8","八"],["10","十"],["12","十二"]],"source":"《中国石油大学（华东）学生纪律处分规定》","note":"","category":"学生纪律处分","excerpt":"第六条除开除学籍处分以外，给予学生处分设置一定期限，警告处分期限为6个月，严重警告处分期限为8个月，记过处分期限为10个月，留校察看处分期限为12个月，处分期限从处分决定下达之日起计算。受纪律处分的学生，其处分期限可减至退学或者毕业等离校日止。"},{"id":458,"type":"fillin","stem":"修读双学位的学生，获得主修专业学位但达不到双学位专业和教学培养方案要求的，低于（　）学分者，其所修双学位课程作为通识教育选修课记入《中国石油大学（华东）学生成绩记载表》。","options":[],"answer":[["30","30学分"]],"source":"《中国石油大学（华东）本科生双学位培养管理办法》","note":"","category":"双学位与辅修","excerpt":""},{"id":459,"type":"fillin","stem":"修读双学位的学生，获得主修专业学位但达不到双学位专业和教学培养方案要求的，若所修双学位课程的总学分（　）学分者，颁发辅修专业证书。","options":[],"answer":[["≥25","25","达到25","不少于25"]],"source":"《中国石油大学（华东）本科生双学位培养管理办法》","note":"题库单选第25题：总学分≥25学分者颁发辅修专业证书。","category":"双学位与辅修","excerpt":""},{"id":460,"type":"fillin","stem":"辅修专业培养方案由辅修专业开设院部制定，所设课程应是本专业基础课程和专业课，总学分一般为（　）左右。","options":[],"answer":[["30","30学分"]],"source":"《中国石油大学（华东）本科生辅修培养管理办法》","note":"（原整理标注答案为30）","category":"双学位与辅修","excerpt":""},{"id":461,"type":"fillin","stem":"对于可以优先推荐免试攻读硕士研究生的优异生的数量约占本年级在校生总数的（　）左右。","options":[],"answer":[["3%","0.03","3％","百分之三"]],"source":"《本科生优异生培养实施办法》","note":"","category":"其他","excerpt":""},{"id":462,"type":"fillin","stem":"独立设置的实验（上机）课程，缺做实验（　）或缺交实验报告（　）及以上者，成绩以零分记载。","options":[],"answer":[["1/3","三分之一","1／3"],["1/3","三分之一","1／3"]],"source":"《中国石油大学（华东）本科实验教学管理办法》","note":"记住关键数据 1/3 以上，成绩以 0 分记载。","category":"实验教学与实习","excerpt":"第十九条独立设置的实验（上机）课程，缺做实验1/3或缺交实验报告1/3及以上者，成绩以零分记载。"},{"id":463,"type":"fillin","stem":"建校近70年来，学校形成了鲜明的办学特色。在新的历史时期，学校坚持特色发展、内涵发展、高质量发展，正向着“（　）”的办学目标奋力迈进。","options":[],"answer":[["中国特色石油领域中国一流大学"]],"source":"《学校概况》","note":"别写少字了。","category":"学校概况","excerpt":""},{"id":464,"type":"fillin","stem":"学分学费按学生修读学分计收，学分收费标准为每学分（　）元。","options":[],"answer":[["100","100元","一百"]],"source":"《中国石油大学（华东）学分制收费管理暂行办法》","note":"","category":"学分制收费","excerpt":""},{"id":465,"type":"fillin","stem":"我校现有在校本科生近（　）人，研究生7000余人，留学生1100余人。","options":[],"answer":[["19000","19000人","1.9万","近19000"]],"source":"《学校概况》","note":"","category":"学校概况","excerpt":"学校教育体系完备，各类教育层次结构合理，现有全日制在校本科生19000余人、研究生11000余人，留学生800余人。建校以来，学校始终坚持以立德树人为根本任务，着力打造人才培养质量品牌，赢得了广泛的社会声誉。建有国家级实验教学示范中心4个、国家级工程实践教育中心3个、国家级虚拟仿真实验教学中心3个、教育部虚拟教研室5个，获批国家级一流本科专业32个、国家级一流课程64门。从广大校友中涌现出大批杰出人才，走出了32位两院院士以及一大批石油石化行业领军人物和工程技术骨干。2004年被国务院授予“全国就业先进工作单位”荣誉称号，2011年入选50所全国毕业生就业典型经验高校，2019年入选“国家创新人才培养示范基地”，2021年入选“国家首批特色化示范性软件学院”，2022年入选国家级创新创业教育实践基地，2024年入选教育部涉外法治人才协同培养创新基地。"},{"id":466,"type":"fillin","stem":"在中国国际“互联网+”大学生创新创业大赛获得金奖、银奖、铜奖，分别获得奖金（　）。","options":[],"answer":[["5万、3万、1万","50000、30000、10000","5万/3万/1万","50000/30000/10000","5万，3万，1万"]],"source":"《中国石油大学（华东）本科生创新成果奖励办法》","note":"金奖5万、银奖3万、铜奖1万。","category":"学科竞赛","excerpt":""},{"id":467,"type":"fillin","stem":"学生免修课程应向所在院部提出书面申请，院部主管领导批准，经过考核，成绩达到（　）分以上，取得该课程学分。","options":[],"answer":[["70","70分","七十分"]],"source":"《中国石油大学（华东）本科生学籍管理规定》","note":"判断题如果说“及格及以上取得该学分”就是错的，必须要70分以上。","category":"学籍管理","excerpt":""},{"id":468,"type":"fillin","stem":"学生申请学分认定，应于每学期初（　）向所在院（部）提出申请，并提供能体现创新创业实践过程及成果的支撑材料，经院（部）创新创业教育领导小组认定、学校创新创业教育工作领导小组办公室审定后，报学校备案。","options":[],"answer":[["3周内","三周内","3周","前三周"]],"source":"《中国石油大学（华东）本科生创新创业学籍管理办法（试行）》","note":"","category":"创新创业","excerpt":"第十一条学生申请学分认定，应于每学期初3周内向所在院（部）提出申请，并提供能体现创新创业实践过程及成果的支撑材料，经院（部）创新创业教育领导小组认定、学校创新创业教育工作领导小组办公室审定后，报学校备案。必要时，由学校组织专家论证，通过者取得相应学分。因创业休学，未按时申请学分认定的，可复学后提出申请。"},{"id":469,"type":"fillin","stem":"学生对学校的处分决定有异议的，应在接到学校处分决定书之日起（　）日内，向学校学生申诉处理委员会提出书面申诉。","options":[],"answer":[["10","10日","十日"]],"source":"《中国石油大学（华东）学生申诉处理办法》","note":"","category":"申诉处理","excerpt":"第六条申诉委设秘书处作为其常设机构，专门负责受理学生提出的申诉，整理相关材料，召集申诉委会议。秘书处不参加复查处理决定的审议。秘书处办公室设在学校监察处。第三章申诉程序第七条学生对学校的处理或者处分决定有异议的，可以在接到学校处理或者处分决定书之日起10日内，向申诉委秘书处提出书面申诉，并附带相关材料。"},{"id":470,"type":"fillin","stem":"国家助学贷款本专科生每人每年最高不超过（　）元。","options":[],"answer":[["8000","8000元","八千"]],"source":"《国家助学贷款管理规定》","note":"","category":"奖学金与资助","excerpt":""},{"id":471,"type":"fillin","stem":"凡结课（含免修）考核不及格的课程，可通过重新选课修读或补考取得该课程的学分。考核成绩合格但成绩不理想的课程，也可重新选课修读。在学校规定的最长学习年限内，重新选课修读（　）。","options":[],"answer":[["不限制次数","不限次数","不限制"]],"source":"《中国石油大学（华东）本科生学籍管理规定》","note":"","category":"学籍管理","excerpt":"第十七条凡结课（含免修）考核不及格的课程，可通过重新选课修读或补考取得该课程的学分。考核成绩合格，但成绩不理想的课程，也可重新选课修读。1.在学校规定的最长学习年限内，重新选课修读不限制次数，所有修读成绩均如实记载；2.补考时间为每学期的开学初，补考课程为前一学期考核不及格的必修或限选课程，且申请补考的课程成绩必须达50分（含）以上；3.实验课程、实习实训、毕业设计等实践性教学环节以及无结课考核环节的课程不能补考；4.学生补考及格获得该课程学分，补考不及格须重新选课修读。"},{"id":472,"type":"fillin","stem":"学校本科专业标准学制四年（建筑学专业学制五年），实行学分制管理和弹性学习年限，学生可在标准学制的基础上（　）或（　）毕业。","options":[],"answer":[["提前1年","提前一年","提前","提前1-2年"],["延长2年","延长两年","延长","推迟2年","推迟"]],"source":"《中国石油大学（华东）本科生学籍管理规定》","note":"原整理答案为“1、2”（提前1年/延长2年）。建筑学专业可延长至…以学籍管理规定为准。","category":"学籍管理","excerpt":""},{"id":473,"type":"fillin","stem":"受资助项目如有盈利，根据项目收益情况，将项目净利润的（　）%上交学校大学生创业基金，用以滚动支持更多创业项目。","options":[],"answer":[["5","5%","百分之五"]],"source":"《中国石油大学（华东）大学生创业实践管理办法》","note":"","category":"创新创业","excerpt":"第十一条基金运作管理：1.受资助的项目应定期向办公室提交基金使用情况的财务报告和项目运行情况报告，并接受中期检查和期满验收考核。2.受资助的项目因客观原因需对目标、进度和经费等进行调整时，应向办公室提出书面申请，经审核通过方可执行。3.受资助的项目提前退出时，须提前提出书面申请，报办公室审核后，办理清算核销手续。4.受资助项目如有盈利，根据项目收益情况，将项目净利润5%上交学校大学生创业基金，用以滚动支持更多创业项目。第五章扶持政策第十二条办公室负责与政府、企业、校友联系，为大学生创业项目争取场地、技术、资金等扶持政策。"},{"id":474,"type":"fillin","stem":"学生结业后（　）之内回校完成相关课程修读，达到本科培养方案规定的学分要求的，学校准予毕业，符合学士学位授予标准的，授予学士学位。","options":[],"answer":[["1年","一年","1"]],"source":"《中国石油大学（华东）本科生学籍管理规定》","note":"","category":"学籍管理","excerpt":"第四十六条学生毕业时未修满本科培养方案规定的学分要求，可申请延长学习年限或结业。1.延长学习年限（1）延长学习年限应由学生本人提出申请，所在院部审核批准后报教务处备案，但其累计在校时间不能超过学校规定的最长学习年限；（2）延长学习年限的学生，享受在校生待遇。2.结业（1）毕业时累计欠本科培养方案规定的学分要求15学分以内（含15学分）的学生，经本人申请，所在院部审核，学校批准后，可办理结业手续；（2）学生结业后1年之内回校完成相关课程修读，达到本科培养方案规定的学分要求的，学校准予毕业，符合学士学位授予标准的，授予学士学位。合格后颁发的毕业证书、学位证书，毕业时间、获学位时间按发证日期填写；（3）学生结业1年后仍未达到本科培养方案规定的学分要求的，不再换发毕业证书。"},{"id":475,"type":"fillin","stem":"专业注册学费是指以不同专业的（　）为基础，对不同专业收取的年度学费。","options":[],"answer":[["生均培养成本"]],"source":"《中国石油大学（华东）学分制收费管理暂行办法》","note":"","category":"学分制收费","excerpt":"第四条本办法所称学分制收费，是按照专业注册学费和学分学费两部分计收学费的收费管理制度。学分制收费执行政府定价或政府指导价。第二章收费项目及标准第五条专业注册学费是学生进行专业学习注册取得专业课程选修资格需缴纳的费用。专业注册学费由学校按照不同专业生均培养成本等因素合理确定。专业注册学费按学年计收。学校在每学年初向学生收取专业注册学费，为学生办理专业注册手续，授予学生本学年选课资格。学校按照学生实际修业年限收取专业注册学费。"},{"id":476,"type":"fillin","stem":"已知英语（4-2）3学分，数学（2-2）5学分，军事理论1学分，小李同学英语、数学、军理的成绩分别是85、98、91，那么小李同学的这三门功课的专业学习测评成绩绩点为（　）。","options":[],"answer":[["4.29","约4.29"]],"source":"《中国石油大学（华东）学生综合素质测评办法》","note":"计算方法：85/10-5=3.5，98/10-5=4.8，91/10-5=4.1，（3.5×3+4.8×5+4.1×1）/（3+5+1）≈4.29。","category":"综合素质测评","excerpt":""},{"id":477,"type":"fillin","stem":"凡我校本科生在取得本专业培养计划规定学分的同时，还需至少取得（　）个自主发展计划学分。","options":[],"answer":[["10","10个","十"]],"source":"《中国石油大学（华东）本科生自主发展计划》","note":"","category":"自主发展计划","excerpt":""},{"id":478,"type":"fillin","stem":"创业基金初期拨付资助金额的（　）。","options":[],"answer":[["50%","0.5","50％","一半","百分之五十"]],"source":"《中国石油大学（华东）大学生创业实践管理办法》","note":"","category":"创新创业","excerpt":"第十条基金资助程序：1.项目申报。实行集中申报和评审，项目负责人向办公室提出申请，并提交创业基金申请表、项目可行性研究报告等材料。2.项目遴选。办公室对项目进行初审，并组织相关专家组成评审组对通过初审的项目进行评审，评审过程采用公开答辩的形式。根据评审意见，拟定资助额度。3.项目资助。项目负责人与办公室签订资助协议。基金资助期原则上为一年，初期拨付资助金额的50%，经中期检查通过后，拨付剩余资助金额的50%。"},{"id":479,"type":"fillin","stem":"优良学风班分为优良学风班、优良学风标兵班，奖励标准分别为（　）元/班。","options":[],"answer":[["1000、3000","1000/3000","1000，3000","1000和3000"]],"source":"《中国石油大学（华东）优良学风班评选办法》","note":"优良学风班1000元/班，优良学风标兵班3000元/班。","category":"优良学风班","excerpt":""},{"id":480,"type":"fillin","stem":"评选优良学风班需具备的条件之一是：全班学生学习效果显著，各门必修课程考试及格率达（　）。","options":[],"answer":[["95%","0.95","95％","百分之九十五"]],"source":"《中国石油大学（华东）优良学风班评选办法》","note":"","category":"优良学风班","excerpt":"二、评选标准1.评选优良学风班需具备以下条件：（1）全班学生政治思想状况良好，拥护党的路线、方针、政策；（2）全班学生学习态度端正，学习目的明确，学习气氛浓厚；（3）全班学生遵守法纪，遵守《高等学校学生行为准则》和学校的各项规章制度；（4）班集体凝聚力强，开展集体活动效果良好；（5）全班学生学习效果显著：各门必修课程考试及格率达95%，优良率达60%，各种竞赛成绩和课外科技活动成果突出。2.优良学风标兵班从优良学风班中选出。3.符合以下任一项者不得申报或取消其当年评选资格：（1）凡班级有学生在评选当年受到学校处分者；（2）凡班级申报材料弄虚作假者，一经发现，取消其评奖资格，并不得参加下一年度的申报。"},{"id":481,"type":"fillin","stem":"组织能力奖学金、文艺特长及体育优胜奖学金的评选比例不超过（　）。","options":[],"answer":[["10%","0.1","10％","百分之十"]],"source":"《中国石油大学（华东）学生奖学金管理细则》","note":"","category":"奖学金与资助","excerpt":"……第五条奖励标准：该奖项分为三个等级：一等奖学金4000元/人，按学生数的3%评定；二等奖学金2000元/人，按学生数的7%评定；三等奖学金1000元/人，按学生数的15%评定。评选要求：参评学生应为二年级以上（含二年级）学生。各院部严格按照《中国石油大学（华东）学生综合素质测评办法》的标准，对学生进行综合素质测评。4.企事业奖学金奖励对象：奖励品学兼优，综合素质全面发展，符合设奖单位（个人）评选要求的学生。奖励标准：奖励标准和奖励名额由学校与设奖单位（个人）协商确定。评选要求：各院部按照设奖单位（个人）的评选要求进行评定。以上四类综合奖学金不可兼得。（二）单项奖学金1.学习优秀奖学金奖励对象：奖励当学年学习成绩特别优秀的学生。奖励标准：2000元/人。评选要求：参评学生应为二年级以上（含二年级）学生，当学年专业学习测评排名在专业年级前10%，且未获得综合奖学金。2.社会工作奖学金奖励对象：奖励在各学生团体以及学校各类活动中有较强工作能力和服务意识，且成绩突出的学生。奖励标准：1000元/人，按学生数的10%评定。"},{"id":482,"type":"fillin","stem":"学生毕业时，按照多退少补原则结算学费，学生实际修读学分超过所属专业毕业要求总学分（　），应补交超出的学分学费。","options":[],"answer":[["5学分（不含）以上",">5学分","＞5学分","超过5学分","5学分以上"]],"source":"《中国石油大学（华东）学分制收费管理暂行办法》","note":"超过毕业要求总学分5学分（不含）以上。","category":"学分制收费","excerpt":""},{"id":483,"type":"fillin","stem":"国家励志奖学金申请学生当学年基础性素质测评等级至少为（　）。","options":[],"answer":[["B","B级","b"]],"source":"《中国石油大学（华东）学生奖学金管理细则》","note":"","category":"奖学金与资助","excerpt":"第三条品行端正，诚实守信，当学年基础性素质测评等级为“B”及以上。"},{"id":484,"type":"fillin","stem":"“三进”计划原则上面向（　）年级本科生，秋季学期组织，每年选拔300~500名。","options":[],"answer":[["二","2","大二"]],"source":"《优秀本科生“三进”提升计划实施办法》","note":"","category":"三进提升计划","excerpt":"第八条学校每三年开展一次科研团队评估和动态调整工作。第四章学生选拔第九条坚持“早选拔、早培养、早成才”思路，优秀生选拔原则上面向二年级本科生（建筑学专业三年级），秋季学期组织，每年选拔300~500名。"},{"id":485,"type":"fillin","stem":"“三进”提升计划优秀生培养周期为（　）年。","options":[],"answer":[["2","二","两年","2年"]],"source":"《优秀本科生“三进”提升计划实施办法》","note":"","category":"三进提升计划","excerpt":"第十一条科研团队负责人所在院部为该计划实施归口管理院部。学校根据科研团队数量和学生申请情况对归口管理院部选拔指标进行分配，每个科研团队当年接收优秀生原则上不超过3名，具体选拔流程如下：1.学生提出申请，经所在学院同意，报归口管理院部。2.归口管理院部组建不少于5人的专家组，对学生进行面试选拔，确定推荐名单。3入选学生与科研团队按照“双向选择”原则，经双方同意后，相关材料报大学生创新创业教育工作领导小组办公室。4.学校大学生创新创业教育工作领导小组对优秀生选拔结果进行审批并公布。第五章组织管理第十二条优秀生培养周期一般为2年。"},{"id":486,"type":"fillin","stem":"学生综合素质测评工作分（　）、班级测评、（　）、院部复核和学校审批五个步骤进行。","options":[],"answer":[["个人自评"],["年级测评"]],"source":"《中国石油大学（华东）学生综合素质测评办法》","note":"","category":"综合素质测评","excerpt":"……第七条第三章测评流程第八条学生综合素质测评工作分个人自评、班级测评、年级测评、院部复核和学校审批五个步骤进行。（一）个人自评：学生根据自己日常表现，向班级测评小组提交相关证明材料。（二）班级测评：班级测评小组据实做好每名学生的专业学习、基础性素质和发展性素质测评工作。其中，基础性素质成绩根据记实和评议得出；发展性素质成绩根据学生所获荣誉、奖励及实际参加各类活动情况记实得出。（三）年级测评：辅导员带领班长审核班级测评成绩，进行年级专业排名，并向院部学生综合素质测评工作小组提交测评结果。"},{"id":487,"type":"fillin","stem":"创业基金资助期原则上为（　）年。","options":[],"answer":[["一","1","一年","1年"]],"source":"《中国石油大学（华东）大学生创业实践管理办法》","note":"","category":"创新创业","excerpt":"第十条基金资助程序：1.项目申报。实行集中申报和评审，项目负责人向办公室提出申请，并提交创业基金申请表、项目可行性研究报告等材料。2.项目遴选。办公室对项目进行初审，并组织相关专家组成评审组对通过初审的项目进行评审，评审过程采用公开答辩的形式。根据评审意见，拟定资助额度。3.项目资助。项目负责人与办公室签订资助协议。基金资助期原则上为一年，初期拨付资助金额的50%，经中期检查通过后，拨付剩余资助金额的50%。"},{"id":488,"type":"fillin","stem":"对提供器械供人打架斗殴，未造成伤害后果者，给予（　）处分。","options":[],"answer":[["警告"]],"source":"《中国石油大学（华东）学生纪律处分规定》","note":"","category":"学生纪律处分","excerpt":"……第二十四条1.用语言污辱或者用其他方式触及他人，引起事端或者激化矛盾者，给予警告处分；2.引起打架后果者，给予严重警告处分；3.勾结本校学生以外人员到校内打架肇事者，给予留校察看处分，对造成严重后果者，给予开除学籍处分。（二）对打人者的处分：1.动手打人未造成伤害者，给予严重警告处分；2.打人致伤者，给予记过处分，手段恶劣或者致伤严重者，给予留校察看或者开除学籍处分；3.寻衅、报复打人者，加重一级处分；4.持械打人、结伙打人者，视情节加重一级处分。（三）对组织及策划打架、打人者的处分：1.造成后果较轻者，给予记过处分；2.造成后果严重者，给予留校察看或者开除学籍处分。（四）对打架中间介入者的处分：中间介入或者以“劝架”为名偏袒一方者，给予严重警告处分；导致事态加重或者造成严重后果者，视情节轻重，给予记过、留校察看或者开除学籍处分。（五）对提供器械者的处分：1.未造成伤害后果者，给予警告处分；"},{"id":489,"type":"fillin","stem":"1980年后出版的中文图书直接赔款是按照原价的（　）赔偿。","options":[],"answer":[["3-5倍","3~5倍","3—5倍","3倍至5倍"]],"source":"《中国石油大学（华东）图书馆借阅规定》","note":"","category":"图书馆","excerpt":""},{"id":490,"type":"fillin","stem":"学生费用清缴次序为（　）。①代收费；②专业注册学费；③住宿费；④学分学费。","options":[],"answer":[["①③②④","1324","1-3-2-4","代收费、住宿费、专业注册学费、学分学费"]],"source":"《中国石油大学（华东）学分制收费管理暂行办法》","note":"","category":"学分制收费","excerpt":""},{"id":491,"type":"fillin","stem":"学习进步奖学金奖励标准是800元/人，奖励专业学习测评成绩排名较上学年进步达到（　）%的学生。","options":[],"answer":[["30","30%","百分之三十"]],"source":"《中国石油大学（华东）学生奖学金管理细则》","note":"","category":"奖学金与资助","excerpt":""},{"id":492,"type":"fillin","stem":"按照每生每（　）元的标准，给予科研团队优秀生培养经费资助，主要用于优秀生培养。","options":[],"answer":[["3000-5000","3000~5000","3000—5000","3000至5000"]],"source":"《优秀本科生“三进”提升计划实施办法》","note":"","category":"三进提升计划","excerpt":""},{"id":493,"type":"fillin","stem":"保留入学资格由新生本人提出书面申请，并附相关证明材料（因病需提交校医院或校医院指定的二级甲等以上医院诊断证明），经学校批准，可保留入学资格（　）。保留入学资格期间不具有学籍。","options":[],"answer":[["1年","一年","1"]],"source":"《中国石油大学（华东）本科生学籍管理规定》","note":"","category":"学籍管理","excerpt":"第六条新生因患病或者其他正当理由的，可申请保留入学资格。保留入学资格由新生本人提出书面申请，并附相关证明材料（因病需提交校医院或校医院指定的二级甲等以上医院诊断证明），经学校批准，可保留入学资格1年。保留入学资格期间不具有学籍。新生保留入学资格期满前应向学校申请入学，因病保留入学资格者须同时提交校医院或校医院指定的二级甲等以上医院出具的病愈证明，经学校审查合格后，办理入学手续。审查不合格的，取消入学资格；逾期不办理入学手续且未有因不可抗力延迟等正当理由的，视为放弃入学资格。"},{"id":494,"type":"fillin","stem":"学生参加勤工助学不应当影响学业，原则上每周不超过（　）小时，每月不超过（　）小时。","options":[],"answer":[["8","八"],["40","四十"]],"source":"《学生勤工助学管理办法》","note":"","category":"奖学金与资助","excerpt":"第十条校内勤工助学岗位既要满足学生需求，又要保证学生不因参加勤工助学而影响学习。学生参加勤工助学的时间原则上每周不超过8小时，每月不超过40小时。寒暑假勤工助学时间可根据学校的具体情况适当延长。"},{"id":495,"type":"fillin","stem":"各院部选拔优异生要全面考虑，好中选优，选拔的数量约占本年级在校生总数的（　）左右。","options":[],"answer":[["3%","0.03","3％","百分之三"]],"source":"《本科生优异生培养实施办法》","note":"","category":"其他","excerpt":""},{"id":496,"type":"fillin","stem":"服务时间累计60小时以上者，计（　）学分。","options":[],"answer":[["2","二","2学分"]],"source":"《中国石油大学（华东）本科生自主发展计划》","note":"","category":"自主发展计划","excerpt":""},{"id":497,"type":"fillin","stem":"心理咨询服务的时间为每周一至周五的（　）。","options":[],"answer":[["上午8:00-12:00，下午14:00-17:30","上午8：00-12：00，下午14：00-17：30","8:00-12:00和14:00-17:30","上午8:00—12:00、下午14:00—17:30"]],"source":"《心理咨询来访者须知》","note":"","category":"心理咨询","excerpt":""}];
